window.LBODY = {"L07":[{"pts":["النمو **تغيّر تقدمي منظّم** في جوانب متكاملة: جسمية وعقلية وانفعالية ولغوية واجتماعية وأخلاقية؛ ومنه **التكويني** وهو زيادة في الحجم والشكل، و**الوظيفي** وهو تحسّن أداء الأعضاء والقدرات.","**[[خصائصه|ar.l07.principles]]**: مستمر ومتتابع وتراكمي وقابل للتنبؤ، مع فروق فردية في سرعته؛ و**معدلاته مختلفة**: سريع في الطفولة المبكرة والمراهقة، وبطيء في الطفولة المتوسطة.","**اتجاهه** رأسي–ذيلي (الرأس قبل القدمين) ومركزي–طرفي (الذراع قبل الأصابع)، ومن العام إلى الخاص (القبض بالكف قبل الالتقاط بإصبعين).","النمو محصلة **تفاعل الوراثة والبيئة**؛ و**[[النضج|ar.l07.maturation]] شرط للتعلم** لا العكس: النضج تغير داخلي يحدث دون تدريب، والتعلم تغير بالخبرة، والتعليم قبل الاستعداد يضيع الجهد ويولد الإحباط.","في الصف: معلمة روضة تدرّب أطفالاً في الثالثة على الكتابة بين السطور فلا ينجحون رغم التكرار؛ السبب عدم اكتمال النضج العضلي الدقيق، لا ضعف الدافعية ولا قلة التعزيز، فتبدأ بأنشطة تهيئة كالقص وتتبع الخطوط الكبيرة.","ومن جذور الجدل بين الوراثة والبيئة: **جون لوك** يرى أن الطفل يولد وعقله **صفحة بيضاء** تكتبها الخبرة، و**روسو** يراه يولد خيّراً بطبعه وينمو نمواً طبيعياً حراً، والمجتمع هو الذي يفسده."]},{"pts":["**[[بياجيه|ar.l07.piaget]]**: الطفل **يبني معرفته بنفسه**، ويمر بأربع مراحل **ثابتة الترتيب** يختلف فيها التفكير نوعاً لا كماً، وعوامل الانتقال بينها النضج والخبرة والتفاعل الاجتماعي و[[الموازنة|ar.l09.adapt]].","المراحل وأعمارها: الحس-حركية (0–2) يبدأ فيها **دوام الشيء** نحو 8 أشهر ويكتمل في نهايتها، وما قبل العمليات (2–7) فيها اللغة والرموز مع **التمركز حول الذات** والإحيائية، والعمليات المحسوسة (7–11) فيها [[**الاحتفاظ**|ar.l07.conservation]] والمعكوسية، والمجردة (11 فأكثر) فيها التفكير الافتراضي.","طالب **الابتدائية** من نحو 7 سنوات (الصف الثاني فما فوق) في العمليات المحسوسة؛ أما الصف الأول (6–7) فعلى حدود ما قبل العمليات، فتُحدَّد مرحلته من السلوك الوارد في السؤال: الإحيائية والتمركز حول الذات ما قبل العمليات، والمعكوسية والاحتفاظ محسوسة.","التطبيق: طلاب الابتدائية كلهم يتعلمون بالوسائل المحسوسة والتجارب لا بالتجريد اللفظي، وتظهر بوادر المجرد في آخرها؛ وطالب المتوسطة والثانوية يبدأ المجرد فتناسبه المناقشة والفروض؛ والتمركز حول الذات عجز عن رؤية منظور الآخر لا أنانية.","في الصف: طالب الصف الثالث يحل «5 + 3» بالمكعبات ويتعثر في «س + 3 = 8»، فيمثل المعلم المجهول بصندوق مغلق قبل الرمز؛ ولو سُئلت عن مرحلته فهي العمليات المحسوسة لا المجردة، حتى لو كان ذكياً."],"map":{"type":"steps","title":["Piaget — Cognitive Stages","مراحل النمو المعرفي عند بياجيه"],"groups":[{"n":"الحس-حركية","ar":"من 0 إلى 2","d":"ar.l07.piaget","items":[{"n":"دوام الشيء"}],"tag":"يعرف العالم بالحواس والحركة"},{"n":"ما قبل العمليات","ar":"من 2 إلى 7","d":"ar.l07.piaget","items":[{"n":"التمركز حول الذات"},{"n":"الإحيائية"},{"n":"غياب الاحتفاظ"}],"tag":"لغة ورموز ولعب إيهامي"},{"n":"العمليات المحسوسة","ar":"من 7 إلى 11","d":"ar.l07.conservation","items":[{"n":"الاحتفاظ"},{"n":"المعكوسية"},{"n":"التصنيف والترتيب"}],"tag":"منطق على أشياء **محسوسة** فقط · طالب الابتدائية","hl":true,"trap":"الاحتفاظ يظهر هنا، لا قبلها"},{"n":"العمليات المجردة","ar":"11 فأكثر","d":"ar.l07.piaget","items":[{"n":"اختبار الفروض"},{"n":"التعميم"}],"tag":"تفكير **افتراضي استنباطي**"}]}},{"pts":["**[[إريكسون|ar.l07.erikson]]**: ثماني أزمات نفسية اجتماعية من المهد إلى الشيخوخة، كل أزمة صراع بين قطب إيجابي وآخر سلبي، وحلّ كل أزمة حلاً إيجابياً يمهد للتالية.","أزمات سن المدرسة ثلاث: المبادرة مقابل الذنب (3–6) قبل المدرسة، ثم الاجتهاد مقابل الدونية (6–12) في الابتدائية، وتسمى أيضاً **الكفاية مقابل الشعور بالنقص**، ثم الهوية مقابل تشتت الهوية (12–18) في المراهقة.","التطبيق: في الابتدائية مهام ممكنة وتقدير للجهد، فالتشجيع يبني الكفاية والنقد المتكرر يولّد الدونية؛ وفي المراهقة أدوار ومسؤوليات واحترام للاستقلالية.","في الصف: طالب في الصف الرابع يُحبط بسرعة ويقول «أنا لا أستطيع» كلما أخطأ؛ الأنسب مهام متدرجة يمكنه إنجازها مع الاعتراف بإنجازه، لا إعفاؤه من الصعب ولا مقارنته بزميل متفوق، فكلاهما يرسخ الدونية.","**مارسيا** فصّل أزمة الهوية بمعيارين، الاستكشاف والالتزام، في أربع حالات: التشتت (لا هذا ولا ذاك)، والانغلاق (هوية يفرضها الوالدان بلا استكشاف)، والتعليق (استكشاف بلا التزام)، والتحقيق (استكشاف ثم التزام)."],"map":{"type":"steps","title":["Erikson — Psychosocial Crises","أزمات إريكسون الثماني"],"brackets":[{"from":0,"to":2,"n":"قبل المدرسة"},{"from":3,"to":3,"n":"الابتدائية"},{"from":4,"to":4,"n":"المراهقة"},{"from":5,"to":7,"n":"الرشد والشيخوخة"}],"groups":[{"n":"الثقة","ar":"مقابل عدم الثقة","d":"ar.l07.erikson","tag":"من 0 إلى 1"},{"n":"الاستقلال","ar":"مقابل الخجل","d":"ar.l07.erikson","tag":"من 1 إلى 3"},{"n":"المبادرة","ar":"مقابل الذنب","d":"ar.l07.erikson","tag":"من 3 إلى 6","trap":"لما قبل المدرسة لا للابتدائية"},{"n":"الاجتهاد","ar":"مقابل الدونية","d":"ar.l07.erikson","tag":"من 6 إلى 12: إنجاز يُقدَّر","hl":true},{"n":"الهوية","ar":"مقابل تشتت الهوية","tag":"من 12 إلى 18: «من أنا؟»","hl":true},{"n":"الألفة","ar":"مقابل العزلة","d":"ar.l07.erikson"},{"n":"الإنتاجية","ar":"مقابل الركود","d":"ar.l07.erikson"},{"n":"التكامل","ar":"مقابل اليأس","d":"ar.l07.erikson"}]}},{"pts":["بعد بياجيه وإريكسون ثلاث نظريات أخرى، والفرق الحاسم بين الخمس: بياجيه **معرفي**، وإريكسون نفسي اجتماعي، وكولبرج أخلاقي، وفرويد نفسي جنسي، وهافجهرست مطالب نمو.","**[[كولبرج|ar.l07.kohlberg]]** يقيس **التبرير** لا الحكم بمعضلات أخلاقية (هاينز): ثلاثة مستويات في كل منها مرحلتان، ما قبل التقليدي (العقاب، المصلحة المتبادلة)، والتقليدي (الولد الطيب، القانون والنظام)، وما بعد التقليدي (العقد الاجتماعي، المبادئ العالمية).","في الصف: لماذا لا نغش؟ «حتى لا يُخصم مني» مرحلة 1، و«حتى لا يزعل أبي» مرحلة 3، و«لأن نظام المدرسة يمنعه» مرحلة 4؛ فالاختيار واحد عند الثلاثة، والتبرير وحده يحدد المرحلة.","**[[فرويد|ar.l07.freud]]**: فمية ← شرجية ← قضيبية ← **الكمون** (6–12، سن الابتدائية) ← تناسلية؛ وفي الكمون تهدأ الدوافع ويتجه الطفل إلى التعلم والأقران، والشخصية عنده هو وأنا وأنا أعلى.","**[[مطالب النمو|ar.l07.havighurst]]** عند **هافجهرست** مهام كل مرحلة، وإنجازها يمهد لما بعدها: في الطفولة المتوسطة القراءة والكتابة والحساب واللعب الجماعي والضمير، وفي المراهقة الاستقلال واختيار المهنة.","**حيل الدفاع** عند فرويد أساليب لا شعورية يخفف بها الفرد قلقه: **الإسقاط** أن ينسب مشاعره أو عيوبه إلى غيره، و**الإزاحة** أن يفرغ غضبه في هدف أضعف من مصدره.","و**التعويض** سد نقص يشعر به بالتفوق في مجال آخر، و**التسامي** (الإعلاء) توجيه دافع غير مقبول كالعدوان إلى نشاط مقبول اجتماعياً، و**النكوص** رجوع إلى سلوك مرحلة عمرية سابقة.","في الصف: طالب عاقبه المعلم أمام زملائه فركل حقيبة زميل أصغر منه ← إزاحة؛ وطالب كثير العراك وُجّه إلى فريق الكاراتيه فصار يفرغ اندفاعه في تدريب منظم ← تسامٍ."],"map":{"type":"steps","head":true,"title":["Kohlberg — Moral Reasoning","مراحل الحكم الأخلاقي عند كولبرج"],"brackets":[{"from":0,"to":1,"n":"ما قبل التقليدي"},{"from":2,"to":3,"n":"التقليدي"},{"from":4,"to":5,"n":"ما بعد التقليدي"}],"groups":[{"n":"تجنب العقاب","d":"ar.l07.kohlberg","tag":"يلتزم بالنظام «خوفاً من الخصم»"},{"n":"المصلحة المتبادلة","d":"ar.l07.kohlberg"},{"n":"الولد الطيب","ar":"إرضاء الآخرين","d":"ar.l07.kohlberg","tag":"«ليُرضي معلمه»","hl":true},{"n":"القانون والنظام","d":"ar.l07.kohlberg","tag":"«لأنه قانون المدرسة»","hl":true,"trap":"الولد الطيب 3 والقانون والنظام 4، وكلاهما تقليدي"},{"n":"العقد الاجتماعي","d":"ar.l07.kohlberg"},{"n":"المبادئ العالمية","d":"ar.l07.kohlberg"}]}},{"pts":["مراحل التعليم العام تقابلها أربع مراحل نمو: الطفولة المتوسطة والمتأخرة في الابتدائية، والمراهقة المبكرة في المتوسطة، والمراهقة المتوسطة في الثانوية؛ وخصائص كل مرحلة تحدد الإجراء التدريسي الأنسب لها.","**[[الطفولة المتوسطة|ar.l07.stages]] (6–9)**، أي الصفوف الأولية: فضول وأسئلة كثيرة، وتعلّم بالمحسوسات، وانتباه قصير؛ فالأنسب أنشطة قصيرة متنوعة تتخللها حركة، ولعب ووسائل محسوسة، لا الجلوس الطويل.","**الطفولة المتأخرة (9–12)**، أي الصفوف العليا: سن الجماعة وروح العمل الجماعي وزيادة المفردات؛ فيناسبها العمل في مجموعات وإسناد أدوار قيادية في الأنشطة الجماعية.","**المراهقة المبكرة (12–15)**، أي المتوسطة: طفرة نمو وبلوغ تسبق فيه البنات الأولاد بنحو سنة إلى سنتين، وتقلب انفعالي وأحلام يقظة؛ والمراهق **أكثر المراحل حساسية للنقد القاسي**، فيُناقش انفراداً بالحوار والاحتواء لا الصدام.","**المراهقة المتوسطة (15–18)**، أي الثانوية: اكتمال التفكير المجرد وتكوين الهوية والمثالية؛ فالأنسب مشاريع ومسؤوليات وأدوار قيادية، وربط الدروس بالتخصصات والمهن المستقبلية.","في الصف: طالب في الصف الثاني المتوسط يجادل في كل توجيه ويحرص على موافقة أقرانه؛ هذا سلوك طبيعي لمرحلة البحث عن الهوية والاستقلال، فيُحتوى بالحوار، ولا يُعد اضطراباً سلوكياً يستدعي الإحالة."]},{"pts":["يطلب مؤشر 5.1 أن تعرف أثر الأحداث الضاغطة ومشكلات النمو في التعلم وكيف تتعامل معها: **الأحداث الضاغطة** (طلاق، وفاة، انتقال، ولادة أخ، تنمر) تظهر تشتتاً وتراجعاً وانسحاباً أو عدواناً.","**مشكلات شائعة** في النمو: القلق، والعدوان، والغيرة، والكذب، والخجل، ومخاوف المدرسة؛ و**العلامة التحذيرية** هي التغير المفاجئ عن حال الطالب السابقة، لا السلوك الطبيعي لمرحلته.","**تعامل المعلم** بالترتيب: ملاحظة وتوثيق ← حوار فردي هادئ ← مرونة مؤقتة ← إحالة للموجه الطلابي ← متابعة، مع روتين ثابت وبيئة آمنة، و**السرية** وعدم المقارنة.","الطالب المنتقل حديثاً يُعرَّف بالفصل ويُعطى **زميلاً مرافقاً** ويُشرك تدريجياً؛ وقلق الاختبار يخففه توضيح التقويم مبكراً وتنويع أدواته والتدريب على أسئلة مشابهة.","في الصف: طالب متفوق تراجع تحصيله فجأة وصار شارداً منطوياً بعد انفصال والديه؛ الإجراء الأول حوار فردي هادئ معه ثم التنسيق مع الموجه الطلابي، لا مناقشة ظروفه أمام زملائه ولا الانتظار حتى نهاية الفصل."]},{"pts":["**[[مؤشرات الاضطراب الانفعالي|ar.l07.emo]]**: حزن مستمر، وانسحاب، وغضب غير مبرر، وشكاوى جسمية بلا سبب طبي؛ والمعلم أقرب من يلاحظها يومياً، والعلامة الواحدة منها ليست دليلاً قاطعاً.","[[**الإيذاء**|ar.l02.childprot]]: إساءة جسدية أو نفسية أو جنسية أو التهديد بها؛ و**الإهمال**: عدم توفير الحاجات الأساسية أو التقصير فيها؛ وانقطاع الطالب عن التعليم يُعد إيذاءً أو إهمالاً.","**[[المادة 29|ar.l07.abuse]]**: إبلاغ مدير المدرسة فوراً وبسرية ← لجنة التوجيه الطلابي ← محضر رسمي ← ولي الأمر؛ والإجراءات عاجلة سرية لا تتدرج كالمخالفات السلوكية، بل بحسب خطورة الحالة.","الحالة العاجلة تُبلَّغ إلى **1919** فوراً؛ وإذا كان المصدر من **منسوبي المدرسة** رُفعت الحالة إلى إدارة التعليم، ولمن لاحظ تراخياً من الإدارة أن يبلغ 1919 مباشرة.","في الصف: لاحظ معلم على طالب كدمات غير مفسرة وخوفاً من العودة إلى المنزل؛ الصحيح أن **يلاحظ ويوثق ويبلغ** مدير المدرسة فوراً وبسرية، لا أن يتصل بالأسرة ليتحقق بنفسه، فالمعلم لا يحقق ولا يواجه ولا يعد الطالب بالكتمان."]}],"L08":[{"pts":["**الفروق الفردية** انحراف الفرد عن متوسط الجماعة في سمة ما، وهي فروق كمية في الدرجة لا في النوع تتوزع توزيعاً اعتدالياً، ونوعان: **بين الأفراد**، و**داخل الفرد** (قوي في اللغة ضعيف في الرياضيات).","**أكبر مدى** للفروق في السمات الانفعالية والشخصية، وأقله في الجسمية، والعقلية أكثر ثباتاً؛ وأسبابها الوراثة والبيئة والعمر والجنس، وتظهر في القدرات والتحصيل والاستعداد والاتجاهات والميول.","مقياس «موافق بشدة… غير موافق بشدة» يقيس **الاتجاهات**؛ وزمن الرجع، وهو الزمن بين ظهور المثير وبدء الاستجابة، من مظاهر الفروق التي تُقاس كمياً.","تُراعى الفروق بالتنويع والتعلم التعاوني والتعليم المبرمج، و**المحاضرة لا تراعيها**؛ وأوسع أساليب مراعاتها [[التعليم المتمايز|ar.l08.diff]] عند توملينسون: يُمايَز المحتوى أو العملية أو المنتج أو البيئة وفق استعداد الطلاب واهتماماتهم وأنماطهم.","**التعليم المتمايز** يقوم على **مجموعات مرنة** تتغير بحسب المهمة، فتجميع المتقاربين في المستوى لنشاط يناسبهم صحيح، والخطأ التقسيم الدائم حسب الذكاء؛ وهدف التعلم واحد للجميع، والذي يتنوع هو الطريق إليه والمنتج.","في الصف: معلمة الصف الخامس هدفها واحد (فهم دورة الماء)، فقدمت المحتوى بنص وفيديو ومجسم، وتركت الطلاب يختارون المنتج (ملصق، عرض، تجربة): هذا تعليم متمايز، لا تعلم تعاوني ولا تعليم مبرمج."]},{"pts":["**[[أنماط التعلم|ar.l08.styles]]** (VARK) طريقة الطالب المفضلة في استقبال المعلومات: بصري، وسمعي، وحسي حركي، وقرائي كتابي؛ فتقسيم الطلاب إلى بصري وسمعي وحسي **أنماط تعلم** لا ذكاءات.","**[[ذكاءات جاردنر الثمانية|ar.l08.gardner]]** أنواع مستقلة نسبياً لا قدرة واحدة: لغوي، ومنطقي، ومكاني، وجسمي، وموسيقي، واجتماعي، وذاتي، وطبيعي؛ ويملك كل طالب خليطاً منها بدرجات مختلفة.","في الصف: طالبة تتأمل نفسها وتكتب عن مشاعرها وأهدافها ذكاؤها **ذاتي**، والتي تقود زميلاتها وتفهم مشاعرهن ذكاؤها اجتماعي، ومن يصنف النباتات طبيعي؛ والفيصل بين الذاتي والاجتماعي: فهم الذات أم فهم الآخرين.","دورة **كولب** في التعلم: خبرة ← تأمل ← تجريد ← تجريب؛ ونموذج **مكارثي (4MAT)** يبني الدرس على أربعة أسئلة تناسب جميع الأنماط: لماذا؟ ماذا؟ كيف؟ ماذا لو؟","التطبيق: **تنويع** المداخل والعرض والأنشطة، لا حصر الطالب في نمط واحد؛ فعرض الدرس شرحاً شفهياً ثم خريطة مفاهيم ثم نشاطاً يدوياً يراعي الأنماط السمعي والبصري والحسي."]},{"pts":["مؤشر 5.2 يطلب أن تميز اختلافات الطلاب الراجعة إلى خلفياتهم الاقتصادية والاجتماعية والثقافية وما تحتاجه كل منها؛ والقاعدة الجامعة: **العدالة** تقديم ما يحتاجه كل طالب، لا الشيء نفسه للجميع، مع حفظ خصوصية ظروفه.","**[[الخلفية الاقتصادية|ar.l08.bg]]** المحدودة تفرّق الطلاب في خلفياتهم المعرفية وخبراتهم لا في قدرتهم على التعلم، فتُتاح لهم مصادر المدرسة ووقت للإنجاز فيها ولا تُشترط مواد مكلفة؛ و**الخلفية الاجتماعية** (تعليم الوالدين، استقرار الأسرة) تؤثر في الدعم المنزلي.","**الخلفية الثقافية واللغوية**، كطالب وافد أو لغته الأم غير العربية: أمثلة من بيئات متنوعة، وشرح المفردات، ودعم لغوي، واحترام للعادات.","**التدريس المستجيب ثقافياً** يجعل ثقافة الطالب جسراً للتعلم، بتوقعات عالية للجميع ودون قوالب نمطية؛ فخفض المستوى المطلوب من الطلاب الوافدين قالب نمطي لا مراعاة.","في الصف: كلف معلم طلابه بمشروع يحتاج طباعة ملونة وأدوات مكلفة فلم ينجزه بعضهم لظروف أسرهم الاقتصادية؛ الأنسب إتاحة بدائل منخفضة التكلفة واستخدام مصادر المدرسة، لا إعفاؤهم من المشروع نهائياً، فالإعفاء يحرمهم من التعلم.","في الصف، من نماذج دليل الهيئة: معلم لفصل فيه طلاب من خلفيات لغوية متنوعة يعزز تعلمهم بجمع ذوي المستوى المتقارب في مجموعات صغيرة لأنشطة تناسبهم، لا بإتاحة الحديث عن محتوى الدرس للجميع، لأن ذلك لا يراعي اختلاف مستوياتهم اللغوية."]},{"pts":["التدني الدراسي أربع حالات يفرقها الذكاء والسبب: صعوبات التعلم (ذكاء عادي واضطراب في العمليات)، وبطء التعلم (ذكاء حدّي 70–85 وضعف عام)، والتأخر الدراسي (ذكاء عادي وسبب خارجي)، والإعاقة الفكرية (ذكاء دون 70 تقريباً، ويقبل الدليل التنظيمي حتى 75 مع قصور تكيفي).","تشخيص [[صعوبات التعلم|ar.l08.ld]] بـ**محك التباين** (ويسمى التباعد أو التفاوت) بين القدرة والتحصيل، ومعه محك الاستبعاد للإعاقات والظروف البيئية؛ وسبب تدني ذي الصعوبات **اضطراب العمليات**، لا انخفاض الذكاء ولا ضعف الدافعية.","أنواع الصعوبات: **أكاديمية**، فالديسلكسيا قراءة، والديسغرافيا كتابة، والديسكالكوليا حساب؛ و**نمائية** في العمليات نفسها: الانتباه والإدراك والذاكرة.","ذو الصعوبات يبقى في الفصل العادي مع [[غرفة المصادر|ar.l08.inclusion]] و[[خطة فردية|ar.l08.iep]]، ومن طرق تدريسه تعدد الحواس؛ و[[تشخيصه وتدريسه|ar.l08.ld2]]: يُحال إذا استمرت المشكلة بعد الصف الثاني الابتدائي رغم سلامة الذكاء والحواس.","في الصف: راشد وفيصل في الصف الثالث؛ راشد ضعيف في جميع المواد بذكاء حدّي، وفيصل ضعيف في الرياضيات واللغة العربية فقط بذكاء عادي؛ فراشد بطيء تعلم وفيصل ذو صعوبات تعلم، والعكس فخ متكرر."],"map":{"type":"grid","mlist":true,"title":["Low achievement: four cases","أربع حالات يفرّقها الذكاء والسبب"],"cols":[{"n":"الذكاء","c":"#4A5953"},{"n":"السبب وما يميزه","c":"#4A5953"}],"rows":[{"n":"صعوبات التعلم","cells":[{"n":"عادي أو فوق العادي","c":"#1F6B4C","d":"ar.l08.ld"},{"n":"اضطراب في العمليات النفسية الأساسية","ar":"تباين بين القدرة والتحصيل في مادة أو أكثر","c":"#1F6B4C","d":"ar.l08.ld"}]},{"n":"بطء التعلم","cells":[{"n":"حدّي (70–85)","c":"#33449A"},{"n":"تدنٍّ عام","ar":"في كل المواد","c":"#33449A"}]},{"n":"التأخر الدراسي","cells":[{"n":"عادي","c":"#A8562A"},{"n":"سبب خارجي","ar":"إهمال، غياب، ضعف دافعية، ظروف أسرية","c":"#A8562A"}]},{"n":"الإعاقة الفكرية","cells":[{"n":"دون 70 تقريباً","c":"#8A3B63","d":"ar.l08.id"},{"n":"قصور في السلوك التكيفي","ar":"في مرحلة النمو (قبل 18)","c":"#8A3B63","d":"ar.l08.id"}]}],"trap":"الذكاء عادي في الصعوبات والتأخر: الفرق في السبب، داخلي في الأولى وخارجي في الثانية"}},{"pts":["**[[التوحد|ar.l08.autism]]**: قصور التواصل والتفاعل، وسلوك نمطي متكرر، ومقاومة للتغيير، ويظهر في الطفولة المبكرة (غالباً قبل الثالثة)؛ وبيئته **التعلم المنظم** الثابت: روتين وجداول بصرية وتنبيه مسبق قبل أي تغيير.","في الصف: طالب يرفض أي تغيير في ترتيب المقاعد وينزعج بشدة عند تغيير الجدول؛ الأنسب تثبيت الروتين وإعلامه مسبقاً بأي تغيير بجدول بصري، لا تغيير الترتيب باستمرار ليعتاد، فذلك يزيد اضطرابه.","**فرط الحركة**: ضعف انتباه ونشاط زائد واندفاعية؛ فيُجلس الطالب قرب المعلم بعيداً عن المشتتات، ويُكلف بمهام قصيرة تتخللها حركة هادفة مع تعزيز فوري، لا العزل في آخر الصف ولا العقاب.","**[[الإعاقة الفكرية|ar.l08.id]]**: ذكاء دون 70 تقريباً (حتى 75 على وكسلر في الدليل التنظيمي) مع قصور في السلوك التكيفي يظهر في مرحلة النمو (قبل 18 في التعريف الشائع)، والشرطان معاً؛ و**[[السمعية والبصرية|ar.l08.sensory]]**: مواجهة الطالب ولغة الإشارة وإجلاسه في المقدمة، وبرايل والوصف اللفظي لما على السبورة.","**الدمج** مع العاديين أنواع: مكاني (فصل خاص في مبنى المدرسة العادية يشاركها المرافق فقط)، أو اجتماعي، أو أكاديمي (جزئي أو كلي)، أو شامل.","ذوو الاحتياجات الخاصة **يشملون الموهوبين**؛ ودور المعلم مع اشتباه إعاقة أن يلاحظ ويحيل ولا يشخص، ولا يبلغ ولي الأمر بحكم غير مؤكد.","**الحبسة الكلامية** (الأفازيا) اضطراب لغوي مكتسب بإصابة في الدماغ: في **التعبيرية** يفهم الطالب ما يُقال ويتعسّر عليه إخراج الكلام، وفي **الاستقبالية** يتكلم بطلاقة كلاماً قليل المعنى ولا يفهم ما يُقال له."]},{"pts":["مسار الطالب: ملاحظة ← إحالة ← موافقة ولي الأمر خطياً ← تشخيص ← خطة فردية؛ والتشخيص من مصادر متعددة، و**لا يُكتفى بمقياس واحد**، وللأسرة طلب إعادة التشخيص.","**عناصر الخطة**: مستوى الأداء الحالي ← أهداف طويلة وقصيرة قابلة للقياس ← الخدمات ← التقويم؛ والخطة **وثيقة متجددة** تُراجع سنوياً أو نصف سنوي، أو عند تعثر التقدم.","في الصف: هدف قصير جيد في الخطة «يقرأ 20 كلمة من كلمات الصف بدقة 90% خلال 6 أسابيع»، أما «يتحسن في القراءة» فمرفوض لأنه غير قابل للقياس؛ وتُشتق الأهداف كلها من مستوى أدائه الحالي.","**[[لجنة الخطط|ar.l08.iepteam]]**: قائد المدرسة رئيساً، ومعلما التربية الخاصة والتعليم العام، والمرشد، وولي الأمر، والطالب قدر الإمكان؛ وليس منها المشرف التربوي للمادة.","**معلم التعليم العام** يكيّف التدريس ويشارك في الخطة والتقويم مع معلم التربية الخاصة؛ و**الخدمات المساندة** كالعلاج الطبيعي والنطق، و**المكان التربوي** في البيئة الأقل تقييداً: فصل عام ← غرفة مصادر ← فصل خاص ← معهد."],"map":{"type":"flow","title":["Referral path to the IEP","المسار: من الملاحظة إلى الخطة الفردية"],"groups":[{"n":"ملاحظة","idea":"المعلم يلاحظ ويوثّق","trap":"المعلم يلاحظ ويحيل ولا يشخص"},{"n":"إحالة","idea":"إلى الفريق المختص"},{"n":"موافقة","idea":"**موافقة ولي الأمر الخطية**"},{"n":"تشخيص","idea":"فريق متعدد التخصصات، لا مقياس واحد"},{"n":"خطة فردية","idea":"أداء حالي ← أهداف ← خدمات ← تقويم","items":[{"n":"الخطة الفردية","d":"ar.l08.iep"}]}]}},{"pts":["الموهوبون من ذوي الاحتياجات الخاصة، ويُسأل عنهم في ثلاثة أمور: مفهوم الموهبة عند رنزولي وجانييه، وطريقة الكشف عنها، وأسلوب رعايتها بالإثراء أو التسريع.","**[[رنزولي|ar.l08.renzulli]]**: الموهبة قدرة فوق المتوسط + إبداع + التزام بالمهمة، فلا يكفي الذكاء وحده؛ و**جانييه** (فرانسوا): الموهبة فطرية والتفوق مكتسب، فكل متفوق موهوب، لا العكس.","**الكشف** بمحكات متعددة (ذكاء، إبداع، ترشيح المعلم، ملاحظة الأداء) لا بالتحصيل وحده، لأن التحصيل المرتفع ليس من حلقات رنزولي الثلاث.","**[[الإثراء|ar.l08.gifted]]** يعمّق (رأسي) أو يوسّع (أفقي) في الصف نفسه، و**[[التسريع|ar.l08.accel]]** (التعجيل) قبول مبكر أو تخطي صف أو ضغط منهج يحذف ما أتقنه الطالب منه، لا حذف مواد؛ فالإثراء يبقيه في صفه والتسريع يغير مستواه أو زمنه.","في الصف: طالبة أنهت تمارين الكسور في دقائق وبدأت تمل؛ لا تُعطى عشرين مثلها، فالتمارين نفسها خطأ شائع يزيد الملل، بل [[مهام أعمق|ar.l08.giftchar]] كمشكلة مفتوحة (تحويل وصفة من 4 أشخاص إلى 30)، وهذا إثراء رأسي."]}],"L09":[{"pts":["قبل نظريات التعلم ميّز أربعة مفاهيم متقاربة يكثر الخلط بينها في الأسئلة: **التعلم والتعليم والتدريس** والتربية؛ والفرق بينها في صاحب النشاط ومداه الزمني وسعته.","**التعلم** نشاط ذاتي خاص بالمتعلم: تغير شبه دائم في سلوكه يكتسبه من الخبرة والممارسة؛ فهو ما يحدث داخل الطالب، لا ما يفعله المعلم.","**التعليم** تصميم منظم للخبرة يقوم به المعلم ليساعد المتعلم على تغيير سلوكه، و**التدريس** إجراء قصير المدى ينفذه المعلم لأهداف محددة في موقف معين، و**التربية** أشملها لأنها تستهدف نمو الفرد كله وإعداده للحياة.","لذلك إذا وصف السؤال «إجراء قصير المدى يقوم به المعلم لأهداف محددة» فهو التدريس، و«العملية الأشمل لنمو الفرد» هي التربية؛ والتعليم يُغري لأنه من عمل المعلم أيضاً، لكنه تصميم للخبرة لا إجراء قصير.","بعد هذه المفاهيم تأتي خمس عائلات نظرية تختلف في نظرتها إلى المتعلم: السلوكية تراه متلقياً يتعلم بالمثير والاستجابة، والاجتماعية بالملاحظة، والمعرفية ومعالجة المعلومات بالفهم والتنظيم، والبنائية تراه يبني معرفته بنفسه."]},{"pts":["**السلوكية** تفسر التعلم بارتباط بين مثير واستجابة يقويه الاقتران أو النتيجة، والمتعلم فيها متلقٍ سلبي والمعلم ملقّن ومعزِّز؛ ومؤسسها **واطسون** صاحب تجربة الطفل ألبرت التي أثبتت أن الخوف يُتعلم بالاقتران.","**بافلوف** قرن مثيراً محايداً (الجرس) بمثير غير شرطي (الطعام) مرات عدة، حتى صار الجرس وحده **مثيراً شرطياً** يستدعي استجابة شرطية (اللعاب)؛ فالمثير هنا يسبق الاستجابة، والاستجابة لا إرادية.","إذا تكرر المثير الشرطي دون غير الشرطي ضعفت الاستجابة حتى تختفي، وهذا **الانطفاء**؛ وعودتها فجأة بعد راحة **الاسترجاع التلقائي**، و**التعميم** استجابة لمثيرات تشبه الأصلي، و**التمييز** استجابة للمثير الأصلي وحده.","في الصف: طالب وُبِّخ مراراً في حصة الرياضيات فصار يخاف كل حصة فيها أرقام، وهذا تعميم؛ ولو زال خوفه بعد حصص آمنة (انطفاء) ثم عاد فجأة بعد إجازة طويلة فهو استرجاع تلقائي، وقلق الاختبار عموماً استجابة مكتسبة لا فطرية.","**[[ثورندايك|ar.l09.thorndike]]** فسّر التعلم بالمحاولة والخطأ (القط في الصندوق)، ووضع قانون **الأثر**: الاستجابة المتبوعة بارتياح تقوى، ومعه قانونا التدريب والاستعداد؛ أما **جاثري** فصاحب الاقتران الذي يكفي فيه اقتران واحد قوي.","**[[انتقال أثر التعلم|ar.l09.transfer]]** استخدام خبرة سابقة في موقف جديد، ويفسره ثورندايك بالعناصر المتطابقة بين الموقفين؛ وهو موجب أو سالب أو صفري، وأفقي في المستوى نفسه، أو رأسي حين تُبنى مهارة أعلى على سابقة كالضرب على الجمع."],"cmp":{"title":"الكلاسيكي أم الإجرائي؟","cols":["الكلاسيكي (بافلوف)","الإجرائي (سكنر)"],"rows":[{"k":"الترتيب","a":"المثير قبل الاستجابة","b":"النتيجة (التعزيز) بعد الاستجابة"},{"k":"نوع الاستجابة","a":"لا إرادية انفعالية (لعاب، خوف)","b":"إرادية يصدرها المتعلم"},{"k":"الانطفاء","a":"تكرار المثير الشرطي دون غير الشرطي","b":"إيقاف التعزيز عن السلوك"},{"k":"مثال صفي","a":"قلق مكتسب من قاعة الاختبار","b":"زيادة المشاركة بعد المدح"}]}},{"pts":["**[[سكنر|ar.l09.skinner]]** درس السلوك الإجرائي الذي يصدره المتعلم بإرادته ثم تتحكم فيه نتائجه، فالتعزيز بعد الاستجابة مفتاح التعلم؛ ويُسمى أيضاً الاشتراط الوسيلي لأن الاستجابة وسيلة للحصول على المعزز.","مفتاح التعزيز والعقاب: التعزيز يزيد السلوك والعقاب يقلله، والموجب إضافة والسالب إزالة؛ فالتعزيز السالب إزالة منفّر فيزيد السلوك وليس عقاباً، والعقاب السالب سحب معزّز ومنه تكلفة الاستجابة والإقصاء.","في الصف: طالب يجيب إجابات صحيحة ولا يعززه المعلم فتقل مشاركته تدريجياً؛ هذا **الانطفاء** الإجرائي (إيقاف التعزيز فيتلاشى السلوك)، لا إشراط كلاسيكي، لأن المشاركة سلوك إرادي تحكمه نتائجه.","والانطفاء وصفه **بافلوف** أولاً في الاشتراط الكلاسيكي: يتكرر المثير الشرطي بلا المثير الطبيعي فتضعف الاستجابة. فإن سُئلت عن النظرية التي يتبعها الانطفاء عموماً ولم يكن **الإجرائي** بين البدائل، فالجواب الاشتراط الكلاسيكي.","**جداول التعزيز**: المستمر أسرع تعلماً وأسرع انطفاءً، و**النسبة المتغيرة** أقواها وأكثرها مقاومة للانطفاء؛ وفي **الفترة الثابتة** (اختبار كل أسبوع) يرتفع الاستذكار قبيل الموعد، والاختبار المفاجئ فترة متغيرة تبقي الأداء منتظماً.","**التشكيل** تعزيز التقريبات المتتابعة، كمدح الطالب الخجول حين يرفع يده ثم حين يجيب بكلمة ثم بجملة؛ و**مبدأ بريماك** أن يعزز نشاط محبب نشاطاً أقل تفضيلاً: «أنهِ الواجب ثم العب».","**[[المعززات وتطبيقاتها|ar.l09.reinf]]**: معززات غذائية (حلوى)، ومادية (هدية)، واجتماعية أو معنوية (ابتسامة ومدح)، ورمزية كالنجوم تُستبدل لاحقاً (الاقتصاد الرمزي)، ونشاطية (وقت لعب)؛ ومن تطبيقات سكنر التعليم المبرمج وتعديل السلوك."],"map":{"type":"grid","title":["Skinner — Consequences","التعزيز والعقاب عند سكنر"],"colsTitle":["نضيف أم نزيل؟"],"rowsTitle":["أثره في السلوك"],"cols":[{"n":"موجب","ar":"نضيف شيئاً","c":"#4A5953"},{"n":"سالب","ar":"نزيل شيئاً","c":"#4A5953"}],"rows":[{"n":"تعزيز","ar":"يزيد السلوك","cells":[{"n":"تعزيز موجب","ar":"نضيف سارّاً","ex":"مدح، درجات، نجمة","c":"#1F6B4C","d":"ar.l09.skinner"},{"n":"تعزيز سالب","ar":"نزيل منفّراً","ex":"إلغاء الإنذار لمن شارك","c":"#1F6B4C","d":"ar.l09.skinner"}]},{"n":"عقاب","ar":"يقل السلوك","cells":[{"n":"عقاب موجب","ar":"نضيف منفّراً","ex":"توبيخ","c":"#A8562A","d":"ar.l09.skinner"},{"n":"عقاب سالب","ar":"نسحب معزّزاً","ex":"تكلفة الاستجابة، الإقصاء","c":"#A8562A","d":"ar.l09.skinner"}]}],"legend":["**موجب** و**سالب** = نضيف أو نزيل، لا «جيد» و«سيئ»"],"trap":"التعزيز السالب يزيد السلوك: ليس عقاباً"},"cmp":{"title":"جداول التعزيز المتقطع: بعدد الاستجابات أم بالزمن؟","cols":["ثابتة","متغيرة"],"rows":[{"k":"**نسبة** (عدد استجابات)","a":"نجمة كل 5 إجابات صحيحة","b":"بعد عدد غير منتظم: **أعلى أداء وأقوى مقاومة للانطفاء**"},{"k":"**فترة** (زمن)","a":"اختبار كل أسبوع: يرتفع الأداء قبيل الموعد","b":"اختبارات قصيرة **مفاجئة**: أداء منتظم"}]}},{"pts":["**[[باندورا|ar.l09.bandura]]** يرى أننا نتعلم بملاحظة نموذج وتقليده (**النمذجة**) دون تعزيز مباشر، كما قلّد الأطفال في تجربة دمية بوبو؛ ونظريته جسر بين السلوكية والمعرفية، وتقوم على **الحتمية التبادلية** بين الفرد وسلوكه وبيئته.","يمر التعلم بالملاحظة بأربع مراحل مرتبة: الانتباه إلى النموذج، ثم الاحتفاظ بما رآه، ثم الإنتاج أي أداء السلوك، ثم الدافعية لتكراره؛ والنموذج قد يكون حياً أو رمزياً كالفيديو والقصة.","**التعزيز البديل** أن يرى الملاحظ النموذج يُكافأ فيزيد سلوكه هو، والعقاب البديل يقلله، والتعزيز الذاتي رضا الفرد عن أدائه؛ والنمذجة أنسب طريقة لتعلم **الاتجاهات والقيم** والمهارات الاجتماعية، فالمعلم قدوة.","في الصف: لتعليم «احترام رأي الآخرين» بالنمذجة يمارسه المعلم أمام طلابه؛ أما شرح معناه والحث عليه فتلقين لفظي، ومكافأة من يمارسه تعزيز سلوكي، ولا تعلم بالملاحظة دون نموذج يؤدي السلوك.","**[[الكفاءة الذاتية|ar.l10.selfeff]]** اعتقاد الطالب بقدرته على مهمة محددة، وأقوى مصادرها خبرات الإتقان؛ فمن يقول «لن أنجح في الرياضيات مهما حاولت» يحتاج نجاحات متدرجة ونماذج تشبهه نجحت، لا عبارة «أنت ذكي» وحدها.","**[[الانفصال الأخلاقي|ar.l09.moraldis]]** تبرير الفرد سلوكه المؤذي، ومن آلياته التهذيب اللفظي: كأن يبرر طالب اعتداءه المتكرر على زملائه بأنه «نوع من المزاح المقبول»."]},{"pts":["**المعرفية** ترى التعلم فهماً وتنظيماً بعمليات عقلية داخلية كالإدراك والمعنى، والمتعلم فيها نشط؛ وأعلامها في الاختبار: الجشطلت (الاستبصار)، وتولمان (التعلم الكامن)، وأوزوبل (التعلم ذو المعنى)، وبرونر (الاكتشاف).","**[[الجشطلت|ar.l09.gestalt]]**: الكل أكبر من مجموع أجزائه، والتعلم **استبصار** مفاجئ بإعادة تنظيم الموقف كما ركّب قرد كوهلر العصوين ليجلب الموز، وكالطالب الذي يصيح «فهمت!» بعد محاولات فاشلة؛ ومن قوانين الإدراك الإغلاق والتشابه.","**[[تولمان|ar.l09.tolman]]**: فئرانه تجولت في المتاهة بلا تعزيز ثم تحسن أداؤها فجأة حين وُضع الطعام، وهذا التعلم الكامن الذي يحدث دون تعزيز ويظهر عند الحاجة، ويكوّن فيه المتعلم خرائط معرفية.","**[[أوزوبل|ar.l09.ausubel]]**: التعلم ذو المعنى بربط الجديد بالبنية المعرفية، ويمهد له **المنظم المتقدم** قبل الدرس (شارح أو مقارن)؛ ومبدآه **التمايز التدريجي** (التقدمي) من العام إلى الخاص، و**التوفيق التكاملي** بربط المفاهيم وإزالة التناقض.","**[[برونر|ar.l09.bruner]]**: يتعلم الطالب أعمق حين يصل إلى المبدأ بنفسه، و**الاكتشاف** الموجه أنسب صفياً؛ ويتدرج التمثيل من عملي بالأشياء إلى أيقوني بالصور والخرائط إلى رمزي باللغة، ومن أفكاره المنهج الحلزوني.","في الصف: فيلم عن تجاذب الأجسام وتنافرها قبل درس الشحنات منظم متقدم لأنه يربط الدرس بالبنية المعرفية، لا تهيئة حافزة تثير الاهتمام فقط؛ وحفظ تعريف الاحتكاك دون ربطه بالحركة تعلم صمّ لا ذو معنى.","**هرم جانييه** يرتب أنواع التعلم ثمانية من **التعلم الإشاري** إلى **حل المشكلات**، مروراً بالمثير والاستجابة والتسلسل والترابط اللفظي والتمييز والمفاهيم والمبادئ، وكل نوع شرط لما فوقه، فيبدأ المعلم بالمتطلبات السابقة."]},{"pts":["نموذج **الذاكرة** عند أتكنسون وشيفرين يشبّه العقل بالحاسوب: ثلاثة مخازن متتابعة هي الحسية ثم قصيرة المدى (العاملة) ثم طويلة المدى، و**الانتباه** بوابة المعالجة، والعمليات ترميز ثم تخزين ثم استرجاع.","الذاكرة قصيرة المدى (العاملة) تتسع لنحو 7±2 وحدات (ميلر)، وتبقى فيها المعلومة 15–30 ثانية دون تسميع، والطويلة غير محدودة؛ وتُنقل المعلومة إلى الطويلة بالتسميع والتجميع والتفصيل بالربط والتنظيم.","في الصف: يفشل الطلاب في حفظ رقم من عشرة أرقام، وينجحون حين يُعرض ثلاث مجموعات (055 – 123 – 4567)؛ هذا تجميع يقلل الوحدات في الذاكرة العاملة، وليس تسميعاً لأن التسميع تكرار.","**التداخل** قبلي حين يعيق القديم الجديد، وبعدي حين يعيق الجديد القديم، والاسم بحسب اتجاه الإعاقة: من تعلم الإسبانية بعد الفرنسية فنسي الفرنسية تداخله بعدي؛ وبقية [[أنواع الذاكرة والنسيان|ar.l09.memtypes]] في الدرج.","**الترميز المزدوج** (بايفيو) يخزن المعلومة لفظياً وبصرياً معاً فتكون أقوى، و**الحمل المعرفي** (سويلر) عبء المعالجة على الذاكرة العاملة؛ فإذا شرح المعلم عشرين دقيقة متواصلة توقف الطلاب عن المتابعة، والحل التقسيم والتوقف للمعالجة.","**[[ما وراء المعرفة|ar.l10.meta]]** (فلافل) تفكير في التفكير بالتخطيط والمراقبة والتقويم، كأن يسأل المعلم «كيف توصلت إلى الإجابة؟»؛ و**التدريب الموزع** على جلسات قصيرة متباعدة أفضل للاحتفاظ من المذاكرة المكثفة ليلة الاختبار.","**أنواع الانتباه**: **الانتقائي** تركيز على مثير واحد وتجاهل غيره، و**الموزع** (المنقسم) على أكثر من مثير في الوقت نفسه، والمتناوب تنقّل سريع بين مثيرين أو مهمتين، و**القسري** يفرضه مثير قوي مفاجئ كصوت الرعد."],"map":{"type":"flow","title":["Atkinson & Shiffrin — memory stores","مخازن الذاكرة (أتكنسون وشيفرين)"],"back":[[2,1]],"loop":["الاسترجاع: من الطويلة إلى العاملة"],"note":"نموذج **أتكنسون وشيفرين**: الانتباه ينقل من الحسية إلى العاملة، والتسميع والتجميع ينقلان إلى الطويلة.","groups":[{"n":"الحسية","idea":"سعة كبيرة ومدة قصيرة جداً","items":[{"n":"الانتباه"}]},{"n":"العاملة","idea":"قصيرة المدى: **7±2** وحدات، 15–30 ثانية","items":[{"n":"التسميع"},{"n":"التجميع"}]},{"n":"طويلة المدى","idea":"غير محدودة","items":[{"n":"الاسترجاع"}]}]}},{"pts":["**البنائية** ترى أن المتعلم يبني معرفته على خبراته السابقة، والمعلم ميسّر والخطأ فرصة للتعلم؛ وهي عند بياجيه بناء فردي بتفاعل الطفل مع الأشياء، وعند فيجوتسكي بناء اجتماعي أولاً ثم فردي.","عند [[بياجيه|ar.l09.adapt]] تنتظم الخبرات في مخططات: **تمثل** يُدخل الخبرة الجديدة في مخطط قائم دون تغييره، و**مواءمة** تعدّل المخطط أو تبني جديداً، وتحركهما الموازنة حين تُحدث خبرة محيرة اختلالاً في التوازن.","في الصف: طفل يسمي الحمار الوحشي «حصاناً مخططاً» فهذا تمثل، ثم يكوّن له مفهوماً جديداً فهذه مواءمة؛ ولهذا يطرح المعلم البنائي مواقف محيرة تناسب المرحلة لتدفع الطالب إلى المواءمة.","**[[فيجوتسكي|ar.l09.vygotsky]]**: التعلم اجتماعي أولاً، واللغة أداة التفكير، و**منطقة النمو القريب** المسافة بين ما ينجزه الطالب وحده وما ينجزه بمساعدة الأكثر خبرة؛ فمن يحل مسألة من خطوتين وحده ومن أربع بتلميحات يُدرَّس مسائل الأربع.","**السقالات** دعم مؤقت متدرج (تلميح، نموذج، سؤال) يُسحب مع تقدم المتعلم، والدعم الدائم ليس سقالة؛ كمعلمة تقدم قائمة تحقق وأسئلة موجهة في أول تقرير علمي ثم تقللها في التقارير التالية.","في الصف: خالد في الصف الأول الابتدائي يحدّث نفسه أثناء حل المسائل؛ هذا عند فيجوتسكي استراتيجية توجه تفكيره وتطور طبيعي في سنه، لا عدم نضج ولا عادة تحتاج علاجاً، وإن عدّه بياجيه تمركزاً حول الذات."],"cmp":{"title":"بياجيه أم فيجوتسكي؟","cols":["بياجيه","فيجوتسكي"],"rows":[{"k":"مصدر البناء","a":"فردي: تفاعل الطفل مع الأشياء","b":"اجتماعي أولاً ثم فردي"},{"k":"النمو والتعلم","a":"النمو يسبق التعلم (الاستعداد)","b":"التعلم يقود النمو"},{"k":"الحديث الذاتي","a":"علامة تمركز حول الذات","b":"أداة لتنظيم التفكير"},{"k":"دور المعلم","a":"يهيئ بيئة للاكتشاف والحيرة المعرفية","b":"يدعم داخل منطقة النمو القريب ثم يسحب الدعم"}]}},{"pts":["يطلب مؤشر 5.3 أن يعرف المعلم نتائج الأبحاث المعاصرة في التعلم وأساليب التعلم الفردي، ومنهما موضوعا هذا القسم: التعلم المستند إلى الدماغ، والأساليب المعرفية التي تصف كيف يتعلم كل فرد.","**[[التعلم المستند إلى الدماغ|ar.l09.brain]]** (كين وكين): الدماغ اجتماعي يبحث عن المعنى، والانفعالات أساسية في التعلم، والتعلم يتعزز بالتحدي ويُكبح بالتهديد؛ لذلك يجمع المعلم بيئة خالية من السخرية والخوف مع مهام تتحدى الطلاب.","عناصره ثلاثة: **الاسترخاء اليقظ** (أمان نفسي مع تحدٍّ مرتفع)، والانغماس المنظم في خبرات حقيقية، والمعالجة النشطة بالتلخيص والتطبيق، كأن يلخص الطلاب المفهوم بكلماتهم ويطبقوه على موقف حقيقي.","**[[الأسلوب المعرفي|ar.l09.styles]]** طريقة ثابتة نسبياً تصف كيف يتعلم الفرد لا مقدار ذكائه، ولا أسلوب أفضل مطلقاً؛ ونموذج **دن ودن** يربط أسلوب التعلم بعناصر بيئية وانفعالية واجتماعية وجسمية ونفسية.","**ويتكن**: المعتمد على المجال يدرك الكل ويتأثر بالسياق ويفضل الجماعة، والمستقل يحلل الأجزاء ويفضل العمل الفردي؛ و**كاجان**: المندفع سريع كثير الخطأ، والمتروي متأنٍّ أقل خطأً.","في الصف: طالب يجيب فور سماع السؤال فيخطئ كثيراً رغم قدرته؛ يُعالج اندفاعه بتدريبه على التوقف وفحص البدائل وتمديد وقت الانتظار، لا بحرمانه من المشاركة ولا بنقله إلى مجموعة أضعف."]}],"L10":[{"pts":["**[[الدافعية|ar.l10.motiv]]** حالة داخلية تحرك السلوك نحو هدف وتحافظ عليه، وأولى خصائصها الغرضية؛ والدافع داخلي والحافز خارجي والباعث هدف يجذب، وهي **داخلية** من المهمة نفسها أو **خارجية** من المكافأة.","في الصف: طالب كان يرسم لمتعته، فصار المعلم يعطيه درجة على كل رسمة، فلما توقفت الدرجات توقف عن الرسم؛ فالإفراط في المكافآت الخارجية أضعف دافعيته الداخلية.","[[هرم ماسلو|ar.l10.maslow]] يرتب الحاجات: فسيولوجية ثم أمن ثم انتماء ثم تقدير ثم تحقيق الذات في القمة، ولا تبرز الحاجة الأعلى بقوة قبل إشباع الأدنى إشباعاً كافياً لا كاملاً؛ فمع الطالب الجائع أو المتنمَّر عليه يبدأ المعلم بطعامه وأمنه قبل الحوافز.","**واينر**: القدرة سبب داخلي ثابت، والجهد داخلي متغير قابل للضبط؛ فعزو الفشل إلى الجهد يحفّز وإلى القدرة يحبط، كأن يقول المعلم لمن قال «أنا غبي في الرياضيات»: «أخطأت في خطوتين لم نتدرب عليهما».","**العجز المتعلم** (سليجمان) توقف عن المحاولة رغم القدرة بعد فشل متكرر، كمن يقول «مهما ذاكرت سأرسب»؛ أما الإحباط فانفعال مؤقت يقتصر على الموقف، كمن مزّق ورقته غاضباً ثم واصل المشاركة في بقية المهام.","**[[الكفاءة الذاتية|ar.l10.selfeff]]** تُبنى بخبرات نجاح متدرجة، و**دويك** تفضّل توجه الإتقان والعقلية النامية؛ و**[[يركس–دودسون|ar.l10.achieve]]**: أفضل أداء عند **استثارة متوسطة**، وذو دافع الإنجاز يختار مهاماً متوسطة الصعوبة.","نموذج **كيلر** للدافعية أربعة عناصر: **الانتباه** يُثار بالمفاجأة والتنويع، و**الصلة** بربط الدرس بحياة الطالب، و**الثقة** بمهام متدرجة تضمن نجاحاً مبكراً، والرضا بإعلان الإنجاز.","نظرية **خفض الحافز** (كلارك هل): الحاجة تولد حافزاً يدفع السلوك، وإشباعها يخفض الحافز فيتعزز السلوك الذي أشبعها، كالأكل حين يشتد الجوع."],"map":{"type":"steps","head":true,"title":["Maslow — Hierarchy of Needs","هرم الحاجات عند ماسلو: الحاجة الدنيا تُشبع أولاً"],"brackets":[{"from":0,"to":3,"n":"حاجات نقص"},{"from":4,"to":4,"n":"حاجة نمو"}],"groups":[{"n":"فسيولوجية","d":"ar.l10.maslow","tag":"الجائع لا يتعلم: ابدأ بها"},{"n":"أمن","d":"ar.l10.maslow","tag":"الخائف أو المتنمَّر عليه"},{"n":"انتماء وحب","d":"ar.l10.maslow"},{"n":"تقدير","d":"ar.l10.maslow"},{"n":"تحقيق الذات","d":"ar.l10.maslow","hl":true,"tag":"القمة","trap":"في الصورة السباعية: المعرفية والجمالية قبلها لا بعدها"}]},"cmp":{"title":"العزو عند واينر: لماذا نجحت أو فشلت؟","cols":["الموقع","الثبات"],"rows":[{"k":"**القدرة**","a":"داخلي","b":"ثابت"},{"k":"**الجهد**","a":"داخلي","b":"متغير · **قابل للضبط**: أفضل عزو للفشل"},{"k":"**صعوبة المهمة**","a":"خارجي","b":"ثابت"},{"k":"**الحظ**","a":"خارجي","b":"متغير"}]}},{"pts":["الذكاء قدرة عقلية عامة على التعلم والتفكير المجرد والتكيف وحل المشكلات، ويسأل عنه الاختبار من ثلاث جهات: كيف يُقاس، وكيف تُصنف درجاته، ومن صاحب كل نظرية فيه.","**بينيه** وضع أول اختبار ذكاء (1905) ومفهوم العمر العقلي، و**جالتون** أكد الوراثة وابتكر معامل الارتباط، و**رافن** وضع مصفوفات غير لفظية تناسب من لا يجيد اللغة.","**[[نسبة الذكاء|ar.l10.iq]]** في صورتها الأولى العمر العقلي ÷ الزمني × 100، فعمر عقلي 10 وزمني 8 يعطي 125؛ والاختبارات الحديثة تحسبها **انحرافية** متوسطها 100 وانحرافها 15، وهي **ثابتة نسبياً**، ولا تُستخدم وحدها للتصنيف ولا تُعلن للطلاب.","في الصف: طالب نال 68 في اختبار مقنن مع قصور واضح في مهارات الحياة اليومية يُصنف إعاقة فكرية لا بطء تعلم؛ لأن **التصنيف**: 90–109 متوسط، و 70–85 بطيء التعلم، وأقل من 70 إعاقة فكرية، و 130 فأكثر موهوب.","[[النظريات العاملية|ar.l10.factor]]: سبيرمان عامل عام (g) وعوامل خاصة، وثيرستون سبع قدرات أولية، وجيلفورد بنية العقل والتمييز بين التقاربي والتباعدي، و**كاتل** ذكاء سائل فطري يتراجع مع العمر ومتبلور مكتسب يزداد بالخبرة.","ونظريات أوسع من الاختبار: [[جاردنر|ar.l08.gardner]] ثمانية ذكاءات متعددة، و[[ستيرنبرغ|ar.l10.sternberg]] ذكاء ثلاثي تحليلي وإبداعي وعملي، كطالب متوسط لفظياً يدير مقصف المدرسة بنجاح، و[[جولمان|ar.l10.goleman]] ذكاء وجداني يفهم الانفعالات ويديرها."],"map":{"type":"cards","title":["Theories of Intelligence","نظريات الذكاء"],"groups":[{"n":"النظريات العاملية","ar":"ذكاء عام وقدرات","items":[{"n":"سبيرمان","who":"Spearman · العاملان","ar":"عامل عام g وعوامل خاصة s","d":"ar.l10.factor"},{"n":"ثيرستون","who":"Thurstone · القدرات الأولية","ar":"سبع قدرات"},{"n":"جيلفورد","who":"Guilford · بنية العقل","ar":"التفكير التقاربي والتباعدي"},{"n":"كاتل","who":"Cattell · السائل والمتبلور","ar":"السائل يتراجع والمتبلور يزداد"}]},{"n":"ذكاءات متعددة الأنواع","ar":"أوسع من الاختبار","items":[{"n":"جاردنر","who":"Gardner · الذكاءات المتعددة","ar":"ثمانية ذكاءات","d":"ar.l08.gardner"},{"n":"ستيرنبرغ","who":"Sternberg · الذكاء الثلاثي","ar":"تحليلي وإبداعي وعملي","d":"ar.l10.sternberg"},{"n":"جولمان","who":"Goleman · الذكاء الوجداني","ar":"خمسة مكونات","d":"ar.l10.goleman"}]}]}},{"pts":["مهارات التفكير **العليا** في بلوم المعدل التحليل والتقويم والإبداع، وتُستثار بالأسئلة المفتوحة مع انتظار 3–5 ثوانٍ؛ ويتناول هذا القسم ثلاث عمليات: التفكير الناقد الذي يقوّم، وما وراء المعرفة التي تراقب التفكير، وحل المشكلات بخطوات منظمة.","**[[التفكير الناقد|ar.l10.critical]]** فحص المعلومات والحجج وتقويمها بمعايير، ومنطلقه الشك المنهجي لا الرفض؛ ومهاراته عند واطسون وجليسر: الاستنتاج، والتعرف على **الافتراضات**، والاستنباط، والتفسير، وتقويم الحجج.","**الناقد** يفرز ويقوّم، كأن يختار أفضل 5 أفكار من 20، و**الإبداعي** يولّد العشرين؛ وتقييم مواقع الإنترنت من حيث الدقة والمصداقية، أو تقديم تفسيرات منطقية للنتائج، **تفكير ناقد** لأنه حكم بمعايير.","في الصف: بعد وحدة عن المستكشفين الأوائل، أعلى مستوى للتفكير الناقد كتابة مقال من وجهة نظرهم لأنه يحلل الدوافع ويحكم عليها؛ أما الخط الزمني والاختبار القصير فتذكّر، والرسم التخيلي إبداع لا نقد.","**[[ما وراء المعرفة|ar.l10.meta]]** (فلافل) تفكير في التفكير: تخطيط قبل المهمة، ومراقبة أثناءها، وتقويم بعدها؛ وتنميها أسئلة مثل «كيف توصلت؟» وجدول KWL، أما القراءة الصامتة والحفظ فمهارات معرفية لا ما وراء معرفية.","**حل المشكلات** عند ديوي خمس خطوات: الشعور بالمشكلة، ثم تحديدها، ثم اقتراح الحلول (الفروض)، ثم استنتاج ما يترتب على كل فرض، ثم **اختبار الفروض** بالملاحظة والتجربة لقبولها أو رفضها؛ وتأتي في الأسئلة غالباً: الشعور، فالتحديد، فوضع الفروض، فاختبارها، فالوصول إلى النتيجة، وتضيف كتب كثيرة جمع المعلومات بعد التحديد؛ وهي خطوات التفكير العلمي نفسها، والشعور بالمشكلة يسبق تحديدها دائماً.","**التفكير المركب** يضم التفكير الناقد والإبداعي وحل المشكلات و**اتخاذ القرار**، ويُبنى على مهارات التفكير الأساسية كالملاحظة والمقارنة والتصنيف؛ واتخاذ القرار موازنة بدائل وفق معايير ثم اختيار مسبَّب."]},{"pts":["**[[التفكير الإبداعي|ar.l10.creative]]** ينتج حلولاً جديدة أصيلة، وأساسه **التفكير التباعدي** عند جيلفورد، أي توليد حلول متعددة لمشكلة واحدة؛ ويُسأل عنه من ثلاث جهات: مكوناته، ومراحله، وطرق تنميته ومعوقاته.","مكوناته عند جيلفورد وتورانس: الطلاقة (عدد الأفكار)، والمرونة (تنوع فئاتها)، والأصالة (ندرتها)، والإفاضة (تفاصيلها)، والحساسية للمشكلات (رؤية ما لا يراه الآخرون).","في الصف: «اذكر أكبر عدد من استخدامات القلم»؛ عدد الإجابات طلاقة، وتنوع فئاتها مرونة، والإجابة التي لم يذكرها أحد أصالة، وشرح تفاصيلها ورسمها إفاضة.","مراحل **والاس** أربع مرتبة: الإعداد بجمع المعلومات، ثم الاحتضان حين تُترك المشكلة تختمر، ثم الإلهام بومضة الحل، ثم التحقق؛ فمن ترك مشكلته وذهب يمشي ثم خطر له الحل كان في الاحتضان قبل الإلهام.","**العصف الذهني** (أوزبورن) يقدم الكم على الكيف ويرجئ الحكم، فلا نقد للأفكار أثناء طرحها؛ و**معوقاته** أي معوقات الإبداع: الخوف من الخطأ، والنقد المبكر وهو أكبرها، والجمود الذهني.","**[[أدوات توليد الأفكار|ar.l10.creatools]]**: الأسئلة المفتوحة مثل «ماذا لو؟» وكتابة نهاية جديدة لقصة، وسكامبر، والتفكير الجانبي، والإثارة العشوائية؛ أما رسم بطل القصة أو تمثيل أحداثها فإعادة إنتاج لما فيها لا إبداع."],"map":{"type":"fan","title":["Torrance — Components of Creativity","مكونات الإبداع (جيلفورد وتورانس)"],"groups":[{"n":"الطلاقة","ar":"**عدد** الأفكار.","items":[{"n":"لفظية"},{"n":"فكرية"},{"n":"أشكال"},{"n":"تداعي"}],"d":"ar.l10.creatools"},{"n":"المرونة","ar":"**تنوع** فئات الأفكار وتغيير الزاوية.","items":[{"n":"تكيفية"},{"n":"تلقائية"}],"d":"ar.l10.creatools"},{"n":"الأصالة","ar":"**ندرة** الفكرة وجدّتها.","d":"ar.l10.creative"},{"n":"الإفاضة","ar":"إضافة **التفاصيل**.","d":"ar.l10.creative"},{"n":"الحساسية للمشكلات","ar":"رؤية ما لا يراه الآخرون.","d":"ar.l10.creative"}]}},{"pts":["يُعلَّم التفكير مباشرة في برامج مستقلة أو مدمجاً في المحتوى، وأشهر ما يسأل عنه الاختبار قبعات ديبونو الست، وبرنامج كورت، ونموذج هيرمان، والتمييز بين التفكير التقاربي والتباعدي.","**[[القبعات الست|ar.l10.debono]]** تعلّم النظر من زوايا متعددة وتفصل الأنا عن الفكرة: البيضاء حقائق، والحمراء مشاعر وحدس، والسوداء حذر ومخاطر، والصفراء فوائد، والخضراء إبداع وبدائل، والزرقاء ضبط التفكير والخلاصة.","في الصف: «أشعر أنها لا تعجبني» بلا تبرير القبعة **الحمراء**، و«ستفشل لأن التكلفة مرتفعة» السوداء، و«لنعرض الأرقام أولاً» البيضاء، و«لنلخص ما توصلنا إليه» الزرقاء.","**برنامج كورت** (ديبونو) يعلّم التفكير مباشرة في ست وحدات، ومن أدواته PMI (إيجابيات وسلبيات ونقاط مثيرة للاهتمام)؛ و**[[هيرمان|ar.l10.progs]]** يصف أربعة أنماط: النمط A تحليلي، والنمط B منظم، والنمط C عاطفي اجتماعي، والنمط D تخيّلي.","التفكير **التقاربي** يصل إلى إجابة واحدة صحيحة، و**التباعدي** يولّد إجابات متعددة، والاختبارات الموضوعية تقيس التقاربي غالباً؛ فسؤال «كيف نحافظ على سلامة البيئة؟» يشجع الإبداع، و«ما مكونات الماء؟» تذكّر.","ومن الاستراتيجيات الصفية لتنمية التفكير: **الأسئلة السابرة** التي تعمّق إجابة الطالب، والخرائط الذهنية (بوزان) والمفاهيمية (نوفاك)، والمناظرة، ولعب الأدوار."],"map":{"type":"fan","title":["de Bono — Six Thinking Hats","قبعات ديبونو الست"],"groups":[{"n":"البيضاء","ar":"حقائق ومعلومات: «ما الأرقام؟»","c":"#64748B","d":"ar.l10.debono"},{"n":"الحمراء","ar":"مشاعر وحدس.","c":"#B42318","d":"ar.l10.debono"},{"n":"السوداء","ar":"حذر وسلبيات ومخاطر.","c":"#475467","d":"ar.l10.debono"},{"n":"الصفراء","ar":"إيجابيات وفوائد.","c":"#A15C07","d":"ar.l10.debono"},{"n":"الخضراء","ar":"إبداع وبدائل.","c":"#1F6B4C","d":"ar.l10.debono"},{"n":"الزرقاء","ar":"ضبط التفكير والخلاصة: «لنلخص».","c":"#2F6690","d":"ar.l10.debono"}]}},{"pts":["يطلب مؤشر 5.3 أن يبين المعلم كيف تُكتسب **[[عادات العقل|ar.l10.habits]]** وكيف تؤثر الاتجاهات والقيم في التعلم؛ والعادات عند كوستا وكاليك 16 عادة، وهي سلوكيات ذكية يلجأ إليها الطالب أمام مشكلة لا يعرف حلها فوراً.","تُميَّز العادة بالسلوك: من لا يستسلم يُظهر المثابرة، ومن يراجع حله الكفاح من أجل الدقة، ومن يقرأ السؤال كاملاً قبل الحل **التحكم بالتهور**، ومن يعيد صياغة كلام زميله الإصغاء بتفهم، ومن يصف كيف وصل التفكير حول التفكير.","تُنمّى العادات بتسميتها للطلاب، وبنمذجتها بالتفكير بصوت مسموع، وبتعزيز ظهورها؛ فهي ميل يُتعلم ويُنمّى، لا قدرة فطرية ثابتة ولا معارف تُحفظ عن التفكير.","**[[الاتجاه|ar.l10.attitude]]** استعداد مكتسب للقبول أو الرفض نحو موضوع، ومكوناته معرفي ووجداني وسلوكي: اعتقاد الطالب بأهمية القراءة، ثم شعوره بالمتعة فيها، ثم ميله إلى استعارة الكتب؛ والسلبي منه نبوءة تحقق ذاتها.","في الصف: طالبة تكرر «أنا لا أفهم الرياضيات أبداً» فتتجنب المحاولة؛ يعدّل المعلم اتجاهها بخبرات نجاح متدرجة وربط المادة بحياتها والقدوة، لا بالوعظ ولا بمقارنتها بالمتفوقات ولا بإعفائها من المهام.","**القيم** معايير يحكم بها المتعلم، فإذا رأى المحتوى متصلاً بقيمه كالإتقان وخدمة المجتمع والأمانة العلمية زاد اندماجه في التعلم."]}],"L15":[{"pts":["أربعة مصطلحات تتدرج من الأشمل إلى الأخص: التقويم حكم يتبعه قرار تعديل وعلاج، والتقييم حكم على قيمة الأداء بمعيار، والقياس رقم بلا حكم، والاختبار أداة نجمع بها الرقم لا نوع من التقويم.","تعرّف لائحة تقويم الطالب 2025 التقويم بأنه عملية منهجية منظمة لجمع المعلومات وتحليلها وإصدار أحكام وبناء خطط علاجية وتطويرية في ضوئها؛ فالعلاج هو ما يميزه عن التقييم.","الاختبار **التحصيلي** يقيس ما تعلمه الطالب فعلاً، واختبار **الاستعداد** يتنبأ بنجاحه مستقبلاً، واختبار الذكاء للقدرة العقلية العامة؛ والاختبار **المقنن** يعده متخصصون بتعليمات وظروف موحدة ومعايير، بخلاف اختبار المعلم ولو كان جيداً.","التقويم الجيد مستمر، شامل لجوانب المتعلم، تعاوني، **علمي** (صادق وثابت وموضوعي)، واقتصادي؛ و[[مواصفات الاختبار الجيد|ar.l15.eval]] الصدق والثبات والموضوعية و**التمييز** و**الشمول** لمحتوى المادة وأهدافها.","في الصف: رصد المعلم «18 من 25» فهذا قياس، وقال «مستواه جيد جداً» فهذا تقييم، وأضاف «سأعطيه ورقة علاجية في الكسور» فصار تقويماً ← والخطأ الشائع تسمية الحكم وحده تقويماً."],"map":{"type":"nest","title":["Measurement ⊂ Assessment ⊂ Evaluation","من الأشمل إلى الأخص"],"axis":["الأشمل","الأخص"],"groups":[{"n":"التقويم","tag":"حكم + تعديل وعلاج","ar":"«يحتاج تدريباً على الكسور وسأعطيه ورقة علاجية»"},{"n":"التقييم","tag":"حكم بمعيار","ar":"«مستواه جيد جداً»"},{"n":"القياس","tag":"رقم بلا حكم","ar":"«حصل خالد على 18 من 25»"},{"n":"الاختبار","tag":"أداة القياس","ar":"**أداة** نجمع بها الرقم، لا نوع من التقويم","trap":"الأشمل التقويم، والاختبار أداة قياس فقط"}]}},{"pts":["يُصنَّف التقويم بسؤالين: متى نقوّم ولأي غرض (قبلي، تكويني، ختامي، تتبعي)، وبماذا نقارن الدرجة (محكي، معياري، ذاتي المرجع)؛ والموقف الواحد قد يجمع التصنيفين معاً.","[[**القبلي**|ar.l15.types]] يسبق التعلم، وتسميه لائحة تقويم الطالب 2025 «القبلي (التشخيصي)»: يقف على الاستعداد والمتطلبات السابقة ويشخّص ما يملكه الطالب؛ فإن فرّق السؤال بينهما فالاستعداد قبلي، ونقاط القوة والضعف وأسباب الصعوبة تشخيصي.","**التكويني (البنائي)** أثناء التدريس لتحسين التعلم وتعديل التدريس لا لحكم نهائي، ويُوصف بالمستمر لأنه يرافق التعلم؛ و**الختامي (التجميعي)** نهاية الوحدة أو الفصل لأحكام النجاح والانتقال، و**التتبعي** بعده بفترة لقياس بقاء الأثر.","[[**محكي المرجع**|ar.l15.ref]] يقارن بمحك إتقان (أتقن أم لم يتقن)، و**معياري المرجع** يقارن بالأقران، كمعرفة ترتيب طالب منقول بين زملائه الجدد، و**التقويم ذاتي المرجع** يقارن الطالب بدرجته السابقة.","**تقويم التعلم** ختامي للحكم، والتقويم من أجل التعلم تكويني يقدّم أدلة يفسرها المعلم والطالب لتوجيه الخطوة التالية، والتقويم كتعلم يراقب فيه الطالب تعلمه بنفسه.","في الصف: معلم يبني اختباراً تشخيصياً ← هدفه الأساسي تحديد نقاط القوة والضعف وحاجات الطلاب التعليمية (دليل المتقدم) ← لا ترتيبهم ولا التنبؤ بمستقبلهم؛ ويُشخَّص الخطأ المتكرر في مهارة قبل علاجه."]},{"pts":["يطلب المؤشر 10.1 خطة تقويم تجمع **الرسمي** و**غير الرسمي** في دورتين: **قصيرة المدى** و**طويلة المدى**؛ فالخطة الجيدة لا تعتمد على الاختبار وحده.","الرسمي مخطط منظم موثق بشروط وزمن ودرجة، تُرصد نتائجه ويُبنى عليه حكم؛ وغير الرسمي (الاعتيادي) يجري تلقائياً أثناء التدريس بالملاحظة والأسئلة الشفهية و**بطاقة الخروج** والسبورات الصغيرة، ليعدّل المعلم تدريسه فوراً.","الدورة القصيرة داخل الحصة أو بين حصة وأخرى يعقبها تعديل أو تغذية راجعة سريعة، والطويلة على مستوى الوحدة والفترة والعام تقيس تحقق نواتج التعلم وتوجه الخطط العلاجية والإثرائية والتقارير.","خطة التقويم تحدد لكل ناتج تعلم: ماذا يُقوَّم، وبأي أداة، ومتى، وكيف يُصحح، وكيف تُوظف النتائج، مع توزيع الدرجات على الأدوات.","في الصف: معلم يستعمل طرقاً رسمية وغير رسمية أثناء كل وحدة ← فائدتها الأساسية مراقبة تحصيل الطلاب وفاعلية تدريسه وتعديله عند الحاجة (دليل قياس) ← لا تدريبهم على التقويم الذاتي ولا جمع بيانات للحكم الختامي.","في الصف: بطاقة خروج كشفت أن نصف الصف أخطأ في وحدة القياس، فبدأ المعلم الحصة التالية بمراجعة قصيرة ← تقويم تكويني غير رسمي في الدورة القصيرة ← لأنه عدّل التدريس ولم يُصدر حكماً."]},{"pts":["[[**التقويم البديل**|ar.l15.authentic]] (الأصيل أو الواقعي) يقيس الأداء في **مهام حقيقية** بمعايير معلنة مسبقاً، ويُدمج مع التقويم التقليدي للوصول إلى حكم دقيق؛ وأدواته قوائم وسلالم وروبركات، وملف إنجاز، وسجلات وملاحظة.","**قائمة الشطب (الرصد)** تسأل: موجود أم لا؟ و**سلم التقدير العددي** (1–5) أو اللفظي يسأل: بأي درجة؟ و[[**الروبرك (سلم التقدير الوصفي)**|ar.l15.rubric]] يصف كيف يبدو كل مستوى لكل معيار؛ التحليلي درجة لكل معيار، والكلي حكم عام واحد.","[[**ملف الإنجاز (البورتفوليو)**|ar.l15.portfolio]] جمع منظم لأعمال مؤرخة هدفه **التأمل الذاتي** ومتابعة التقدم لا الأرشفة؛ و**التقويم الذاتي** و**تقويم الأقران** يحكمان على العمل بمحكات واضحة معدة مسبقاً.","المهارة العملية كالوضوء والتجربة تُقوَّم **بالملاحظة** وقائمة الشطب لا بالاختبار الكتابي؛ ومن [[أدوات أخرى|ar.l15.tools]] السجل القصصي يكتبه المعلم، وسجل سير التعلم يكتبه الطالب، والمقابلة، و**التقارير الذاتية** للاتجاهات والميول.","في الصف: طلب المعلم من طلاب الثالث الثانوي تعبئة نموذج طلب توظيف حقيقي مع سيرتهم الذاتية ← تقويم أداء يطبق فيه الطالب ما تعلمه نظرياً على أرض الواقع (دليل المتقدم) ← لا تطبيق ما وراء المعرفة ولا تحديد مهاراته التقنية.","في الصف: معلم يطلب من كل عضو في المجموعة تقويم مشاركات زملائه ودورهم في المهمة ← تقويم أقران يضمن مشاركة الجميع (دليل قياس) ← أما مطالبتهم بالتعاون فبديهي يفرضه النشاط، وتسليم منتج واحد لا يضمن المشاركة."]},{"pts":["يقسم دليل الاختبارات 2025 الأسئلة نوعين: [[**الموضوعية**|ar.l15.objective]] ذات الإجابة المنتقاة، وهي الاختيار من متعدد والصواب والخطأ والمطابقة والإكمال، و**المقالية** الحرة أو المقيدة.","الموضوعية لا تتأثر بذاتية المصحح وتغطي محتوى واسعاً، لكنها عرضة للتخمين وتحتاج وقتاً في الإعداد ولا تقيس التعبير؛ والمقالية تقيس التنظيم والتفكير العليا بلا تخمين، لكن تصحيحها ذاتي فينخفض ثباتها.","**أسئلة الإجابة القصيرة والمقالية المقيدة ليست** موضوعية، فالدليل يعدّ السؤال القصير («عدّد، عرّف، علّل») مقالياً مقيداً؛ أما الإكمال فموضوعي لأن إجابته كلمة محددة سلفاً.","قواعد الصياغة: بدائل متجانسة معقولة متقاربة الطول، ولا كلمات جزم أو تعميم في الصواب والخطأ، واستجابات المطابقة أكثر من مقدماتها، وفراغ واحد مهم قرب آخر جملة الإكمال.","لتقليل التخمين **تُزاد** البدائل الفعالة لا تُقلل، وتُرتب الفقرات من السهل إلى الصعب فيستمر متدني التحصيل في الإجابة ويقل قلقه.","في الصف: عبارة «كل المعادن تتمدد بالحرارة دائماً» في سؤال صواب وخطأ ← تُعاد صياغتها «يتمدد الحديد عند تسخينه» ← لأن كلمتي الجزم «كل» و«دائماً» تكشفان الإجابة لمن لم يتعلم."]},{"pts":["خطوات البناء بالترتيب: **تحديد الأهداف** أولاً، ثم تحليل المحتوى، ثم جدول المواصفات، ثم صياغة الفقرات، ثم التعليمات، ثم التجريب والتحليل؛ فالخطوة الأولى ليست كتابة الأسئلة ولا تحليل المحتوى.","[[**جدول المواصفات**|ar.l15.tos]] مخطط ثنائي البعد يقاطع المحتوى مع مستويات الأهداف، ووظيفته الأولى صدق المحتوى لا الثبات؛ ووزن الموضوع يساوي عدد حصصه أو أهدافه ÷ المجموع × 100.","مثال الحساب: وحدة لها 6 حصص من 20 حصة، والاختبار 40 سؤالاً، فنصيبها 6 ÷ 20 × 40 = 12 سؤالاً؛ ثم توزَّع أسئلة كل موضوع على مستويات الأهداف بأوزانها.","التعليمات تذكر الزمن، وطريقة الإجابة ومكانها، ودرجة كل سؤال، وتنبيهات التخمين؛ وتصحيح المقالي بنموذج إجابة ومحكات مسبقة، وتصحيح السؤال الواحد لكل الطلاب قبل غيره، وإخفاء الأسماء.","التصحيح **بمعيار واحد للجميع**، فظرف الطالب الشخصي يُعالج بطرق تربوية أخرى لا برفع درجته؛ واختبار المعلم هو الأنسب لقياس تمكن طلابه مما درسوه في فترة محددة (دليل قياس).","في الصف: معلمة وجدت في اختبارها 15 سؤالاً من الدرس الأول و 3 فقط من بقية الوحدة ← أسئلة تركز على موضوعات دون أخرى يعالجها **جدول مواصفات** قبل الكتابة ← لأن الخلل في صدق المحتوى لا في الثبات."]},{"pts":["مؤشر 10.2 يفرّق بين أمرين: [[**التسهيلات**|ar.l15.access]] تغيّر طريقة الاختبار أو مكانه أو زمنه **دون خفض المستوى المقيس**، والتعديل يغيّر محتوى التقويم أو مستواه وفق الخطة التربوية الفردية.","تسهيلات عامة: زمن كافٍ، ومكان مناسب فردي أو جماعي، ومرونة في المواعيد، وتجزئة الاختبار، و**ألا يُختبر في أكثر من مادة تحريرية في اليوم الواحد** (وغيره من الطلاب حتى مادتين).","بحسب الإعاقة: البصرية برايل أو قارئ كاتب مبصر أو طباعة مكبرة، والسمعية أسئلة موضوعية واضحة ولغة إشارة بلا محاسبة على الإملاء، وصعوبات التعلم قراءة الأسئلة بصوت عال، وفرط الحركة فترات قصيرة.","يشرف **معلم التربية الخاصة** على التقويم بالتعاون مع معلم التعليم العام، والتسهيل **حق** للطالب لا تفضيل؛ ومن لم يستفد مما يقدم في الفصل العام **يُقوَّم في محتوى خطته الفردية**.","في الصف: طالب ذو صعوبة في القراءة يُختبر في الرياضيات، فيقرأ له المعلم الأسئلة في غرفة هادئة مع وقت إضافي والمسائل نفسها ← هذا تسهيل ← أما أسئلة من محتوى خطته الفردية فتعديل."],"map":{"type":"fan","title":["Accommodations by Disability","تسهيلات حسب نوع الإعاقة"],"groups":[{"n":"البصرية","ar":"برايل، أو شفهي، أو **قارئ كاتب مبصر**، وطباعة مكبرة","d":"ar.l15.access"},{"n":"السمعية","ar":"أسئلة موضوعية واضحة، ولغة الإشارة، و**لا محاسبة على الإملاء والنحو**","d":"ar.l15.access"},{"n":"صعوبات التعلم","ar":"**قراءة الأسئلة بصوت عال**، وإجابة شفهية، وفترات راحة","d":"ar.l15.access"},{"n":"فرط الحركة وتشتت الانتباه","ar":"**فترات قصيرة**، والسماح بالتحرك، وركن بعيد عن المشتتات","d":"ar.l15.access"},{"n":"الجسمية واضطرابات النطق","ar":"أجهزة تعويضية وكاتب موثوق، ولا محاسبة على أخطاء الاضطراب","d":"ar.l15.access"}]}},{"pts":["[[لائحة تقويم الطالب|ar.l15.reg]] تفرّق بين مرحلتين: **الصفان الأول والثاني الابتدائي** يُقوَّمان تكوينياً على [[مستويات أداء|ar.l15.levels]] وصفية في معظم المواد (التقويم المستمر للصفوف الأولية)، ومن **الثالث الابتدائي** يكون التقويم بالدرجات.","ينجح طالب الصفين الأول والثاني بإتقان **75%** من معايير المادة بما فيها معايير الحد الأدنى؛ فمن أتقن 90% وفاته معيار واحد من الحد الأدنى غير مجتاز.","ومن الثالث الابتدائي: **60 درجة** للتقويمات التكوينية و**40 درجة** لاختبار نهاية الفترة، والنجاح بتحقيق **النهاية الصغرى 50%** و**النسبة الشرطية 20%** من درجة الاختبار التحريري، ولا تُطبق الشرطية في الدور الثاني.","في الصف: طالب في الثاني متوسط مجموعه 58، لكن درجته في الاختبار التحريري لنهاية العام 6 من 40، والشرطية 8 ← لم يحقق النسبة الشرطية فيدخل الدور الثاني ← ولا تُطبق عليه الشرطية هناك.","[[**نافس**|ar.l15.intl]] اختبارات وطنية للصفوف 3 و 6 و 9 تشخّص المستوى الوطني لتحسين التعليم، لا لنجاح الطالب أو ترتيبه؛ أما **TALIS** فمسح دولي عن المعلمين وبيئات التدريس، لا اختبار للطلاب.","اختبار **PISA** من منظمة OECD لعمر 15 سنة كل 3 سنوات (وكل 4 بعد دورة 2025)، واختبار **TIMSS** للصفين الرابع والثامن كل 4 سنوات، واختبار PIRLS للقراءة في الصف الرابع كل 5 سنوات."]}],"L16":[{"pts":["[[**الصدق**|ar.l16.validity]] أن يقيس الاختبار ما وُضع لقياسه فعلاً، وهو أهم خصائص الاختبار وأعمها؛ ولا يكون مطلقاً بل لغرض معين وفئة معينة، فالاختبار الصادق لغرض قد لا يصدق لغيره.","يضعف الصدق غموض الأسئلة، وتلميحات تكشف الإجابة، واستعمال الاختبار لغير غرضه أو فئته، وسوء ظروف التطبيق.","أنواعه: صدق المحتوى ويتحقق بجدول المواصفات وتحكيم المختصين، والصدق الظاهري مجرد مظهر وهو أضعفها، وصدق البناء اتساق الاختبار مع النظرية المفسرة للسمة ويُتحقق منه بالتحليل العاملي، ثم صدق المحك.","صدق المحك بنوعيه يُقدَّر **بمعامل ارتباط** بين درجات الاختبار ودرجات محك خارجي: التلازمي إذا جُمع المحك في الوقت نفسه، والتنبؤي إذا جُمع في المستقبل كالمعدل الجامعي بعد اختبار القبول.","الصدق الذاتي هو الجذر التربيعي لمعامل الثبات، وهو الحد الأعلى للصدق: ثبات 0.64 يعطي صدقاً ذاتياً 0.8، وثبات 0.81 يعطي 0.9.","في الصف: اختبار قبول تُقارن درجاته بنجاح الطلاب بعد سنة ← صدق تنبؤي لأن المحك في المستقبل ← لا تلازمي، فمحك التلازمي يُجمع في الوقت نفسه كدرجات اختبار مقنن مماثل."],"map":{"type":"tree","title":["Types of Validity","أنواع الصدق"],"groups":[{"n":"المرتبط بالمحتوى","idea":"هل تمثّل الأسئلة ما دُرّس؟","d":"ar.l16.validity","items":[{"n":"صدق المحتوى","ar":"**بجدول المواصفات** وتحكيم المختصين","d":"ar.l16.validity"},{"n":"الصدق الظاهري","ar":"يبدو في شكله أنه يقيس ما وُضع له؛ **أضعفها**"}]},{"n":"المرتبط بمحك","idea":"معامل ارتباط بمحك خارجي","d":"ar.l16.validity","items":[{"n":"صدق المحك التلازمي","ar":"محك يُجمع **في الوقت نفسه** (اختبار مقنن مماثل)"},{"n":"صدق المحك التنبؤي","ar":"محك **مستقبلي** (المعدل الجامعي من اختبار القبول)"}],"trap":"محك مستقبلي = تنبؤي"},{"n":"صدق البناء","ar":"(المفهوم / التكوين الفرضي)","idea":"انسجام مع النظرية","d":"ar.l16.validity","items":[{"n":"التحليل العاملي","ar":"طريقة **التحقق منه**"}]},{"n":"الصدق الذاتي","idea":"يُحسب من الثبات","d":"ar.l16.validity","items":[{"n":"√ معامل الثبات","ar":"**الحد الأعلى** للصدق"}]}]}},{"pts":["[[**الثبات**|ar.l16.reliab]] اتساق النتائج عند تكرار القياس في ظروف مماثلة، ومعامله بين 0 و 1؛ ويُقدَّر بإعادة التطبيق، أو الصور المتكافئة، أو الاتساق الداخلي من تطبيق واحد، أو اتفاق المصححين.","فرّق بين الطرق بعدد الاختبارات ومرات التطبيق: إعادة التطبيق اختبار واحد مرتين، والصور المتكافئة اختباران لكل منهما مرة، والتجزئة النصفية اختبار واحد مرة واحدة ثم تصحيح سبيرمان براون.","ومعاملا الاتساق الداخلي: كودر ريتشاردسون للفقرات الثنائية (صح أو خطأ)، وكرونباخ ألفا للمقاييس المتدرجة كمقياس ليكرت؛ وكلاهما يقيس الثبات لا الصدق.","[[**الخطأ المعياري للقياس**|ar.l16.coef]] يساوي الانحراف المعياري × √(1 − الثبات)، وكلما كبر قلّ الثبات؛ فبانحراف 10 وثبات 0.84 يكون الخطأ 10 × 0.4 = 4، ودرجة 70 تعني أن الحقيقية غالباً بين 66 و 74.","**عوامل الثبات**: يرتفع بطول الاختبار وتباين العينة وتوسط الصعوبة، وينخفض بالتخمين والغموض والعينة شديدة التجانس؛ و**الموضوعية** شرط للثبات، والثبات شرط **ضروري غير كافٍ** للصدق، فميزان يزيد كيلوغرامين دائماً ثابت غير صادق.","في الصف: طالب أجاب عن فقرة صحيحاً ثم أخطأ فيها عند الإعادة دون تعلم جديد ← هذا ضعف ثبات ← لا ضعف تمييز، فالتمييز يُحكم عليه بالفرق بين الفئتين العليا والدنيا."],"map":{"type":"fan","title":["Estimating Reliability","طرق تقدير الثبات"],"groups":[{"n":"إعادة التطبيق","ar":"الاختبار نفسه بعد فاصل (**الاستقرار**)؛ عيبه أثر الذاكرة","d":"ar.l16.reliab"},{"n":"الصور المتكافئة","ar":"نسختان بمواصفات واحدة (**التكافؤ**)","d":"ar.l16.reliab"},{"n":"التجزئة النصفية","who":"Spearman–Brown سبيرمان براون","ar":"تطبيق واحد: الفردية × الزوجية، ثم ر الكلي = 2ر ÷ (1 + ر)","d":"ar.l16.coef"},{"n":"KR-20 ومعامل ألفا","who":"Kuder–Richardson · Cronbach","ar":"كودر للفقرات **الثنائية**، وألفا **للمتدرج** والمقالي","d":"ar.l16.coef"},{"n":"ثبات المصححين (اتفاق المقيمين)","ar":"اتفاق مصححين مستقلين؛ مؤشر **الموضوعية** في المقالي","d":"ar.l16.reliab"}]}},{"pts":["بعد التصحيح تُحلَّل كل فقرة بثلاثة مؤشرات: الصعوبة، والتمييز بين المتمكن والأقل تمكناً، وفعالية المشتتات؛ و[[**المشتت الفعال**|ar.l16.distract]] تختاره الفئة الدنيا أكثر من العليا، والذي لا يختاره أحد يُستبدل.","التعريف الأول والأشهر: [[**معامل الصعوبة (السهولة)**|ar.l16.difficulty]] يساوي المصيبين ÷ المجيبين، فكلما ارتفع كانت الفقرة **أسهل**؛ وبه تحسب أغلب المراجع، ودليل الاختبارات 2025 في معادلته وتفسيره (100% سهل جداً)، والمقبول الشائع 0.20–0.80.","التعريف الثاني في بعض المراجع: «الصعوبة» نسبة المخطئين و«السهولة» نسبة المصيبين، ومجموعهما 1، وبه جاءت جملة التعريف في الدليل نفسه؛ والاختبار يقصد غالباً المصيبين، فلا تحسب بالمخطئين إلا إذا نص السؤال عليهم.","**معامل الصعوبة في السؤال المقالي** يساوي مجموع درجات الطلاب فيه ÷ (عدد الطلاب × درجة السؤال)؛ فسؤال من 5 لعشرين طالباً مجموع درجاتهم فيه 60 معامله 60 ÷ 100 = 0.60.","[[**معامل التمييز**|ar.l16.discrim]] يساوي (صحيح العليا − صحيح الدنيا) ÷ عدد إحدى الفئتين، بأخذ 27% من كل طرف: 0.40 فأعلى ممتاز، وأقل من 0.20 ضعيف، و**السالب** يُفحص مفتاحه أولاً، فإن صحّ حُذفت الفقرة، والفقرة التي يجيب عنها الجميع تمييزها صفر.","في الصف: فصل من 25 طالباً أجاب 14 منهم عن فقرة صحيحاً ← معامل الصعوبة 14 ÷ 25 = 0.56، فقرة متوسطة داخل توصية الدليل (30%–70%) ← ومن يحسب بالمخطئين يكتب 0.44، فاقرأ تعريف السؤال أولاً."]},{"pts":["مستويات القياس عند **ستيفنز** أربعة، يزيد كل منها على ما قبله خاصية: الاسمي يصنف، والرتبي يرتب، والفتري يساوي المسافات، والنسبي يضيف صفراً حقيقياً؛ ونوع المستوى يحدد العمليات الإحصائية المسموح بها.","**الاسمي** أرقام أو أسماء للتصنيف فقط كأرقام اللاعبين والجنس، و**الرتبي** ترتيب بلا مسافات متساوية كالأول والثاني والثالث وتقديرات ممتاز وجيد.","**الفتري** مسافاته متساوية وصفره اعتباري كدرجات الاختبار والحرارة المئوية، فلا نقول 40 درجة ضعف 20؛ و**النسبي** صفره حقيقي يعني انعدام الصفة كالطول والوزن والزمن، فيجيز «ضعف» و«نصف».","في الصف: طالب حصل على صفر في اختبار الكسور ← أخفق في فقرات هذا الاختبار لا في الكسور كلها، لأن صفر الاختبار اعتباري (فتري)."]},{"pts":["الإحصاء الوصفي يلخص درجات الصف بثلاثة أسئلة: أين تتمركز الدرجات (النزعة المركزية)؟ وكم تتباعد (التشتت)؟ وهل ترتبط درجات اختبارين (الارتباط)؟ ثم تُعرض في جدول أو رسم.","[[**المتوسط**|ar.l16.central]] يتأثر بالقيم المتطرفة، و**الوسيط** القيمة الوسطى بعد الترتيب لا يتأثر بها فهو الأنسب للبيانات الملتوية، والمنوال الأكثر تكراراً ويناسب البيانات النوعية.","**المدى** أكبر قيمة ناقص أصغر قيمة، والتباين متوسط مربعات الانحرافات عن المتوسط، و[[**الانحراف المعياري**|ar.l16.spread]] جذره التربيعي؛ والصف ذو الانحراف الأصغر أكثر تجانساً، والانحراف صفر يعني درجات متساوية.","إضافة ثابت لكل الدرجات ترفع المتوسط ولا تغير الانحراف، والضرب في ثابت يضرب الاثنين؛ و**المدرج التكراري** لعرض توزيع الدرجات، والأعمدة للمقارنة، والدائري للنسب، والخطي للتغير عبر الزمن.","**معامل الارتباط** بين −1 و+1: الإشارة اتجاه (طردي أو عكسي) والقيمة قوة، فأقل من 0.3 ضعيف، ومن 0.3 إلى 0.7 متوسط، وفوقها قوي؛ فارتباط −0.8 أقوى من +0.5، والارتباط لا يثبت السببية.","في الصف: درجات 4، 6، 6، 7، 9، 10، 14 متوسطها 8 ووسيطها 7 ومنوالها 6؛ ولو صارت 14 هي 49 لقفز المتوسط إلى 13 وبقي الوسيط 7 ← لذلك يُختار الوسيط حين توجد قيم متطرفة."]},{"pts":["[[**التوزيع الاعتدالي**|ar.l16.normal]] منحنى جرسي متماثل يتساوى فيه المتوسط والوسيط والمنوال، وفيه نحو 68% من الدرجات ضمن ± انحراف معياري واحد، و 95% ضمن ± انحرافين، و 99.7% ضمن ± ثلاثة.","افهم الالتواء بسؤالين: أين تتكدس أغلب الدرجات؟ وأين القلة؟ فإذا كانت الأغلبية منخفضة وقلة نالت درجات عالية فالاختبار **صعب**، وهذا **الالتواء الموجب**، والمتوسط فيه أكبر من الوسيط لأن القلة العالية ترفعه.","وإذا كانت الأغلبية مرتفعة وقلة منخفضة فالاختبار سهل والالتواء سالب، والمتوسط أصغر من الوسيط. والإشارة تتبع ذيل القلة لا التكدس: ذيل الموجب يمتد نحو الدرجات العالية (يميناً في الرسم)، وذيل السالب نحو المنخفضة (يساراً).","**التفرطح** يصف القمة لا الميل مقارنة بالمنحنى الاعتدالي: مدبب حين تكون قمته أحدّ منه، ومفرطح حين تكون أكثر انبساطاً، والمعتدل بينهما؛ ولا يُعرف من الانحراف المعياري وحده، أما الالتواء فميل التوزيع إلى أحد الجانبين.","[[**الدرجة المعيارية ز**|ar.l16.z]] تساوي (الدرجة − المتوسط) ÷ الانحراف، فمتوسطها 0 وانحرافها 1، والدرجة **ت** = 50 + 10 × ز؛ أما **الرتبة المئينية** 90 فتعني تفوقه على 90% من المجموعة، لا 90% إجابات صحيحة.","في الصف: طالب نال 80 في الرياضيات (متوسط 70، انحراف 5) و 85 في العلوم (متوسط 80، انحراف 10) ← ز الرياضيات 2 وز العلوم 0.5 ← فأداؤه النسبي في الرياضيات أفضل رغم أن درجتها الخام أقل."],"map":{"type":"curves","title":["Skewness — three curves","الالتواء: اسمه من جهة الذيل"],"axis":["درجات منخفضة","مرتفعة"],"mode":"المنوال","mean":"المتوسط","allSame":"المتوسط = الوسيط = المنوال","curves":[{"n":"التواء موجب","skew":1,"c":"#A8562A","order":"من الأصغر: المنوال ← الوسيط ← المتوسط","ar":"الذيل نحو الدرجات **المرتفعة**؛ أغلب الدرجات منخفضة: اختبار **صعب**"},{"n":"اعتدالي","skew":0,"c":"#1F6B4C","ar":"متماثل: 68% ضمن ± انحراف، و 95% ضمن ± انحرافين"},{"n":"التواء سالب","skew":-1,"c":"#33449A","order":"من الأصغر: المتوسط ← الوسيط ← المنوال","ar":"الذيل نحو الدرجات **المنخفضة**؛ أغلب الدرجات مرتفعة: اختبار **سهل**"}],"trap":"اسم الالتواء من جهة الذيل لا القمة: قمة يساراً وذيل يميناً = موجب = صعب"}},{"pts":["مؤشر 10.3 يطلب [[**نماذج رصد**|ar.l16.records]] لإنجاز الطلاب وتقدمهم التراكمي، وتحليل البيانات ببرامج تقنية لاستخلاص مؤشرات الأداء؛ والنموذج الجيد صف لكل طالب، وأعمدة بالمعايير والأداة والتاريخ والإجراء العلاجي.","في الصفين الأول والثاني تدوين **يومي** في سجل متابعة تقويم الطالب، ثم رصد الخلاصة في **النظام الرقمي** نهاية الفترة موثقة بشواهد في ملف الإنجاز.","ببرنامج الجداول يحسب المعلم المتوسط و**نسبة الإتقان لكل معيار** (عدد المتقنين ÷ عدد الطلاب) ونسبة التحسن بين القبلي والبعدي، ويلوّن غير المتقنين بالتنسيق الشرطي.","القرار بعد التحليل: معيار ضعيف لدى **أغلب الصف** يُعاد تدريسه للجميع، ولدى **قلة** خطة علاجية فردية أو في مجموعة صغيرة؛ والمعلم يحلل نتائج طلابه ليحدد مواطن القوة والضعف وأسبابها.","**سرية البيانات**: نتيجة الطالب مسألة تخصه وولي أمره والقائمين على تعليمه كما تنص لائحة تقويم الطالب 2025، فلا تُنشر علناً.","في الصف: في فصل من 30 طالبة أتقنت 12 معيار «حساب المساحة» (40%) ← يُعاد تدريسه للصف كله ← وأتقنت 27 معيار «المحيط» (90%) ← فتكفي خطة علاجية للثلاث الباقيات في مجموعة صغيرة."]},{"pts":["آخر خطوة في التقويم توظيف نتائجه: تغذية راجعة للطالب، وخطط علاجية وإثرائية، وتقرير لولي الأمر، وتعديل للتدريس نفسه؛ فالحكم الذي لا يتبعه قرار وعلاج تقييم لا تقويم.","[[**التغذية الراجعة**|ar.l12.feedback]] **فورية** (في الحصة التالية للاختبار على الأكثر)، محددة ووصفية، على المهمة لا الشخص، تذكر نقاط القوة ثم ما يُحسَّن؛ وتأخيرها أسبوعاً أو الاكتفاء بثناء عام يضعف أثرها.","بعد تحليل النتائج يُبنى **برنامج علاجي** لمن أخفق في مهارة محددة، و**برنامج إثرائي** للمتفوقين الذين أتقنوا الأهداف.","تقرير ولي الأمر واضح محدد يبين مستوى الطالب وتقدمه وحاجاته بلا مقارنة بالآخرين، والنتائج لا تُستخدم أداة عقاب؛ وتحليلها بالجداول الإلكترونية يكشف الفقرات الضعيفة لتحسين الاختبارات القادمة.","في الصف: تدنت نتائج الصف كله في اختبار ← الخطوة الأولى **تحليل النتائج** (الفقرات والمعايير) ثم تعديل التدريس ← لا إعادة الاختبار بأسئلة أسهل ولا لوم الطلاب."]}],"L11":[{"pts":["مفاهيم التدريس تتدرج من الأعم إلى الأخص: [[المدخل|ar.l11.terms]] فلسفة تحدد لماذا نعلّم بهذه الصورة، ثم الاستراتيجية خطة شاملة مرنة، ثم الطريقة إجراءات يشترك فيها المعلمون، ثم الأسلوب بصمة المعلم الشخصية في تنفيذها.","في الصف: معلمان يطبقان طريقة المناقشة نفسها ويختلفان في طرح الأسئلة وإدارة الحوار، فالمختلف أسلوبهما لا طريقتهما؛ والسبورة الذكية أو المقطع المرئي تقنية تخدم الطريقة وليست طريقة.","نموذج التدريس تصور نظري لخطواته تُشتق منه الاستراتيجيات، وصنّف **جويس وويل** النماذج في [[أربع عائلات|ar.l11.other]]: معالجة المعلومات، والاجتماعية، والشخصية، والسلوكية؛ وهي تقابل المداخل الأربعة في القسم التالي: المعرفي، والاجتماعي، والإنساني، والسلوكي.","**المدخل المنطقي** يرتب المحتوى من البسيط إلى المعقد ومن المحسوس إلى المجرد، و**المدخل السيكولوجي** يرتبه وفق ميول المتعلم وحاجاته؛ والمدخل التكاملي يربط المادة بغيرها، كربط درس النسبة في الرياضيات بالزكاة في الفقه.","معيار اختيار الطريقة مناسبتها **لأهداف الدرس وخصائص الطلاب**، لا شيوعها بين الزملاء؛ وأدوار المعلم: مرشد يوجه إلى المصادر، و**ميسّر** يهيئ الظروف ويدعم عند الحاجة، ومفوّض يسلّم الطلاب المسؤولية ويتابع، وتقليدي ملقّن.","في الصف: في مراكز تعلم تمر عليها المجموعات بالتناوب لتقرأ وتستمع وتشاهد، الدور الأنسب للمعلم الميسّر الذي يقدم الدعم عند الحاجة، لا المحاضر الذي يعيد نفسه إلى مركز الدرس ولا المراقب الذي يكتفي بالحكم."],"map":{"type":"nest","title":["Approach ⊃ Strategy ⊃ Method ⊃ Style","من الأعم إلى الأخص: كل مستوى داخل الذي قبله"],"axis":["فلسفة","تنفيذ داخل الصف"],"groups":[{"n":"المدخل","tag":"فلسفة","ar":"تصور عن طبيعة التعلم يوجّه كل ما تحته","d":"ar.l11.terms"},{"n":"الاستراتيجية","tag":"خطة شاملة","ar":"خطة تنظم الطرق والأنشطة لتحقيق الأهداف","d":"ar.l11.terms"},{"n":"الطريقة","tag":"إجراءات","ar":"خطوات منظمة يتبعها المعلم في الدرس","d":"ar.l11.terms"},{"n":"الأسلوب","tag":"بصمة المعلم","ar":"طريقته الشخصية في تنفيذ **الطريقة نفسها**","d":"ar.l11.terms","trap":"الأعم المدخل والأخص الأسلوب، والتقنية (كالسبورة الذكية) أداة تخدم الطريقة لا مستوى في السلسلة؛ ومعلمان بالطريقة نفسها قد يختلف أسلوباهما"}]}},{"pts":["مؤشر 7.1 يطلب أن يحدد المعلم **الأسس النظرية** لأربعة مداخل عامة للتدريس: السلوكي، والمعرفي، والإنساني (الشخصي)، والاجتماعي؛ ومعرفتها تساعده على اختيار ما يحفز طلابه ويعدل سلوكهم، وكل طريقة في الأقسام التالية تحت مدخلها.","**المدخل السلوكي** (سكنر) يعدّل السلوك الظاهر بتحليل المهمة إلى خطوات صغيرة متتابعة مع تعزيز فوري، ومن نماذجه التعليم المباشر والتعليم المبرمج والتعلم للإتقان.","**المدخل المعرفي** (بياجيه وبرونر وأوزوبل) يمكّن الطالب من التفكير والبحث والاكتشاف ذاتياً حتى يصل إلى المعرفة بجهده، ومن نماذجه الاكتشاف والاستقصاء واكتساب المفاهيم والمنظم المتقدم.","**المدخل الإنساني** (روجرز وماسلو) يعنى بالجوانب الوجدانية والوعي بالذات والاستقلالية والمسؤولية، ونموذجه التدريس غير الموجه؛ و**المدخل الاجتماعي** (باندورا) يوظف التفاعل و**نمذجة السلوك**: يؤدي المعلم أو زميل السلوك المرغوب ليحاكيه الطلاب.","في الصف: «خطوات صغيرة وتعزيز فوري» سلوكي، و«ظاهرة محيرة يجمع الطلاب بياناتها حتى يفسروها بأنفسهم» معرفي، و«يشارك الطالب في تحديد أهدافه ويقوّم تقدمه بنفسه» إنساني، و«يُجلس الطالب بجوار زميل متقن ليحاكيه» اجتماعي."],"map":{"type":"fan","title":["Four Teaching Approaches","المداخل الأربعة للتدريس"],"groups":[{"n":"السلوكي","who":"Skinner سكنر","ar":"**التغيير والتعديل في السلوك** الظاهر و**استجابة المتعلمين للمهام** والتعزيز"},{"n":"المعرفي","who":"Piaget · Bruner · Ausubel","ar":"**التفكير والبحث والاكتشاف ذاتياً** والوصول إلى المعرفة بجهده"},{"n":"الإنساني (الشخصي)","who":"Rogers روجرز · Maslow","ar":"الوعي بالذات والاستقلالية والمسؤولية؛ المعلم **ميسّر**"},{"n":"الاجتماعي","who":"Bandura باندورا · Vygotsky","ar":"التفاعل و**نمذجة السلوك** لدعم **النظم التفاعلية** وثقافة صفية إيجابية"}]}},{"pts":["في طرق العرض المباشر يكون المعلم مصدر الخبرة والتعلم **استقبالي**، وأقرب نماذجها التعليم المباشر، وهو نموذج سلوكي يشرح فيه المعلم ويعرض ثم يطبق الطلاب بتغذية راجعة فورية؛ أما الاستقراء فيعده جويس وويل من نماذج معالجة المعلومات.","**الاستقراء** يسير من الأمثلة إلى القاعدة، ويناسب بناء المفاهيم والتعميمات ويبقى أثره أطول لكنه أبطأ؛ و**الاستنباط (القياس)** يسير من القاعدة إلى الأمثلة، وهو أسرع للتطبيق لكن القاعدة قد تُنسى.","في الصف: معلم يكتب «كتبَ الطالبُ، حضرَ المعلمُ» ويسأل عن حركة آخر الفاعل حتى يستنتج الطلاب أنه مرفوع، فهذا استقراء رغم كلمة «يستنتج»؛ وخطوات **هربارت** الخمس: تمهيد فعرض فربط فاستنتاج فتطبيق، تبدأ استقراءً وتُختم بتطبيق القاعدة، فتسميها أغلب المراجع **الطريقة الاستقرائية** وبعضها **الاستدلالية (الهربارتية)**.","[[**المحاضرة**|ar.l11.lecture]] اقتصادية تناسب الأعداد الكبيرة والمحتوى الكثيف لكن المتعلم فيها متلقٍّ سلبي؛ و**المناقشة** أبرز عيوبها سيطرة بعض الطلاب، و**الحوار السقراطي** أسئلة متتابعة تكشف التناقض حتى يصل الطالب إلى الصواب بنفسه.","[[**العرض العملي**|ar.l11.demo]] للمهارات الأدائية كالوضوء والتجارب، و**القصة** للمرحلة الابتدائية ومواد التاريخ والتربية الإسلامية؛ وفي الندوة يعرض متخصصون جوانب موضوع واحد، وفي المناظرة مجموعة مؤيدة وأخرى معارضة يحكم بينهما محكّمون.","في الصف: معلم تاريخ يقدم مادته قصةً تصف شخصيات تاريخية ملهمة بأوصاف حية، فأرجح نتيجة أن يرتبط المحتوى بحياة الطلاب فيسهل عليهم تذكر الحقائق؛ أما تنمية التفكير الإبداعي فلا تتحقق بالضرورة بمجرد الاستماع."],"map":{"type":"grid","title":["Induction vs deduction","الاستقراء مقابل الاستنباط"],"cols":[{"n":"الاستقراء","c":"#1F6B4C"},{"n":"الاستنباط (القياس)","c":"#33449A"}],"rows":[{"n":"الاتجاه","cells":[{"n":"أمثلة ← قاعدة","c":"#1F6B4C"},{"n":"قاعدة ← أمثلة","c":"#33449A"}]},{"n":"يناسب","cells":[{"n":"بناء المفاهيم والتعميمات","c":"#1F6B4C"},{"n":"التدريب على تطبيق القاعدة","c":"#33449A"}]},{"n":"السرعة والبقاء","cells":[{"n":"أبطأ، وأثره أطول","c":"#1F6B4C"},{"n":"أسرع، وقد تُنسى القاعدة","c":"#33449A"}]}],"trap":"«يستنتج القاعدة من الأمثلة» = استقراء، لا استنباط"}},{"pts":["طرق التعلم الفردي تتيح لكل طالب أن يتعلم بسرعته وقدرته: تبدأ من المدخل السلوكي بالتعليم المبرمج، وتمتد إلى التعلم الذاتي وعقود التعلم التي تحمّل المتعلم مسؤولية تعلمه، وهي من نماذج المدخل الإنساني.","**التعليم المبرمج** (سكنر) تطبيق **سلوكي** للإشراط الإجرائي: خطوات صغيرة، واستجابة نشطة، وتعزيز فوري، وخطو ذاتي؛ و**البرمجة الخطية** (سكنر) مسار واحد للجميع، و**المتشعبة** (كراودر) تحوّل المخطئ إلى إطار علاجي ثم تعيده.","في الصف: برنامج محوسب يحوّل الطالب عند الخطأ إلى إطار يشرح خطأه ثم يعيده إلى المسار برمجة متشعبة؛ وعيب التعليم المبرمج أنه **لا ينمي التفاعل الاجتماعي** ولا يناسب الأهداف الوجدانية والإبداع.","[[**التعلم الذاتي**|ar.l11.self]] يتحمل فيه المتعلم مسؤولية تعلمه برغبته دون تدخل مباشر من المعلم، الذي يصمم المصادر ويوجّه؛ ومن وسائله الحقيبة التعليمية (أهداف واختبار قبلي وأنشطة بدائل واختبار بعدي) والموديول، وهو وحدة صغيرة مستقلة من برنامج أكبر.","**الفردي** أن يؤدي كل طالب المهام نفسها منفرداً، و**التفريدي** أن تختلف المهام بحسب ميوله؛ و**عقد التعلم** اتفاق مكتوب يتعهد فيه الطالب بمهام محددة وفق معايير مقابل تقدير."]},{"pts":["في هذه الطرق يبني الطالب المعرفة بنفسه: الاكتشاف والاستقصاء من نماذج المدخل المعرفي، ويلتقي معهما حل المشكلات والمشروعات في التعلم بالعمل؛ وأكثر الطرق تطلباً **لفعالية المتعلم** الاكتشاف والمشروعات، وأقلها المحاضرة.","[[**الاكتشاف**|ar.l11.discovery]] (برونر) يصل فيه الطالب إلى المفهوم بنفسه، وغايته أن يتعلم كيف يصل إلى المعلومة لا أن يتلقاها؛ وهو موجّه يحدد فيه المعلم المشكلة والأدوات، وشبه موجّه، وحر يحدد فيه الطالب المشكلة والأدوات.","**الاستقصاء** أوسع من الاكتشاف: يولّد الطالب المعرفة بالأسئلة والبحث كالباحث، وعملياته الملاحظة والتصنيف والقياس والتنبؤ؛ ولذلك يدرّب المعلم طلابه على الملاحظة وتنظيم البيانات لدعم التعلم بالاستقصاء.","[[**حل المشكلات**|ar.l11.problem]] (ديوي) يبدأ **بالشعور بالمشكلة** ثم تحديدها، ثم وضع الفروض، ثم استنتاج ما يترتب على كل فرض، ثم **اختبارها** بالملاحظة والتجربة لقبولها أو رفضها؛ وتختصرها الأسئلة غالباً: الشعور، فالتحديد، فالفروض، فاختبارها، فالنتيجة؛ وهي خطوات التفكير العلمي نفسها.","في الصف: طلاب لاحظوا ذبول نباتات الحديقة وتساءلوا عن السبب قبل تحديد المشكلة بدقة، فهم في الشعور بالمشكلة؛ ثم اقترحوا قلة الماء أو نقص الضوء أو مرض التربة، وهذا اقتراح فروض لا اختبارها.","[[**المشروعات**|ar.l11.project]] (كلباترك تلميذ ديوي): اختيار الهدف ثم تخطيط ثم تنفيذ ثم تقويم، وتضيف كتب عربية كتابة التقرير، وتنتهي غالباً بمنتج؛ فالاكتشاف ينتهي إلى **مفهوم** والمشروع إلى منتج، وفي **دراسة الحالة** يحلل الطلاب موقفاً واقعياً ويقررون علاجه.","**التدريب الاستقصائي** لسوشمان يعرض حدثاً متناقضاً يثير الحيرة، فيجمع الطلاب البيانات ويختبرون فروضهم بأسئلة جوابها **نعم أو لا**، ثم يصوغون تفسيراً، ثم يحللون طريقة استقصائهم."]},{"pts":["مؤشر 7.2 يطلب اختيار الطريقة التي تتوافق مع متطلبات المنهج وخصائص نمو المتعلمين، ومثاله طريقتان من اتجاهين: العرض العملي من الطرق **المباشرة**، والتغيير المفاهيمي من طرق التدريس **البنائي**.","العرض العملي أداء للمهارة مع **شرح متزامن**، وهو الأنسب للتجارب الخطرة أو المكلفة أو قليلة الأدوات؛ يجربه المعلم مسبقاً ويوضح هدفه ويرتب المكان ليراه الجميع، ثم يؤدي خطوة خطوة مع قواعد السلامة، ثم يطبق الطلاب.","في الصف: تجربة فيها مادة قابلة للاشتعال وأدواتها نسخة واحدة يعرضها المعلم بنفسه مع التأكيد على السلامة، ولا يوزعها على مجموعات في الوقت نفسه ولا يكلف الطلاب بتنفيذها في المنزل.","**التصورات البديلة** أفكار كوّنها الطالب من خبرته اليومية تخالف العلم، وهي **مقاومة للتغيير** لأنها تبدو له منطقية؛ وإعادة شرح الصواب **دون إحداث عدم الرضا** لا تغير التصور غالباً.","[[**التغيير المفاهيمي**|ar.l11.conceptual]] (بوسنر) يحدث بأربعة شروط مرتبة: **عدم الرضا** عن التصور الحالي، ثم أن يكون المفهوم الجديد واضحاً، ثم معقولاً، ثم مثمراً يفسر مواقف جديدة.","في الصف: يتوقع الطلاب أن الكرة الثقيلة تسقط أسرع، فيسقط المعلم كرتين متماثلتين حجماً مختلفتين كتلةً فتصلان معاً تقريباً؛ هذا تناقض معرفي يولّد عدم الرضا قبل تقديم المفهوم العلمي، وهي استراتيجية توقع – لاحظ – فسر."]},{"pts":["الاستراتيجيات الاجتماعية تطبيق للمدخل الاجتماعي يتعلم فيه الطالب بالتفاعل مع زملائه؛ وبيئات التعلم ثلاث: **تنافسية** يرتبط فيها فوز طالب بخسارة آخر، وفردية يعمل فيها كل طالب مستقلاً، وتعاونية ينجح فيها الجميع معاً.","[[**التعلم التعاوني**|ar.l11.coop]] (جونسون وجونسون): مجموعات **غير متجانسة** من 4–6 طلاب، أول عناصره الخمسة الاعتماد الإيجابي المتبادل؛ ومن صوره [[**جيكسو (المجموعات المتداخلة)**|ar.l11.jigsaw]]: مجموعة خبراء ثم عودة لتعليم المجموعة الأم، وفرق التحصيل (STAD) لسلافين ودرجة الفريق فيها من التحسن.","في الصف: مجموعة نالت درجة ممتازة ثم تبيّن أن طالباً واحداً أنجز العمل كله؛ العنصر المفقود المسؤولية الفردية، ويضمنها المعلم بتوزيع الأدوار والاختبار الفردي وتقويم كل عضو لإسهام زملائه.","[[**العصف الذهني**|ar.l11.social]] (أوزبورن) قواعده إرجاء النقد، وحرية التفكير، و**الكم قبل الكيف**، والبناء على أفكار الآخرين؛ فإذا تباطأت الأفكار سأل المعلم «هل هناك فكرة أخرى؟» لا «هل هناك فكرة أفضل؟» لأنها حكم.","**التدريس التبادلي** (بالينسكار وبراون) حوار حول نص مقروء بالتنبؤ وتوليد الأسئلة والتوضيح والتلخيص، يتبادل فيه الطلاب دور المعلم؛ و**تدريس الأقران** طالب يعلّم طالباً فيستفيد الاثنان، و**لعب الأدوار** لا يُقاطع فيه المشهد وتُناقش السلوكيات بعده.","**التدريس المصغر** تدريب للمعلم لا طريقة لتدريس الطلاب: مهارة تدريسية واحدة مع عدد قليل من الطلاب (1–10) في 5–10 دقائق، وتصل في بعض المراجع إلى 20، ثم تسجيل وتغذية راجعة وإعادة؛ فهو الأنسب لمعلم جديد يريد التدرب على طرح الأسئلة وحدها."],"map":{"type":"flow","title":["Jigsaw — Aronson","جيكسو (أرونسون)"],"note":"**جيكسو** (أرونسون): لا يكتمل الدرس إلا بكل الأجزاء، فيقوى **الاعتماد المتبادل**.","groups":[{"n":"المجموعة الأم","short":"الأم","idea":"كل عضو يأخذ جزءاً من الدرس","items":[{"n":"جيكسو","d":"ar.l11.jigsaw"}]},{"n":"مجموعة الخبراء","short":"الخبراء","idea":"أصحاب الجزء نفسه يتعمقون فيه معاً"},{"n":"العودة للأم","short":"العودة","idea":"كل خبير يعلّم جزءه لمجموعته","trap":"الخبراء مرحلة وسطى، والتعليم يتم في الأم"}]}},{"pts":["الوسائل والتقنيات أدوات تخدم أي طريقة وليست طرقاً: **الوسائل التعليمية** أجهزة وأدوات ومواد تُكسب خبرات محددة، و**تقنيات التعليم** أشمل لأنها منظومة من الإنسان والآلة والطريقة.","رتّب [[**إدجار ديل**|ar.l11.dale]] الخبرات من الأكثر حسية في **القاعدة** إلى الأكثر تجريداً في القمة: المباشرة الهادفة، ثم المعدلة، ثم الممثلة، ثم المشاهدة، ثم الرموز البصرية، ثم الرموز اللفظية في القمة.","المجسم خبرة **معدلة** لا مباشرة، و**المحاكاة** بديل آمن للتجارب الخطرة أو المكلفة؛ والأصغر سناً يحتاج قاعدة المخروط أكثر من غيره.","في الصف: زراعة الطالبات بذوراً ومتابعة نموها خبرة مباشرة هادفة، ومجسم جسم الإنسان خبرة معدلة، والخريطة رمز بصري، وشرح المعلم بالكلام وحده رمز لفظي في قمة التجريد."],"map":{"type":"pyramid","title":["Edgar Dale — Cone of Experience","مخروط الخبرة (إدجار ديل): القاعدة محسوسة والقمة مجردة"],"brackets":[{"from":0,"to":2,"n":"العمل"},{"from":3,"to":3,"n":"الملاحظة"},{"from":4,"to":5,"n":"الرموز"}],"groups":[{"n":"المباشرة الهادفة","d":"ar.l11.dale","tag":"يعمل الطالب بنفسه: زراعة، تجربة حقيقية","hl":true},{"n":"المعدلة","d":"ar.l11.dale","tag":"النماذج والمجسمات والعينات","trap":"المجسم معدلة لا مباشرة"},{"n":"الممثلة","d":"ar.l11.dale","tag":"الدراما ولعب الأدوار"},{"n":"المشاهدة","d":"ar.l11.dale","tag":"توضيحات عملية، رحلات، معارض، تلفاز وأفلام، صور وتسجيلات"},{"n":"الرموز البصرية","d":"ar.l11.dale","tag":"الخرائط والرسوم"},{"n":"الرموز اللفظية","d":"ar.l11.dale","tag":"الكلمات: الأكثر تجريداً","trap":"القمة اللفظية لا البصرية"}],"note":"الأصغر سناً يحتاج **القاعدة** أكثر؛ و**المحاكاة** بديل للتجارب الخطرة أو المكلفة."}}],"L12":[{"pts":["الأهداف ثلاثة مستويات تنزل من العام إلى الدقيق: [[**الغايات**|ar.l12.levels]] بعيدة المدى تعبر عن فلسفة المجتمع، ثم الأهداف العامة لمرحلة أو مقرر (متوسطة المدى)، ثم الأهداف **الخاصة السلوكية** لدرس واحد (قريبة المدى).","[[**الهدف السلوكي**|ar.l12.behav]] عند ماجر ثلاثة مكونات: **سلوك** قابل للقياس، و**شرط** الأداء، و**معيار** الإتقان؛ ويُصاغ بالعربية عادة: أن + فعل سلوكي + الطالب + المحتوى + الشرط + المعيار، ويلتقي مع صفات [[SMART|ar.l12.smart]].","الهدف الجيد يصف سلوك **المتعلم** لا المعلم، وناتجاً واحداً لا نشاطاً، بفعل قابل للملاحظة والقياس؛ ولهذا تُرفض صيغ مثل «يوضح المعلم» و«يفهم» و«يقرأ الدرس».","في الصف: «أن يحل الطالب 8 مسائل من 10 دون آلة حاسبة»؛ فعبارة «8 من 10» **معيار** الإتقان، و«دون آلة حاسبة» **شرط** الأداء، والخلط بينهما فخ متكرر."]},{"pts":["يصنف بلوم أهداف المجال المعرفي في ستة مستويات متدرجة، والمطلوب في الاختبار أن تعرف مستوى أي هدف أو سؤال من فعله.","**صيغة المستويات**: أسماء في **بلوم** (1956)، وأفعال في [[المعدل|ar.l12.revised]] (أندرسون وكراثوول 2001) الذي جعل الإبداع في القمة وأضاف **بعد المعرفة**: حقائقية، مفاهيمية، إجرائية، ما وراء معرفية.","صنّف الهدف بفعله عبر [[قائمة الأفعال|ar.l12.verbs]]: يفكك **تحليل**، ويحكم وينقد ويبرر تقويم، ويصمم ويقترح التركيب أو الإبداع؛ أما «يقارن» و«يميز» و«يعلل» فحسب السياق: وصف الحقائق أو شرح سببها فهم، وتفكيك العلاقات تحليل.","المستويات الدنيا تذكر وفهم وتطبيق، والعليا تحليل وتقويم وإبداع، والعليا هي ما تستهدفه **أسئلة التفكير**.","في الصف: «أن ينقد الطالب حجة الكاتب ويبرر رأيه» هدف في مستوى التقويم، و«أن يصمم تجربة تختبر فرضية» في مستوى الإبداع (التركيب في الأصلي)."],"map":{"type":"steps","title":["Bloom (1956) → Anderson & Krathwohl (2001)","تصنيف بلوم: الأصلي والمعدل"],"swap":{"a":4,"b":5,"label":["تبادلا القمة في 2001"]},"brackets":[{"from":0,"to":2,"n":"مهارات دنيا"},{"from":3,"to":5,"n":"مهارات عليا"}],"groups":[{"n":"التذكر","d":"ar.l12.revised","items":[{"n":"يعدد","d":"ar.l12.verbs"},{"n":"يسمي"}],"tag":"1956: المعرفة"},{"n":"الفهم","d":"ar.l12.revised","items":[{"n":"يشرح","d":"ar.l12.verbs"},{"n":"يلخص"}],"tag":"1956: الفهم"},{"n":"التطبيق","d":"ar.l12.revised","items":[{"n":"يحل","d":"ar.l12.verbs"},{"n":"يستخدم"}],"tag":"1956: التطبيق"},{"n":"التحليل","d":"ar.l12.revised","items":[{"n":"يفكك","d":"ar.l12.verbs"},{"n":"يحلل العلاقات"}],"tag":"1956: التحليل","trap":"«يقارن» و«يميز» حسب السياق: وصف = فهم، تفكيك = تحليل"},{"n":"التقويم","d":"ar.l12.revised","items":[{"n":"يحكم","d":"ar.l12.verbs"},{"n":"ينقد"}],"tag":"1956: التقويم **كان القمة**","hl":true},{"n":"الإبداع","d":"ar.l12.revised","items":[{"n":"يصمم","d":"ar.l12.verbs"},{"n":"يقترح"}],"tag":"1956: التركيب **كان الخامس**","hl":true}]}},{"pts":["إلى جانب المعرفي مجالان: الوجداني للقيم والاتجاهات، والنفس‑حركي للمهارات الحركية، ولكل مجال تصنيفه ومستوياته.","«أن يحب وطنه» و«أن يقدّر جهود العلماء» أهداف **وجدانية**، لأنها تصف قيمة أو اتجاهاً لا معلومة أو مهارة.","في دليل الهيئة: المستويات **الدنيا** للوجداني «الاستقبال، الاستجابة، **التقمص**»، و**العليا** «**التقدير**، التنظيم، **التجسيد**»؛ أما **التركيب** فمستوى معرفي لا وجداني.","**النفس‑حركي** عند [[سمبسون|ar.l12.simpson]] سبعة مستويات: الإدراك الحسي، الاستعداد، الاستجابة الموجهة، الآلية، المعقدة، التكيف، الإبداع.","وفي تصنيفات حركية أخرى: **ديف** وأعلى مستوياته التطبيع (الأداء التلقائي)، و**هارو** الذي يبدأ بالحركات الانعكاسية؛ ويقسم دليل الهيئة المهاري إلى **دنيا** «الملاحظة، التقليد، التجريب» و**عليا** «الممارسة، الإتقان، الإبداع»."],"map":{"type":"steps","head":true,"title":["Affective Domain — Krathwohl","المجال الوجداني عند كراثوول: من الانتباه للقيمة إلى أن تصير سمة"],"groups":[{"n":"الاستقبال","d":"ar.l12.krath","tag":"الانتباه والإصغاء"},{"n":"الاستجابة","d":"ar.l12.krath","tag":"المشاركة برضا والتطوع"},{"n":"التقييم","d":"ar.l12.krath","tag":"تقدير القيمة وتبنيها · في دليل الهيئة: «التقدير»"},{"n":"التنظيم","d":"ar.l12.krath","tag":"ترتيب القيم في منظومة عند تعارضها"},{"n":"التميز بالقيمة","ar":"في دليل الهيئة: «التجسيد»","d":"ar.l12.krath","tag":"القيمة جزء ثابت من الشخصية","hl":true}]}},{"pts":["التخطيط الجيد يبدأ من المنهج: مؤشر 8.1 يطلب أنشطة بتسلسل منطقي تربط **أهداف التعلم بمعايير المنهج**.","[[**معايير المحتوى**|ar.l12.align]] تصف ما ينبغي تعلمه في كل مجال، و**معايير الأداء** تصف نواتج التعلم المتوقعة نهاية كل صف.","التسلسل الصحيح: المعيار ثم ناتج التعلم ثم أهداف الدرس ثم الأنشطة ثم أدوات تقويم تجمع **دليلاً** على التعلم.","**التصميم العكسي** (ويغنز وماكتاي) يبدأ من النهاية: النتائج المرغوبة أولاً، ثم أدلة التقويم، ثم خبرات التعلم.","**المحاذاة** أن يكون الهدف والنشاط والتقويم بالمستوى نفسه؛ فهدف «يقارن» لا يُقوَّم بسؤال «اذكر»."]},{"pts":["[[**التخطيط**|ar.l12.plan]] نوعان: طويل المدى (الخطة السنوية والفصلية)، وقصير المدى (خطة الوحدة والخطة اليومية).","يبدأ المعلم درسه بالتحقق من **المتطلبات السابقة**، وتوزيع المقرر السنوي ليس من عناصر الخطة اليومية.","**التهيئة** أكثر عنصر يُغفل، وأنواعها أربعة: حافزة تثير الاهتمام، وتوجيهية توجّه الانتباه لموضوع الدرس، وانتقالية تربط السابق بالجديد، وتقويمية تتأكد من فهم السابق؛ ويقابلها الغلق في الختام.","في الصف: «تعلمنا أمس أن للهواء وزناً، واليوم نرى كيف يدفع الأجسام» تهيئة انتقالية، و«لماذا لم ينسكب الماء من الكوب المقلوب؟» تهيئة حافزة.","أحداث [[جانييه|ar.l12.gagne]] التسعة تبدأ بجذب الانتباه وتنتهي بتعزيز الاحتفاظ والانتقال؛ وعند ضيق الوقت تُرتب الأنشطة **حسب أولويتها للأهداف** ولا تُحوَّل كلها واجبات."],"map":{"type":"flow","title":["Daily Lesson Plan","عناصر خطة الدرس اليومية"],"note":"**الزمن**: لكل خطوة وقتها، وهو أساس **إدارة وقت الحصة**.","groups":[{"n":"قبل الدرس","idea":"ماذا سيتعلم الطالب؟","items":[{"n":"الموضوع"},{"n":"الأهداف"},{"n":"المتطلبات السابقة"}]},{"n":"البداية","idea":"تثير الانتباه وتربط بالسابق","items":[{"n":"التهيئة"}]},{"n":"العرض","idea":"كيف سيتعلم؟","items":[{"n":"المحتوى والإجراءات"},{"n":"الاستراتيجيات"},{"n":"الوسائل"},{"n":"الأنشطة"}]},{"n":"الختام","idea":"هل تحقق الهدف؟","items":[{"n":"التقويم"},{"n":"الغلق"},{"n":"الواجب"}]}]}},{"pts":["تكمل الخطة أربع أدوات: تحليل المحتوى يحدد ماذا ندرّس، وجدول المواصفات كيف نقيسه، والتغذية الراجعة والواجبات كيف نتابع التعلم.","[[**تحليل المحتوى**|ar.l12.content]] يفكك المادة إلى حقائق ومفاهيم وتعميمات ومهارات وقيم واتجاهات، ويأتي بعد الأهداف وقبل الأنشطة.","[[**جدول المواصفات**|ar.l15.tos]] يقاطع الموضوعات (المحتوى) مع مستويات الأهداف ليحقق صدق المحتوى؛ ووزن الموضوع = حصصه (أو صفحاته أو أهدافه) ÷ المجموع × 100.","[[**التغذية الراجعة**|ar.l12.feedback]] الجيدة فورية، محددة ووصفية، على المهمة لا الشخص؛ فكلمة «أحسنت» وحدها لا تكفي، وأقوى صورها **تعليق محدد** يبين ما أُحسن وما يُحسَّن، والمؤجلة أقل أثراً.","إن جاءت البدائل: «تعليق فقط» و«تقدير وتعليق» و«درجة وتعليق»، فالأرجح علمياً «تعليق فقط»؛ فقد بيّنت دراسة **بتلر** (1988) أن إضافة الدرجة إلى التعليق تلغي أثره.","**الواجبات المنزلية** مرتبطة بالدرس ومناسبة الكم، تُصحح وتُعاد بتغذية راجعة، ولا تُستخدم عقاباً."]},{"pts":["مؤشر 8.1 يطلب أن تضم الخطة [[**مصادر رقمية وغير رقمية**|ar.l12.resources]] تحقق شروط الاختيار.","أول الشروط **الارتباط بالهدف**، ثم المناسبة للمتعلمين، والدقة، والأمان، والإتاحة للجميع، واحترام الملكية الفكرية.","المصدر **وسيلة لا غاية**: يجربه المعلم قبل الحصة ويعد بديلاً، والأحدث أو الأغلى ليس الأفضل بالضرورة.","**مصادر البيئة المحلية** (زيارة، عينات حقيقية، خبير من المجتمع) فاعلة وقليلة التكلفة.","نموذج **آشور** (هاينك وزملاؤه) لتوظيف الوسائط ست خطوات: **تحليل خصائص المتعلمين**، فصياغة الأهداف، فاختيار الطرق والوسائط، فاستخدامها، فإشراك المتعلمين، فالتقويم والمراجعة."]}],"L13":[{"pts":["مؤشر 8.3 يطلب استراتيجيات تلبي **حاجات المتعلمين وخصائصهم** وتراعي طبيعة الأهداف، وتنويعها يخفض كره الطلاب للمادة؛ و**التعلم النشط** تطبيق للنظرية **البنائية**: الطالب يبني معرفته بالعمل، والمعلم ميسّر لا ملقّن.","**فكر‑زاوج‑شارك** (ليمان) يبدأ فردياً ثم ثنائياً ثم جماعياً، وجدول **KWL** (أوجل): ماذا أعرف؟ ماذا أريد أن أعرف؟ ماذا تعلمت؟ ينشط المعرفة السابقة وينمي ما وراء المعرفة لا الإبداع.","في الصف: قبل قراءة درس الزواحف ناقش المعلم طلابه ووضعوا قائمة أسئلة يودون معرفة إجاباتها؛ هذه المناقشة القبلية تضع غرضاً واضحاً للقراءة وتنشط المعرفة السابقة، لا تقدم مصطلحات جديدة ولا تدرب على التحليل.","[[**الصف المقلوب**|ar.l13.flipped]]: الشرح في **المنزل** والتطبيق والمناقشة في الفصل؛ و[[**دورة التعلم 5E**|ar.l13.5e]] (بايبي): الانشغال، ثم الاستكشاف قبل الشرح، ثم التفسير، ثم التوسع بتطبيق المفهوم في موقف جديد، ثم التقويم.","[[**التعلم القائم على المشكلات**|ar.l13.pbl]] يبدأ بمشكلة غير محددة البنية بلا حل واحد، والقائم على المشروعات ينتهي بمنتج؛ و**التعلم للإتقان** (بلوم وكارول) لا انتقال فيه قبل إتقان 80–90%، وقاعدته: **الزمن متغير والتحصيل ثابت**.","ومن [[الاستراتيجيات التفاعلية|ar.l13.active]] **مراكز التعلم** بالتناوب والرؤوس المرقمة وحوض السمك، ومن [[النماذج البنائية|ar.l13.models]] التغير المفاهيمي ([[بوسنر|ar.l11.conceptual]]) الذي يعالج التصورات البديلة.","أبعاد التعلم عند **مارزانو** خمسة: الاتجاهات الإيجابية، واكتساب المعرفة وتكاملها، و**تعميق المعرفة وصقلها** (المقارنة والتصنيف)، والاستخدام ذو المعنى (حل المشكلات واتخاذ القرار)، وعادات العقل المنتجة.","استراتيجية **روبنسون** (SQ3R) لفهم المقروء خمس خطوات: المسح، فتحويل العناوين إلى أسئلة، فالقراءة بحثاً عن الإجابة، فالتسميع بأسلوب الطالب، فالمراجعة."],"map":{"type":"flow","title":["5E learning cycle — Bybee","دورة التعلم الخماسية (بايبي)"],"back":[[4,0]],"loop":["دورة تتكرر، والتقويم في كل مرحلة"],"note":"**دورة التعلم الخماسية** (بايبي): يجرّب الطلاب **قبل** أن يُشرح لهم.","groups":[{"n":"الانشغال","idea":"إثارة الاهتمام وكشف المعرفة السابقة","items":[{"n":"Engage","d":"ar.l13.5e"}],"trap":"تبدأ بالانشغال، والثلاثية لكاربلس بالاستكشاف"},{"n":"الاستكشاف","idea":"نشاط عملي **قبل** الشرح","items":[{"n":"Explore"}]},{"n":"التفسير","idea":"الطلاب يفسرون والمعلم يقدم المصطلح","items":[{"n":"Explain"}]},{"n":"التوسع","idea":"تطبيق المفهوم في موقف جديد","items":[{"n":"Elaborate"}],"trap":"التطبيق في موقف جديد = التوسع"},{"n":"التقويم","idea":"في كل مرحلة وفي النهاية","items":[{"n":"Evaluate"}]}]}},{"pts":["[[**التعليم المتمايز**|ar.l13.diff]] (توملينسون) استجابة مخططة لاختلاف الطلاب: يكيّف المعلم المحتوى والعملية والمنتج والبيئة وفق الاستعداد والاهتمام ونمط التعلم، والهدف ومعايير النجاح واحدة للجميع.","معادلته: المثير نفسه (هدف واحد) مع **مهام متنوعة** تؤدي إلى **نفس المخرجات**؛ أما التعليم التقليدي الذي يراعي الفروق فمهمة واحدة للجميع يقبل فيها المعلم مخرجات مختلفة، والتمايز لا يعني خفض الهدف للضعفاء.","في الصف: درس الكسور المتكافئة بقطع ملموسة لمجموعة وبرسوم لأخرى وبمسائل حياتية لثالثة تمايز في العملية؛ وإتاحة إظهار التعلم بمقال أو عرض تقديمي أو فيلم قصير تمايز في المنتج.","[[**خريطة المفاهيم**|ar.l13.maps]] (نوفاك) هرمية العام في قمتها وبين مفاهيمها كلمات ربط، وأساسها نظرية **أوزوبل**؛ والخريطة الذهنية (بوزان) شعاعية حول فكرة مركزية، وأشكال فن دائرتان متقاطعتان للمقارنة.","الأسئلة التي تستثير التفكير وتحفز النقاش **مفتوحة** لا تبحث عن إجابة واحدة؛ ويُطرح السؤال **ثم** يُختار المجيب ليبقى الجميع مفكرين، مع [[**زمن الانتظار**|ar.l14.questions]] (رو) 3–5 ثوانٍ قبل التدخل.","**الأسئلة السابرة** تتبع الإجابة: الناقصة بسؤال توضيحي، والخاطئة بسبر مشجع لا تصحيح فوري، وعدم الإجابة بإعادة صياغة؛ وطلب وصف العمليات والصعوبات آخر الدرس ينمي **التأمل** وما وراء المعرفة."]},{"pts":["مؤشر 8.3 يطلب ممارسات **التعليم الشامل** وأسس التدريس المتمايز: تعليم الجميع معاً في الفصل العام، مع تكييف البيئة والمنهج والتدريس والتقويم ليشارك كل طالب.","**الدمج** يُلحق الطالب ذا الاحتياج بالنظام القائم ويطلب منه التكيف، و**الشمول** يغيّر النظام نفسه ليستوعب التنوع ويعدّه أمراً طبيعياً.","**التصميم الشامل للتعلم (UDL)** تخطيط مسبق بثلاث وسائل متعددة: للتمثيل، وللتعبير والأداء، وللمشاركة والتحفيز، يُخطط لها من بداية الدرس لا بعد ظهور المشكلة.","ممارسات شاملة: توقعات عالية للجميع، ومجموعات مرنة، وتقنيات مساعدة، و**تعاون مع معلم التربية الخاصة**؛ والتمايز أداة من أدوات الشمول، والشمول **ليس** خفض الأهداف ولا عزل ذوي الاحتياج.","في الصف: درس يُقدَّم بنص ومقطع مرئي مصحوب بنص مكتوب ومجسم، وتُظهر فيه الطالبات فهمهن برسم أو تسجيل صوتي أو فقرة؛ تخطيط مسبق يناسب ضعيفة السمع والموهوبة معاً، وهو تصميم شامل للتعلم."]},{"pts":["التقنية تُقاس بما تضيفه إلى التعلم لا بحداثتها، وأنماطها: [[**التعليم المدمج**|ar.l13.elearn]] حضوري مع إلكتروني، و**المتزامن** في الوقت نفسه من أماكن مختلفة، وغير المتزامن في أوقات مختلفة كالمقطع المسجل.","مستويات توظيف التعلم الإلكتروني: **مساند** يدعم الصفي دون تغيير بنيته، ثم مدمج، ثم كامل عن بعد؛ وليس من مميزات الحاسب تنمية التفاعل الاجتماعي، لأن التعلم به فردي في الغالب.","[[**نموذج SAMR**|ar.l13.samr]] (بونتيدورا) يقيس عمق أثر التقنية في المهمة: الاستبدال، فالتعزيز، فالتعديل، فإعادة التعريف بمهمة مستحيلة دون تقنية؛ ونموذج **TPACK** (ميشرا وكوهلر) يصف معارف المعلم: التقنية والتربية والمحتوى.","[[منصات الوزارة|ar.l13.platforms]]: **مدرستي** للتعليم الإلكتروني والفصول الافتراضية، ونور للدرجات والغياب، وعين للمحتوى، وروافد للمصادر؛ و[[**مبادئ ماير**|ar.l13.mayer]]: تعليق صوتي مع الرسوم، والنص قرب الصورة، وحذف المشتتات.","في الصف: بحث جماعي عبر الإنترنت في مصادر موثوقة أعدها المعلم مسبقاً هو الرحلات المعرفية (**الويب كويست**)، لا الرحلات الميدانية ولا التعلم المبرمج؛ و**الحوسبة السحابية** تناسب دمج الملفات وتحريرها معاً، والمزيد في [[أدوات الويب والتطبيقات|ar.l13.tools]].","**ADDIE** أشهر نماذج التصميم التعليمي، ويبدأ بالتحليل ثم التصميم ثم التطوير ثم التنفيذ، وينتهي بالتقويم.","مدخل **ستيم** يدمج العلوم والتقنية والهندسة والرياضيات في مشروع واحد يصمم فيه الطلاب حلاً ويجربونه ثم يحسّنونه، كتصميم جسر من أعواد وحساب حمله وتجريبه."],"map":{"type":"steps","head":true,"title":["SAMR — Puentedura","نموذج SAMR (بونتيدورا): عمق أثر التقنية في المهمة"],"brackets":[{"from":0,"to":1,"n":"تحسين"},{"from":2,"to":3,"n":"تحويل"}],"groups":[{"n":"الاستبدال","ar":"S","d":"ar.l13.samr","tag":"بديل مباشر بلا تغيير وظيفي","trap":"الاستبدال لا يغيّر المهمة"},{"n":"التعزيز","ar":"A","d":"ar.l13.samr","tag":"تحسين وظيفي: مدقق إملائي، قص ولصق"},{"n":"التعديل","ar":"M","d":"ar.l13.samr","tag":"إعادة تصميم كبيرة للمهمة"},{"n":"إعادة التعريف","ar":"R","d":"ar.l13.samr","tag":"مهمة مستحيلة دون تقنية","hl":true}]}},{"pts":["**المنهج** بمفهومه الحديث **جميع الخبرات** المخططة داخل المدرسة وخارجها، فهو أعم من المقرر والمقرر أعم من الكتاب؛ وعناصره: الأهداف، ثم المحتوى، ثم طرق التدريس والأنشطة، ثم التقويم.","أسسه: الفلسفي (العقدي) والنفسي والاجتماعي والمعرفي؛ وأنواعه: الرسمي (المعلن) وثيقة معتمدة، و**الخفي** (جاكسون) يُتعلم ضمناً دون تخطيط، و**الفارغ** أو الصفري (آيزنر) ما لا يُدرَّس، عمداً كان أو سهواً.","في الصف: طلاب صاروا يحترمون الوقت لأن معلمهم يحضر قبل الجرس ويعتذر إن تأخر دقيقة، دون أن يرد ذلك في أي درس؛ هذا منهج خفي، ولو حذفت لجنة المناهج موضوعاً عمداً لكان منهجاً فارغاً.","[[تنظيمات المنهج|ar.l13.currorg]]: المواد المنفصلة، والمترابطة (تنسيق مع بقاء المادتين)، والمندمجة، و**المحوري** (محور مشترك حول حاجات الطلاب ومشكلاتهم، ومعه مواد اختيارية)، و**النشاط** (ديوي) القائم على الميول وحل المشكلات، و**الحلزوني** (برونر) الذي يعيد المفاهيم بعمق متزايد.","**نموذج تايلر** (1949) يبدأ بالأهداف في أربعة أسئلة: الأهداف، فالخبرات، فتنظيمها، فتقويمها، وهو صاحب نموذج تقويم المنهج؛ و**نموذج تابا** استقرائي يبدأ من المعلم بتشخيص حاجات الطلاب.","**التنظيم المنطقي** يرتب المحتوى من البسيط إلى المعقد، و**السيكولوجي** وفق حاجات المتعلم وميوله؛ و**المدى والتتابع**: المدى أفقي يصف اتساع المحتوى في الصف الواحد ومنه ربط المواد ببعضها، والتتابع رأسي يصف تدرجه عبر الصفوف."],"map":{"type":"nest","title":["Curriculum ⊃ Course ⊃ Textbook","المنهج أعم من المقرر، والمقرر أعم من الكتاب"],"groups":[{"n":"المنهج","tag":"الحديث","ar":"جميع الخبرات المخططة داخل المدرسة وخارجها"},{"n":"المقرر","tag":"المعلومات","ar":"المادة المقررة؛ وكان هو المنهج في المفهوم **التقليدي**"},{"n":"الكتاب","tag":"جزء","ar":"جزء من المقرر","trap":"الأعم المنهج، ثم المقرر، ثم الكتاب"}]}},{"pts":["**الأبعاد المشتركة** مهارات وقيم لا تملكها مادة بعينها، فتُنمّى عبر **جميع المواد** بالشواهد والمواقف والأنشطة، بصفة **مباشرة أو ضمنية** كما في نص المؤشر؛ ونصها في المعيار الثامن: **أولويات + قيم ست + مهارات**.","الأولويات ثلاث: المواطنة المسؤولة، ومكانة المملكة الريادية، و**التنمية المستدامة** أي تلبية حاجات الحاضر دون الإضرار بقدرة الأجيال القادمة، كترشيد الاستهلاك والحفاظ على الموارد.","والقيم الست: تقوى الله، والوسطية والاعتدال، وتقدير الذات، و**الشغف المعرفي** أي حب الاستطلاع والرغبة الذاتية في المعرفة وينمو بالأسئلة المفتوحة والمشروعات البحثية، وتقدير العمل وإتقانه، والمسؤولية.","والمهارات المحددة في إطار المناهج، ومنها: حل المشكلات، والاعتماد على الذات وتقديرها، وتقدير العمل وإتقانه، والشعور بالمسؤولية، والتعامل باحترام مع الآخرين؛ وتُنمّى بالمهام، كمشكلة واقعية في المدرسة يحددها الطلاب ويجمعون معلوماتها ويقترحون حلولاً ويجربون أفضلها.","وتشيع قائمة مختصرة للأبعاد تأتي في أسئلة المواقف: الهوية الوطنية، والتفكير العليا، والمهارات الحياتية، و**الثقافة الرقمية** أي الاستخدام الآمن والأخلاقي للتقنية وتقويم مصداقية المصادر، واللغة والتواصل؛ لكن نص المؤشرات المعتمد هو الأولويات والقيم والمهارات.","في الصف: طالبات يقسن استهلاك الماء في المدرسة أسبوعاً ثم يعرضن حلولاً على الإدارة ينمين التنمية المستدامة والمسؤولية وحل المشكلات معاً، ومعلم رياضيات يحسب مع طلابه ميزانية أسرة ينمي المهارات الحياتية."],"map":{"type":"fan","title":["Cross-Curricular Dimensions","الأبعاد المشتركة في المعيار الثامن"],"groups":[{"n":"الأولويات","ar":"خبرات **مباشرة أو ضمنية**","items":[{"n":"المواطنة المسؤولة"},{"n":"مكانة المملكة العربية السعودية ومكانتها الريادية"},{"n":"التنمية المستدامة"}]},{"n":"القيم الست","ar":"يراعيها المعلم في الأنشطة ويعززها","items":[{"n":"تقوى الله"},{"n":"الوسطية والاعتدال"},{"n":"تقدير الذات"},{"n":"الشغف المعرفي"},{"n":"تقدير العمل وإتقانه"},{"n":"المسؤولية"}]},{"n":"المهارات","ar":"تُنمّى بالمهام والاستراتيجيات","items":[{"n":"حل المشكلات"},{"n":"الاعتماد على الذات وتقديرها"},{"n":"تقدير العمل وإتقانه"},{"n":"الشعور بالمسؤولية"},{"n":"التعامل باحترام مع الآخرين"}]}]}}],"L14":[{"pts":["يجمع المؤشر 9.1 أمرين: ما يعتقده المعلم عن قدرة طلابه، وما يعتقده الطالب عن سبب نجاحه أو فشله؛ والتوقع العالي يعكس **إيمانه بقدرة جميع طلابه على النجاح**، لا رغبة المعلم في التنافس أو إنجازه الشخصي.","[[**أثر بجماليون**|ar.l14.expect]] (روزنثال وجاكوبسون 1968): المعلم ينتظر من يتوقع منه الكثير أطول ويكلفه بمهام أصعب، فيتحقق التوقع **نبوءة تحقق ذاتها**؛ والتوقع المنخفض يخفض التحصيل بالطريقة نفسها.","التوقع العالي تحدٍّ مع دعم و**أهداف تعلم واضحة** قابلة للتحقيق، أما التوقع **المثالي غير الواقعي** فيُحبط؛ وقارن الطالب **بأدائه السابق** لا بأقرانه، فالدافعية الداخلية أبقى من المكافآت.","[[**العزو**|ar.l14.attrib]] عند واينر تفسير الطالب لسبب نجاحه أو فشله: عزو الفشل إلى **الجهد** يزيد المثابرة لأنه سبب يتحكم فيه، وعزوه إلى ضعف القدرة الثابتة يولّد العجز المتعلم؛ و**الكفاءة الذاتية** (باندورا) أقوى مصادرها **خبرات الإتقان**.","تقدير الذات يُرفع بإبراز جوانب القوة ومهام ينجح فيها الطالب، لا بخفض المطلوب؛ وبعد الإجابة الخاطئة يلجأ المعلم إلى **إعادة صياغة السؤال** أو السبر، لا إلى إعطاء الإجابة الجاهزة.","في الصف: طالبة تقول «أنا غبية في العلوم» ← الخطوة الأولى: إعادة توجيه العزو إلى مهارة تتحسن بالتدريب مع خطة قصيرة لنجاح مبكر ← الخطأ الشائع: طمأنتها بخفض المطلوب أو مقارنتها بزميلاتها."]},{"pts":["إدارة الصف **تنظيم البيئة التعليمية** المادية والنفسية والاجتماعية ليحدث التعلم، لا مجرد ضبط ومعاقبة؛ وأنماطها ثلاثة: الديمقراطي وهو الأنسب، والتسلطي القائم على الخوف، والفوضوي الذي تضيع فيه الضوابط.","[[**القواعد الصفية**|ar.l14.styles]] قليلة (3–5) إيجابية الصياغة، توضع **مع الطلاب** بداية العام ومتسقة مع قواعد الوزارة، ويُشرح نفعها حتى يلتزموا بها ذاتياً؛ والود بلا ضوابط نمط فوضوي لا ديمقراطي.","وجد [[**كونين**|ar.l14.kounin]] أن الصف المنضبط يميزه سير الدرس لا العقاب: **اليقظة** وعي المعلم بكل ما يجري، والتداخل معالجة أمرين دون توقف الدرس، ومعهما الزخم وتنبيه المجموعة وأثر الموجة؛ و[[الانضباط الحازم|ar.l14.canter]] عند كانتر قواعد وتقدير إيجابي وعواقب متدرجة معلنة.","المقاعد تُرتب حسب **نوع النشاط** (صفوف للعرض، مجموعات للتعاون، حرف U للنقاش)، والمجموعات غير متجانسة بأدوار محددة، والمعلم **ميسّر** يتنقل بينها ويدعم عند الحاجة، ومن ينهي مبكراً يُعطى نشاطاً إثرائياً.","**الأزمة الصفية** لها ترتيب ثابت: الهدوء أولاً، ثم فصل المتسببين، ثم شغل البقية بنشاط، ثم معالجة فردية مع المتسببين بعد الحصة لا أمام الصف.","في الصف: لاحظتَ أثناء الشرح عدم انتباه عدد من الطلاب ونوم أحدهم ← الخطوة الأولى: **نشاط قصير يكسر الروتين** ثم العودة للشرح (دليل المتقدم) ← الخطأ الشائع: التهديد بالعواقب، أو التغافل، أو نقل مقاعدهم."],"map":{"type":"fan","title":["Classroom Management Styles","أنماط إدارة الصف"],"groups":[{"n":"الديمقراطي","ar":"حوار ومشاركة وأمن نفسي و**انضباط ذاتي**؛ وهو الأنسب","d":"ar.l14.styles"},{"n":"التسلطي","ar":"خوف وطاعة تامة واتكالية ودافعية خارجية","d":"ar.l14.styles"},{"n":"الفوضوي (المتساهل)","ar":"لا ضوابط وضياع الوقت؛ ومنه الود الزائد الذي يُضعف مكانة المعلم","d":"ar.l14.styles"}]}},{"pts":["يكمل المؤشر 9.2 قيادة الصف بثلاثة أمور في المعلم نفسه: [[**القدوة الحسنة**|ar.l14.ethics]]، وعلاقة ضمن **حدود مهنية**، والتراجع عن الخطأ وتصحيحه؛ فالطلاب يتعلمون مما يفعله أكثر مما يقوله.","**حدود العلاقة المهنية**: ودّ عادل دون محاباة، ولا تواصل شخصي خارج القنوات المعتمدة، ولا إفشاء لأسرار الطلاب، ولا مزاح يمس كرامتهم.","إن أخطأ المعلم في معلومة أو درجة، أو أساء إلى طالب أمام زملائه، فالأنسب أن **يعترف ويعتذر** ويصحح في أقرب وقت أمام من وصلهم الخطأ؛ فذلك يبني الثقة ولا يُضعف مكانته.","دوره في قواعد السلوك والمواظبة 1447: يباشر **الإجراءات الثلاثة الأولى من مشكلات الدرجة الأولى** (تنبيه شفهي، ثم تنبيه ثانٍ مع حصر الأسباب، ثم تدوين وتوقيع الطالب وإشعار ولي الأمر)، ثم يحيل من لم يستجب للإدارة.","ممنوع بنص القواعد (المادة 28): **نسخ الواجب عقاباً**، وإقصاء الطالب خارج الصف، والإيذاء والسخرية من شخصيته؛ و**المسميات الحالية** الموجه الطلابي ولجنة التوجيه الطلابي (المرشد ولجنة التوجيه والإرشاد سابقاً).","في الصف: طالب خرج من الفصل دون استئذان أثناء الحصة ← الخطوة الصحيحة: رصد المخالفة وتسليم اسمه للإدارة لأنها من الدرجة الثانية ← الخطأ الشائع: حسم درجاته بنفسه، أو إخراجه من الصف بقية اليوم."]},{"pts":["تعديل السلوك يبدأ بسؤالين: هل نريد أن يزيد السلوك أم يقل؟ ثم هل نضيف شيئاً أم نزيله؟ [[**التعزيز**|ar.l14.reinf]] يزيد السلوك و**العقاب** يقلله، والموجب إضافة والسالب إزالة، لا «جيد وسيئ».","التعزيز الفعال **فوري** متنوع متناسب دون إشباع؛ و[[المتواصل|ar.l14.schedules]] لاكتساب سلوك جديد، و**المتقطع** للمحافظة عليه؛ وأسهل المعززات وأكثرها استخداماً في الصف **اجتماعية** (وتسمى معنوية)، ثم نشاطية ومادية ورمزية وغذائية.","**الانطفاء/الإطفاء** حجب التعزيز عن السلوك بالتجاهل المقصود فيتلاشى، ويُقرن **بالتعزيز التفاضلي** للسلوك البديل؛ وقد يزيد السلوك مؤقتاً قبل أن يتلاشى، والتجاهل انطفاء لا عقاب.","**تكلفة الاستجابة** (خصم نقاط أو امتياز) و**الإقصاء** (إبعاد مؤقت عن النشاط المعزز، كإجلاسه جانب الملعب دقائق) عقاب سالب كلاهما؛ والممنوع بنص قواعد 1447 (المادة 28) إقصاؤه **خارج الصف**، فالطرد لا يكون جواباً لسؤال «ماذا يفعل المعلم».","[[**مبدأ بريماك**|ar.l14.premack]] نشاط محبب يُشترط بإنهاء نشاط أقل حباً، و**الاقتصاد الرمزي** رموز تُجمع ثم تُستبدل؛ و**التشكيل** تعزيز التقريبات المتتابعة، و**النمذجة** تعلم بملاحظة نموذج، ومن [[أساليب أخرى|ar.l14.othermod]] التصحيح الزائد وضبط المثير والتلقين.","في الصف: طالب يصيح «أنا أعرف!» دون رفع يده ← الخطوة الأولى: تجاهله واختيار من رفع يده وشكره (انطفاء مع تعزيز تفاضلي) ← الخطأ الشائع: تسمية التجاهل عقاباً؛ فالعقاب السالب سحب معزز موجود، والتجاهل حجب للتعزيز."],"cmp":{"title":"التعزيز والعقاب في جدول واحد","cols":["موجب (نضيف شيئاً)","سالب (نزيل شيئاً)"],"rows":[{"k":"تعزيز: يزيد السلوك","a":"نضيف محبباً: مدح، نجمة","b":"نزيل منفّراً: إلغاء إنذار، إعفاء من واجب"},{"k":"عقاب: يقلل السلوك","a":"نضيف منفّراً: توبيخ","b":"نسحب محبباً: حرمان من امتياز، تكلفة الاستجابة"}]},"ex":["طالب يحضّر دروسه ليتجنب توبيخ المعلم: زاد السلوك لأنه يزيل شيئاً يكرهه، فهذا **تعزيز سالب** لا عقاب."]},{"pts":["منطق الهيئة في البيئة الآمنة واحد: أول حادثة بسيطة يعالجها المعلم بنفسه، والمتكرر أو الخطر يُصعَّد إلى الموجه والإدارة، وكل حالة تُعالج على انفراد دون إحراج علني.","في الصف: **العنف** اللفظي لأول مرة من طلاب على زميلهم ← الخطوة الأولى: تنبيه المعتدين بأن السلوك مرفوض وله عواقب إن تكرر (دليل المتقدم) ← الخطأ الشائع: إبلاغ الإدارة والأهل (خطوة لاحقة) أو تعليم الصف مهارات اجتماعية (إجراء عام).","**التنمر** يُعالج بخطة مدرسية (الموجه والإدارة والأسرة)، و**المعتدى عليه** تُبنى ثقته ويُحمى، لا يُلام ولا يُواجه بالمتنمر أمام الصف؛ وإذا اشتكى ولي أمر من التنمر فالخطوة الأولى **الإنصات**.","في الصف: طالب خجول لا يشارك ← الخطوة الأولى: **علاقة ثقة** ومهام سهلة ينجح فيها ([[فئات الطلاب|ar.l14.cases]]) ← الخطأ الشائع: تجنب سؤاله أو تحويله فوراً للموجه؛ وكثير الحركة يُعطى حركة مشروعة، والمتحدي لقاءً فردياً.","أنجز ثم أساء: افصل **الاعتراف بالإنجاز** عن رفض السلوك («حلك صحيح، وضرب زميلك خطأ له عاقبة»)؛ و**التدخين** ولو خارج السور في الشوارع المحاذية يُبلَّغ للموجه والإدارة وفق [[قواعد السلوك والمواظبة|ar.l14.rules1447]].","ممنوع دائماً: **العقاب الجماعي** والبدني والتشهير والطرد من الفصل؛ والسلامة تبدأ **بإيقاف الخطر فوراً**، فمن يعبث بمواد المختبر يُوقف وتُبعد المواد عنه قبل أي تسجيل أو إبلاغ."],"map":{"type":"steps","title":["Escalation Ladder","سلّم التصعيد في المواقف السلوكية"],"groups":[{"n":"بسيط لأول مرة","ar":"يعالجه المعلم","c":"#1F6B4C","tag":"تجاهل مقصود أو تنبيه هادئ على انفراد مع توضيح العواقب"},{"n":"متكرر","ar":"عواقب اللائحة","c":"#A8562A","d":"ar.l14.rules1447","tag":"إشراك الموجه الطلابي وولي الأمر"},{"n":"خطر أو خارج الصلاحية","ar":"الإدارة والموجه فوراً","c":"#9B2C2C","tag":"طبي، نفسي، قانوني، ولي أمر بحالة غير طبيعية","hl":true}]}},{"pts":["الجزء المادي من المؤشر 9.3 أمران: **جاهزية مصادر التعلم** وإتاحتها لجميع الطلاب، وبيئة تحقق الأمن والسلامة في الصف والمختبر وعند الطوارئ.","افحص الأجهزة والروابط **قبل الحصة** وأعد خطة بديلة، ووفّر بدائل لضعيف البصر والسمع (خط مكبر، نص مرافق للفيديو)، وعند نقص الأدوات اجعل بينها تناوباً عادلاً.","[[**الإخلاء**|ar.l14.safety]] عند الإنذار: هدوء، وخروج منتظم عبر المسار **دون الحقائب**، ثم التحقق من العدد في نقطة التجمع؛ وفي **المختبر** نظارات وقفازات واقية، ومواد موسومة، وإشراف دائم، ومعرفة مكان طفاية الحريق.","عند الإصابة الترتيب ثابت: **إيقاف الخطر** وحماية الطلاب أولاً، ثم الإسعاف في حدود التدريب، ثم الإبلاغ والتوثيق؛ ومعرفة **الحالات الصحية** (ربو، حساسية، سكري، صرع) بالتنسيق مع الموجه الصحي.","محاولة إيذاء الذات (المادة 30 من قواعد 1447): الهدوء وأخذ كلامه بجدية، وتجنب كثرة الأسئلة، ووضعه في مكان آمن مع **عدم تركه بمفرده**، وحفظ خصوصيته، والتبليغ فوراً للجهات المختصة.","في الصف: انطلق إنذار الحريق أثناء الحصة ← الخطوة الأولى: إخراج الطلاب بهدوء عبر مسار الإخلاء دون الحقائب ثم عدّهم ← الخطأ الشائع: السماح بجمع الأغراض، أو إبقاؤهم في الفصل حتى تصل تعليمات الإدارة."]},{"pts":["المؤشر 9.4 تواصل يعزز التعلم: [[عناصر الاتصال|ar.l14.comm]] مرسل ورسالة وقناة ومستقبل و**تغذية راجعة** تميز الاتصال الحديث، وأفضل أنماطه **المتعدد (المفتوح)** الذي يتفاعل فيه الجميع بتوجيه المعلم، ومنه مجموعات التعلم الافتراضية تحت إشرافه.","التواصل **غير اللفظي** (نظرة، إيماءة، قرب، نبرة) يسبق اللفظي أثراً، وهو الأنسب للتنبيه الصامت دون إحراج ولتشجيع الطالب الخجول.","[[**زمن الانتظار**|ar.l14.questions]] 3–5 ثوانٍ بعد السؤال يرفع جودة الإجابات ومشاركة الخجولين؛ ويُطرح السؤال أولاً ثم يُختار المجيب ليبقى الجميع منتبهاً.","**الإنصات النشط** إيماء وإعادة صياغة دون مقاطعة؛ ومع الإجابة الخاطئة ابحث عن الجزء الصحيح ولا تسخر، ثم اسبر بأسئلة تقود الطالب إلى الصواب، كسؤال من ظنت أن الشمس تدور حول الأرض: «ماذا تفعل الأرض حول نفسها في يوم؟».","[[التغذية الراجعة|ar.l12.feedback]] **تراكم معرفي** متعلق بالأداء، والتعزيز تراكم وجداني؛ وأقوى صورها التعليق الفردي المحدد على الجوانب المميزة لا ملصق «أحسنت» (دليل المتقدم)، و«نجمتان وأمنية»: نقطتا قوة ونقطة تحسين.","في الصف: **ولي الأمر الغاضب** في المدرسة ← الخطوة الأولى: الإنصات وإتاحة التعبير، ثم عرض الحقائق بهدوء، ثم خطة مشتركة ← الخطأ الشائع: البدء بشرح وجهة نظرك أو مراجعة القوانين؛ وإن بدا بحالة غير طبيعية فالإدارة.","نظام **فلاندرز** يحلل التفاعل اللفظي في الصف عشر فئات: تقبّل المشاعر والمدح وتقبّل الأفكار والأسئلة كلام **غير مباشر** يوسّع مشاركة الطلاب، والشرح والتوجيهات والنقد كلام **مباشر**، ثم كلام الطلاب والصمت."]},{"pts":["أسئلة المعيار التاسع مواقف بأربعة بدائل تبدو كلها تربوية، والفاصل بينها التوقيت ومن يتأثر بالإجراء؛ وهذه القواعد التي تكررت في أقسام الدرس مجموعة في مكان واحد.","**الخطوة الأولى** تعالج الموقف الحاضر مباشرة؛ أما الإجراء العام (نموذج سلوك للجميع) أو الوقائي (تعليم مهارات) أو التبليغ فخطوات لاحقة، أي بدائل صحيحة في توقيت خاطئ.","سلّم التصعيد: أول حادثة بسيطة يعالجها المعلم، والمتكررة أو الخطرة للموجه والإدارة وولي الأمر، وما خرج عن صلاحيته (طبي، نفسي، قانوني، ولي أمر بحالة غير طبيعية) للإدارة فوراً.","عالج **السلوك لا الشخص**، على انفراد لا علناً، وعزز البديل المرغوب؛ فالتعزيز فوري والتصحيح المحرج مؤجل وخاص، وأي بديل فيه إهانة أو عقاب جماعي أو طرد من الفصل خطأ ولو بدا حازماً.","إذا جاء **بديلان مترادفان** في المعنى فكلاهما خطأ، والبديل البديهي الذي يفرضه النشاط أصلاً لا يضيف شيئاً؛ والبيئة الإيجابية تبدأ **بالعلاقة** (تحية الطلاب عند دخول الفصل، ومناداتهم بأسمائهم) قبل الأدوات والعقوبات.","مع ولي الأمر الترتيب **استمع ← افهم ← اشرح ← اتفق**؛ فلا تبدأ بشرح وجهة نظرك، ولا بمراجعة القوانين، ولا برفع الدرجات لامتصاص غضبه."],"ex":["طالبة تسخر من إجابة زميلتها لأول مرة: الخطوة الأولى تنبيهها على انفراد بأن السخرية مرفوضة ولها عواقب إن تكررت، مع دعم المتضررة؛ أما إبلاغ الإدارة أو محاضرة الصف فخطوات لاحقة أو عامة."],"map":{"type":"grid","mlist":true,"rh":true,"title":["Situation → first step → common mistake","الموقف ← الخطوة الأولى ← الخطأ الشائع"],"cols":[{"n":"الخطوة الأولى","c":"#1F6B4C"},{"n":"الخطأ الشائع","c":"#9B2C2C"}],"rows":[{"n":"«أنا غبية في العلوم»","cells":[{"n":"","ar":"توجيه العزو إلى مهارة تتحسن بالتدريب، ونجاح مبكر","c":"#1F6B4C","d":"ar.l14.attrib"},{"n":"","ar":"خفض المطلوب أو المقارنة بزميلاتها","c":"#9B2C2C"}]},{"n":"عدم انتباه ونوم أثناء الشرح","cells":[{"n":"","ar":"نشاط قصير يكسر الروتين ثم العودة للشرح","c":"#1F6B4C"},{"n":"","ar":"التهديد بالعواقب أو التغافل أو نقل المقاعد","c":"#9B2C2C"}]},{"n":"خروج دون استئذان","cells":[{"n":"","ar":"رصد المخالفة وتسليم اسمه للإدارة (درجة ثانية)","c":"#1F6B4C"},{"n":"","ar":"حسم درجاته بنفسه أو إخراجه بقية اليوم","c":"#9B2C2C"}]},{"n":"يصيح «أنا أعرف!»","cells":[{"n":"","ar":"تجاهله واختيار من رفع يده وشكره","c":"#1F6B4C"},{"n":"","ar":"تسمية التجاهل عقاباً؛ هو حجب للتعزيز","c":"#9B2C2C"}]},{"n":"عنف لفظي لأول مرة","cells":[{"n":"","ar":"تنبيه المعتدين بأن السلوك مرفوض وله عواقب","c":"#1F6B4C"},{"n":"","ar":"إبلاغ الإدارة والأهل أولاً، أو درس عام للصف","c":"#9B2C2C"}]},{"n":"طالب خجول لا يشارك","cells":[{"n":"","ar":"علاقة ثقة ومهام سهلة ينجح فيها","c":"#1F6B4C","d":"ar.l14.cases"},{"n":"","ar":"تجنب سؤاله أو تحويله فوراً للموجه","c":"#9B2C2C"}]},{"n":"إنذار حريق أثناء الحصة","cells":[{"n":"","ar":"الإخلاء بهدوء دون الحقائب ثم العدّ","c":"#1F6B4C","d":"ar.l14.safety"},{"n":"","ar":"جمع الأغراض أو انتظار تعليمات الإدارة","c":"#9B2C2C"}]},{"n":"ولي أمر غاضب","cells":[{"n":"","ar":"الإنصات ثم الحقائق بهدوء ثم خطة مشتركة","c":"#1F6B4C"},{"n":"","ar":"البدء بشرح وجهة نظرك أو مراجعة القوانين","c":"#9B2C2C"}]}]}}],"L01":[{"pts":["المعيار 1.1 يطلب أن يكون المعلم نموذجاً للقيم الإسلامية الوسطية، ومؤشراته للممارس ثلاثة: الالتزام بالقيم في المظهر والسلوك، وأنشطة تعزز الوسطية والتسامح ونبذ التطرف، وتنمية ثقافة الحوار وتقبل الاختلاف؛ ويُضاف إليها الحياد في الخلافيات من مدونة 1447.","[[الوسطية|ar.l01.wasat]] هي **الاعتدال** بين الغلو (الزيادة حتى التشدد) والتفريط (التقصير والتهاون) في الأقوال والأحكام والتعامل، والمعلم يغرس الاعتدال والتسامح والتعايش بسلوكه قبل كلامه.","المعلم **قدوة** داخل المدرسة وخارجها، و«المعلم القدوة» في الأسئلة يعني حسن التعامل مع الطلاب، والرقيب عليه بعد الله ضميره اليقظ؛ لذلك تُعلَّم القيم بالمواقف العملية لا بحصة وعظ.","في القضايا [[**الخلافية**|ar.l01.neutral]] كالمسائل الفقهية المختلف فيها والشؤون السياسية يلتزم المعلم الحياد ولا يفرض رأيه، ونص [[مدونة 1447|ar.l02.code1447]] **تجنب الدخول في نقاشات** حولها، فيحيل الطالب إلى المصادر والجهات المختصة؛ أما الثوابت فتُعلَّم بوضوح.","الطالب الجدلي الذي يشكك في الثوابت يُعالَج بـ[[**الأدلة المنطقية والقدوة العملية**|ar.l01.dialogue]]: إنصات ثم توضيح ثم شواهد تناسب عمره، لا بإغلاق باب الحوار (قمع) ولا بإحالته إلى موقع إلكتروني (تنصّل).","في الصف: رُفع الأذان أثناء الشرح، فتوقف المعلم وردده مع طلابه؛ هذه **نمذجة** للقيمة بالفعل، أما تذكيرهم بواجب المسلم ثم إكمال الشرح فوعظ لفظي يخالفه الفعل.","من أساليب **توضيح القيم** (راث وهارمن وسايمون) أن يكتشف الطالب قيمه بنفسه، ومنها **الاستجابة الموضحة**: سؤال قصير يرد به المعلم على عبارة الطالب دون وعظ أو حكم، مثل «هل ترضى أن يعاملك الآخرون كذلك؟».","**المحاكمة العقلية** تعرض قضية قيمية فيوازن الطلاب أدلة الطرفين حتى يصلوا إلى **حكم مسبَّب**، وتناسب المرحلة الثانوية لقدرة طلابها على التفكير المجرد؛ أما القصة والقدوة فأسلوبان غير مباشرين."]},{"pts":["المعيار 1.2 «تعزيز الهوية الوطنية والتنوع الثقافي» يطلب الولاء للوطن وقيادته واحترام الثقافات الأخرى، وطريق الهوية ثلاث خطوات: غرس مفهوم حب الوطن والمواطنة أولاً، ثم دعمه بشواهد يراها الطالب، ثم نقل القيمة من الإصغاء إلى السلوك.","الهوية تُعزَّز بـ**الشواهد والإحصاءات والمنجزات** المرتبطة بالدرس لا بالوعظ؛ فشواهد جهود المملكة كخدمة الحرمين والحجاج تنمي المواطنة الصالحة، وتعليق الأعلام والبرامج الثقافية وسائل تابعة لا غاية.","رموز الهوية: العلم، والنشيد، والشعار (السيفان والنخلة)، واللغة العربية، واليوم الوطني، ويوم التأسيس، والعملة؛ و[[**رؤية 2030**|ar.l01.identity]] تستهدف في التعليم جودة المخرجات والشراكة المجتمعية ومواءمته مع سوق العمل والتعلم مدى الحياة.","المواطنة قيمة وجدانية تتدرج بسلّم [[**كراثول**|ar.l01.krathwohl]]: يصغي ثم يشارك ثم يقدّر ثم ينظّم، وأعلاها **تمثّل القيمة** حين تصير سلوكاً تلقائياً، كأن يكون الطالب قدوة لأسرته.","في الصف: لترتيب أهداف المواطنة من الأدنى، «يبدي اهتمامه بحديث المعلم عن منجزات الوطن» استقبال، و«يشارك في ندوة» استجابة، و«يقدّر دور المملكة» تقدير، و«يتمثل القدوة لأسرته» أعلاها؛ والبديل الذي يبدأ بالمشاركة يتجاوز الاستقبال.","في الصف: قاطع طالب المعلم سائلاً «أيهما أهم: الأمة أم الوطن؟»؛ الأنسب حوار هادئ يبين أن حب الوطن لا يتعارض مع الانتماء للأمة، وكل خيار يُسكت الطالب أو يسخر منه خاطئ."],"map":{"type":"steps","head":true,"title":["Krathwohl — citizenship as a value","المواطنة على سلّم كراثول: من الإصغاء إلى أن تصير قدوة"],"groups":[{"n":"الاستقبال","d":"ar.l01.krathwohl","tag":"يصغي وينتبه"},{"n":"الاستجابة","d":"ar.l01.krathwohl","tag":"يشارك ويتفاعل"},{"n":"التقييم","ar":"التقدير","d":"ar.l01.krathwohl","tag":"يقدّر القيمة ويدافع عنها"},{"n":"التنظيم","d":"ar.l01.krathwohl","tag":"يوازن بين القيم عند التعارض"},{"n":"التمثّل","d":"ar.l01.krathwohl","tag":"قدوة لأسرته","hl":true,"trap":"الأعلى التمثّل والأدنى الاستقبال"}]}},{"pts":["مؤشر الممارس 1.2 ينص على أن **يوظف المعلم خبرات ومواقف وأنشطة تعليمية** تدعم الاعتزاز بالهوية الوطنية وبالتراث الثقافي الوطني، أي أن يدخل التراث في الدرس نفسه لا أن يبقى مناسبة عابرة.","التراث نوعان: [[**التراث المادي**|ar.l01.heritage]] ملموس كالمباني التاريخية والآثار والأدوات والأزياء والقطع الحرفية، و**التراث غير المادي** كالعادات والأمثال والشعر والفنون كالعرضة ومهارات الحِرف التقليدية كالسدو وآداب الضيافة.","المناسبات ثلاث: يوم التأسيس (22 فبراير) لذكرى الدولة السعودية الأولى، واليوم الوطني (23 سبتمبر) لذكرى التوحيد، ويوم العلم (11 مارس)؛ والاحتفاء بها بأنشطة هادفة لا بالمظاهر، وقواعد 1447 تعد المشاركة الإيجابية فيها من **السلوك المتميز** (الانتماء الوطني).","تنوع تراث المناطق ولهجاتها **ثراء لهوية وطنية واحدة**، والتعريف به يعزز الوحدة الوطنية؛ فإذا سخر طلاب من لهجة زميلهم وظّف المعلم الموقف لبيان هذا الثراء بشواهد، لا بعقاب علني ولا بتجاهل.","في الصف: لتعزيز الاعتزاز بالتراث في درس عن البيئة المحلية، تقابل الطالبات كبار السن لتوثيق حرفة تقليدية ويعرضنها على زميلاتهن؛ وهذا أقوى من تعليق الصور أو المحاضرة أو المطوية لأنه خبرة تعيشها الطالبة.","النشاط التراثي لا يشمل **تحويل المباني التراثية إلى حديثة** لأنه يناقض قيمة الحفاظ على التراث، أما الترميم الذي يحفظ الطابع الأصلي والفيلم الوثائقي والمطويات التوعوية فتعززها."],"map":{"type":"tree","title":["National Occasions","المناسبات الوطنية"],"groups":[{"n":"يوم التأسيس","ar":"22 فبراير","d":"ar.l01.heritage","items":[{"n":"1139هـ (1727م)","who":"الإمام محمد بن سعود","ar":"تأسيس الدولة السعودية الأولى"}]},{"n":"اليوم الوطني","ar":"23 سبتمبر","d":"ar.l01.heritage","items":[{"n":"1351هـ (1932م)","who":"الملك عبدالعزيز","ar":"توحيد المملكة"}]},{"n":"يوم العلم","ar":"11 مارس","d":"ar.l01.heritage","items":[{"n":"العلم","ar":"من رموز الهوية الوطنية"}]}]}},{"pts":["التنوع الثقافي وجود خلفيات وعادات ولغات مختلفة في الصف، والمطلوب من المعلم أمران معاً: تنمية الاعتزاز بالدين والوطن، والتفاعل الإيجابي مع الثقافات الأخرى دون تنازل عن الثوابت.","استشهاد المعلم بمثال إيجابي من ثقافة أخرى [[**يعزز ثقافة احترام الآخرين**|ar.l01.diversity]]، وهو نص مؤشر في جانب **التنوع الثقافي** من المعيار 1.2، فلا يُحسب في الأسئلة تعزيزاً للهوية الوطنية ولا إضعافاً لها؛ والآراء المتباينة مكونات ثقافية تتكامل في بناء الحضارة.","أفعل استراتيجية لفهم التنوع **نشاط عملي** يعيشه الطالب كالمقابلة أو المشروع المشترك أو عرض من زميل، لا الملصقات ولا قوائم الأعياد؛ أما **العزل حسب الثقافة** فخطأ في كل الأحوال.","في الصف: فصل متنوع الخلفيات اللغوية يتفاوت طلابه في مستوى اللغة؛ مفتاح الهيئة (المعيار 5.2) أن يجمع المعلم ذوي **المستوى المتقارب** في مجموعات صغيرة يقدمون أنشطة تناسبهم، و«إتاحة الحديث عن محتوى الدرس» مشتت لأنه لا يعالج تفاوت المستويات.","في الصف: زميل غير مسلم في مهمة عمل يُعامَل **وفق مقتضيات مهام العمل** باتزان واحترام، فلا يُدعى في كل لقاء ولا يُحال إلى مراكز الدعوة ولا يُقاطَع؛ وحسن المعاملة نفسه قدوة."]},{"pts":["**المواطنة الرقمية** هي الممارسة الآمنة والقانونية والأخلاقية للتقنية، ويحكمها [[نظام مكافحة الجرائم المعلوماتية|ar.l01.techcode]] (1428هـ) وباب التقنية في مدونة 1447، والأسئلة عنها تدور حول المراسلة والصور ومصداقية المصادر.","من أخلاقيات المراسلة: **تعريف النفس بوضوح**، ومراعاة حقوق النشر، والاعتذار عن الرسالة المرسلة خطأ؛ أما إخفاء الهوية، والتصرف في وثيقة وصلت بالخطأ، والرسائل المتكررة للتنبيه فمخالفات.","صور الطلاب وبياناتهم أمانة: قبل نشر أي صورة تأتي [[**مراجعة ما تتطلبه لوائح الوزارة لنشر الصور**|ar.l01.privacy]] أولاً، ثم إذن ولي الأمر، ثم النشر عبر القنوات الرسمية للمدرسة.","مصداقية الموقع الإلكتروني تُعرف بـ**وجود معلومات مُعدّ الموقع وإمكانية التأكد منها**، لا بعدد الروابط فيه ولا بجمال العرض.","في الصف: أعجب معلماً نشاطُ طلابه فأراد تصويرهم ونشر المقطع في حسابه الشخصي؛ المدونة (المادة 21) تمنعه من ذلك، فيرفع النشاط لإدارة المدرسة لتنشره عبر قنواتها وفق ضوابط الوزارة."]}],"L02":[{"pts":["ثلاث وثائق تتكلم عن أخلاق المعلم: [[الميثاق|ar.l02.mithaq]] وثيقة قيم يسميها المعيار 1.3 صراحة، و[[مدونة 1447|ar.l02.code1447]] قواعد ملزمة بواجبات و[[محظورات|ar.l02.prohibited]] ومساءلة، و[[مدونة الوظيفة العامة|ar.l02.civilcode]] إطار عام لكل موظفي الدولة.","إذا ذُكر في السؤال طلاب أو أولياء أمور أو اختبارات فالمرجع الأدق مدونة 1447، وإذا سُئلت عن قيم المهنة وأهدافها فالمرجع الميثاق الصادر **1427هـ**، وأخلاقيات المهنة فيه «السجايا الحميدة والسلوكيات الفاضلة».","من أهداف الميثاق **الإسهام في تعزيز مكانة المعلم العلمية والاجتماعية** وتعزيز انتمائه لرسالته، وهي أهداف للميثاق لا لسياسة التعليم؛ و[[النمو المهني|ar.l03.pd]] فيه **واجب أساس** على المعلم لا خيار شخصي.","مع طلابه: **العدل** وصون الكرامة وحفظ أسرارهم و[[تجنب العقاب البدني والنفسي|ar.l02.rifq]]؛ ومع الأسرة: المعلم [[شريك الوالدين|ar.l04.parentcomm]] في التربية؛ ومع الزملاء والإدارة: الثقة المتبادلة والعمل بروح الفريق.","في الصف: اختلف معلمون في المدرسة حول أمر مهني، فالحل **مراجعة ميثاق أخلاقيات مهنة التعليم** في المملكة، لا المواثيق العالمية ولا حكم المدير ولا أن يقرر كل منهم ما يقتنع به.","واستجابة المعلم الإيجابية أو السلبية لمواقف مهنته تسمى **اتجاهه نحو المهنة**، وهو جانب وجداني يظهر مثلاً في مشاركته المستمرة الهادفة في نشاطات المدرسة."]},{"pts":["[[سياسة التعليم|ar.l02.policy]] «الخطوط العامة» للتعليم في المملكة، صدرت بقرار مجلس الوزراء **779** وتاريخ 1389/9/16هـ وتشتهر باسم «سياسة التعليم 1390هـ»، وفيها 236 مادة؛ فسنة الوثيقة 1390 وتاريخ قرارها 1389.","أسسها الإيمان بالله رباً وبالإسلام ديناً وبمحمد ﷺ نبياً، وغاية التعليم فيها **فهم الإسلام فهماً صحيحاً متكاملاً** وغرس العقيدة وتزويد الطالب بالقيم والمعارف والمهارات.","السلم فيها ابتدائي 6 ومتوسط 3 وثانوي 3، ومن مبادئها **التربية المتكاملة** التي تعد المواطن المؤمن إعداداً شاملاً لجوانب شخصيته، وحق الفتاة في التعليم، وسياسة شاملة لرعاية ذوي الاحتياجات الخاصة.","في الصف: معلم يخطط أنشطته لتنمو شخصية الطالب جسمياً وعقلياً ونفسياً واجتماعياً وروحياً معاً؛ هذا مبدأ التربية المتكاملة، لا «التربية للحياة» ولا «تكافؤ الفرص».","**مستجد:** ألغاها قرار مجلس الوزراء 103 (1448هـ) مع بقاء أحكامها سارية حتى يصدر البديل، والنظام الذي حلّ محلها في القسم التالي."]},{"pts":["نظام التعليم العام صدر بالمرسوم الملكي م/36 في 68 مادة، والمطلوب منه ثلاثة أمور: متى يُعمل به، وماذا ألغى قرار الموافقة عليه، وما أحكامه الكبرى في الإلزام والمراحل وذوي الإعاقة والموهوبين.","**منشور ولم يُطبَّق بعد:** نُشر في أم القرى **1448/2/10هـ**، ويُعمل به [[بعد 180 يوماً من نشره|ar.law.effective]] (المادة 68)، أي نحو يناير 2027؛ والمدة تُحسب من النشر لا من تاريخ المرسوم.","قرار الموافقة عليه (مجلس الوزراء 103) [[ألغى سياسة التعليم 1390|ar.law.repeal]] بانتقال منظم، فأحكامها **سارية حتى يُقر البديل** خلال سنة من نفاذ النظام؛ و[[مجلس شؤون التعليم العام|ar.law.council]] برئاسة **وزير التعليم** يحدد سن القبول ويعمل **من تاريخ النشر**.","ثلاثة حدود لا تُخلط: [[**الإلزام من 6 إلى 15**|ar.law.compulsory]] (المادة 4)، والتعليم العام حتى نهاية الصف 12 و[[مراحله|ar.law.defs]] الحضانة ورياض الأطفال والصفوف 1–12، و**الطفولة المبكرة** حتى **نهاية الصف الثالث** (المادة 1)؛ والتعليم **مجاني في المؤسسات الحكومية** (المادة 3).","ذوو الإعاقة: [[الدمج أولاً|ar.law.inclusion]] والمراكز لمن يتعذر دمجه؛ والموهوبون: برامج و[[التسريع|ar.law.gifted]] بتقويم شامل وتنسيق مع ولي الأمر؛ وفيه [[12 هدفاً|ar.law.goals]] و[[إطار وطني للمناهج|ar.law.curriculum]] وأحكام عامة.","في الصف: ولي أمر يطلب أن يدرس ابنه عن بُعد طوال العام بحجة أن التقنية متاحة؛ من [[أحكام النظام الأخرى|ar.law.general]] أن التعليم **حضوري** والتقنية جزء منه لا بديل عنه، والعربية أساس مع جواز لغة إضافية."]},{"pts":["يخاطب النظام خمسة أطراف كما في الخريطة: الطالب والمعلم وإدارة المدرسة والمدرسة الخاصة والأسرة، ولكل طرف حقوق وواجبات، ثم يأتي باب الجزاءات لمن يخالف.","للطالب [[سبعة حقوق وخمسة التزامات|ar.law.srights]] (المادة 38)، منها بيئة آمنة نفسياً وجسدياً وفكرياً، وسماع شكواه وقيدها واتخاذ الإجراء، وتسلّم شهادة النجاح دون قيد أو شرط.","وللمعلم [[حقوق وواجبات|ar.law.teacher]] (المادتان 48 و 49): التطوير المهني حق وواجب، ومن واجباته العدالة ومراعاة الفروق والقدوة داخل المدرسة وخارجها؛ وعلى إدارة المدرسة [[واجب الإبلاغ|ar.law.report]] عن أي اعتداء داخلها أو في محيطها.","[[الجزاءات|ar.law.penalties]] تفرق بين حالتين: عند **قرائن** الإخلال بالنظام العام أو اللحمة الوطنية تُتخذ تدابير عاجلة مثل كف اليد مؤقتاً، وعند **ثبوت** المخالفة الجسيمة إنهاء الخدمة والمنع من العودة للتعليم العام والخاص.","التظلم من الجزاء أمام **الجهة القضائية خلال 60 يوماً** (المادة 63)، و**الحكم القضائي النهائي** بجريمة مخلة بالأمانة أو الشرف يُنهي الخدمة (المادة 64)؛ والمدرسة الخاصة المخالفة تُغرَّم من 5,000 إلى 50,000 ريال، وطلب ترخيصها يُرد عليه كتابياً خلال 30 يوماً.","في الصف: ألزم معلم طلابه بشراء أدوات باهظة لمشروع لم يرد في الخطة وهدّد بحسم درجات من لا يحضرها؛ هذا يخالف حق الطالب ألا يُكلَّف بعمل ناتج عن اجتهاد فردي (المادة 38/1/د)."],"map":{"type":"fan","title":["Who the law addresses","أطراف النظام: الحقوق والواجبات"],"groups":[{"n":"الطالب","ar":"7 حقوق منها الأمان النفسي والجسدي والفكري، وسماع شكواه وقيدها، وشهادة النجاح **دون قيد أو شرط** (م 38).","d":"ar.law.srights"},{"n":"المعلم","ar":"العدالة والفروق الفردية، والقدوة والالتزام بالميثاق **داخل المدرسة وخارجها** (م 49).","d":"ar.law.teacher","items":[{"n":"القدوة والميثاق","d":"ar.law.ethics"}]},{"n":"إدارة المدرسة","ar":"**تبلغ الجهة المختصة** عن أي إيذاء داخلها أو في محيطها لطلابها أو منسوبيها (م 65).","d":"ar.law.report"},{"n":"المدرسة الخاصة","ar":"ترخيص الوزارة **خلال 30 يوماً**، وتدريس مواد الهوية الوطنية، وغرامة 5,000–50,000 ريال (م 32، 31، 60).","d":"ar.law.license"},{"n":"الأسرة","ar":"شريك؛ الوزارة تضع ضوابط مشاركة أولياء الأمور (م 50).","d":"ar.law.general"}]}},{"pts":["أكبر فرق: السياسة **«خطوط عامة»** للتعليم كله ومنه الجامعات، والنظام **أحكام ملزمة** فيها حقوق وجزاءات، وخاص **بالتعليم العام** حتى الصف 12؛ والجدول يقارنهما بنداً بنداً.","ما أضافه النظام ولم تعرفه السياسة: سن إلزام من 6 إلى 15، وقائمة حقوق للطالب (المادة 38)، وباب للمخالفات والجزاءات مع واجب الإبلاغ عن الإيذاء (المواد 57–65).","وما تغيّر: المجانية صارت في المؤسسات الحكومية بعد أن كانت في كل الأنواع والمراحل، والجهة العليا صارت مجلس شؤون التعليم العام، والتعليم الخاص صار يشمل الاستثمار الأجنبي مع تدريس مواد الهوية الوطنية.","في الصف: سألت معلمة جديدة عن وضع سياسة التعليم بعد صدور النظام؛ الجواب أنها أُلغيت بقرار الموافقة على النظام، مع بقاء أحكامها سارية حتى يقر المجلس بديلها خلال سنة، فعبارة «أُلغيت فوراً» خطأ."],"cmp":{"title":"ما الذي تغيّر؟","cols":["سياسة التعليم 1390","نظام التعليم العام 1448"],"rows":[{"k":"طبيعة الوثيقة","tag":"تغيّر","a":"«الخطوط العامة» التي تقوم عليها التربية والتعليم (م 1)، **236 مادة في 9 أبواب** بقرار مجلس الوزراء 779.","b":"**نظام** بمرسوم ملكي م/36، **68 مادة في 9 فصول**، فيه جزاءات (ف 8) ولوائح تنفيذية بقرار الوزير (م 67)."},{"k":"النطاق والمراحل","tag":"تغيّر","a":"التعليم كله: من الحضانة ورياض الأطفال إلى **التعليم العالي** (م 108–149)؛ ابتدائي 6 ومتوسط 3 وثانوي 3 (م 120، 124، 127).","b":"**التعليم العام فقط** حتى نهاية الصف 12، ومراحله الحضانة ورياض الأطفال والصفوف 1–12 (م 1)."},{"k":"الطفولة المبكرة","tag":"تغيّر","a":"دور الحضانة ورياض الأطفال **تشجعها الدولة** وتشرف عليها الجهة المختصة (م 116–117).","b":"جزء من التعليم العام، و«الطفولة المبكرة» من الحضانة حتى **نهاية الصف الثالث** (م 1)."},{"k":"الجهة العليا","tag":"تغيّر","a":"«مجلس أعلى للتعليم» يشرف على التعليم بكافة أنواعه ومراحله (م 231).","b":"[[مجلس شؤون التعليم العام|ar.law.council]] برئاسة **وزير التعليم** (م 7)، يقر السياسات واللوائح (م 8)."},{"k":"الإلزام وسن القبول","tag":"أُضيف","a":"لا سن إلزام؛ الابتدائي «متاح لكل من بلغ سن التعليم» (م 121).","b":"**إلزام من 6 إلى 15** وإجراءات تجاه من يحرم الطفل (م 4)، و**سن القبول يحدده المجلس** (م 8/2)."},{"k":"المجانية","tag":"تغيّر","a":"التعليم **مجاني في كافة أنواعه ومراحله** (م 233).","b":"مجاني **في المؤسسات الحكومية** (م 3)، والخاص يحدد رسومه وفق معايير يعتمدها المجلس (م 35)."},{"k":"تعليم البنات","tag":"تغيّر","a":"يُمنع الاختلاط في جميع المراحل **إلا في دور الحضانة ورياض الأطفال** (م 155).","b":"مدارس البنات مستقلة **بعد مرحلة الطفولة المبكرة**، ويجوز استثناء الخاص بضوابط يعتمدها مجلس الوزراء (م 6)."},{"k":"ذوو الإعاقة والموهوبون","tag":"تغيّر","a":"تعليم المعوقين **«وفق إمكانياتها»** بمناهج خاصة (م 188)، ورعاية النابغين (م 192–194).","b":"[[الدمج أولاً|ar.law.inclusion]] ومراكز لمن يتعذر دمجه (م 20–21)، وبرامج للموهوبين و**التسريع** (م 22–23)."},{"k":"التعليم الأهلي والأجنبي","tag":"تغيّر","a":"ترخيص الأهلي للجهات المختصة **ولا يُسمح به لغير السعوديين** (م 176).","b":"ترخيص الوزارة (م 32)، ويشمل الخاص **الاستثمار الأجنبي**، مع تدريس **مواد الهوية الوطنية** (م 31)."},{"k":"المعلم","tag":"تغيّر","a":"إعداد المعلم وتدريبه المستمر وكادر خاص (م 163–172)، واختيار القائمين على التعليم بالكفاية والخلق (م 195).","b":"حقوق للمعلم (م 48) وواجبات منها [[الالتزام بميثاق أخلاقيات مهنة التعليم|ar.law.ethics]] داخل المدرسة وخارجها (م 49)."},{"k":"حقوق الطالب","tag":"أُضيف","a":"لا قائمة حقوق؛ من أهداف الابتدائية تنمية وعيه بما له من حقوق وما عليه من واجبات (م 79).","b":"[[سبعة حقوق وخمسة واجبات|ar.law.srights]] منصوصة (م 38)."},{"k":"المخالفات والجزاءات","tag":"أُضيف","a":"","b":"[[تدابير عاجلة وجزاءات|ar.law.penalties]] حتى إنهاء الخدمة، وغرامات على الخاص، و[[واجب الإبلاغ|ar.law.report]] (م 57–65)."}]}},{"pts":["[[لائحة الوظائف التعليمية|ar.l02.jobsreg]] تنظم المسار الوظيفي للمعلم في 38 مادة: الرتب والتعيين والتجربة والنصاب والترقية، وتعمل معها [[**الرخصة المهنية**|ar.l02.license]] التي تصدرها **هيئة تقويم التعليم والتدريب** لا وزارة التعليم.","صدرت اللائحة عام 1440هـ بقرار وزير الخدمة المدنية (سابقاً) رقم 2481 وتاريخ 1440/10/9هـ كما تنص مقدمة مدونة 1447، أما نسبتها إلى قرار مجلس الوزراء 601 فلا يسندها نص رسمي.","الرتب في المادة 3 أربعة بنود: معلم خبير، ثم معلم متقدم، ثم معلم ممارس، ثم «معلم/مساعد معلم» في بند واحد؛ فالأسماء خمسة كما في الخريطة، و«معلم» لمن سُكّن عليها عند نفاذ اللائحة بمؤهل دون الجامعي.","الرخصة **إلزامية لمزاولة التعليم** منذ فبراير 2026 (تعديل 1446) ويُعفى من بلغ الخمسين قبله، وصلاحيتها **خمس سنوات**؛ والمعيّن ابتداءً **تحت التجربة سنتين**، والتعيين ابتداءً على ممارس لحامل الجامعية أو مساعد معلم (المادة 5).","مستوى الرخصة يحتاج ثلاثة شروط: المؤهل المناسب، و**سنوات الخبرة**، واختباران ساريان بدرجة المستوى في **الاختبارين معاً** (50 ممارس، 70 متقدم، 80 خبير)، ومستوياتها أربعة أولها «رخصة معلم» لحامل الدبلوم؛ و[[الترقية|ar.l02.jobsmore]] تحتاج رخصة سارية، والحد الأدنى من نقاط التطوير المهني، وتقويم أداء جيد جداً فأعلى، وسنوات الرتبة (6 بكالوريوس، 5 ماجستير، 4 دكتوراه، وتنقص سنة من متقدم إلى خبير).","في الصف: معلم حصل على 82 في التربوي العام و 74 في التخصص؛ أعلى رخصة تؤهله لها درجته «متقدم»، لأن المستوى مطلوب في الاختبارين فتُقرأ الدرجة الأدنى ولا يُوزَن بينهما، مع شرط سنوات الخبرة."],"map":{"type":"steps","title":["Teacher Ranks","رتب المعلمين: الاجتياز والنصاب"],"brackets":[{"from":1,"to":4,"n":"بالرخصة المهنية: 50 فأعلى في الاختبارين معاً"}],"groups":[{"n":"مساعد معلم","ar":"ثانوية ودبلوم سنة","d":"ar.l02.jobsreg"},{"n":"معلم","ar":"دون الجامعي","d":"ar.l02.license","tag":"رخصة معلم · نصاب 24"},{"n":"معلم ممارس","ar":"اجتياز 50","d":"ar.l02.license","tag":"نصاب 24 · يبدأ به التعيين الجامعي","hl":true},{"n":"معلم متقدم","ar":"اجتياز 70","d":"ar.l02.license","tag":"نصاب 22"},{"n":"معلم خبير","ar":"اجتياز 80","d":"ar.l02.license","tag":"نصاب 18"}]}},{"pts":["[[الإصدار الخامس|ar.l02.grades]] من قواعد السلوك والمواظبة (1447هـ) ألغى ما سبقه، وللطالب فيه من الصف الثالث الابتدائي درجتان منفصلتان: **درجة السلوك 100** و**المواظبة 100 درجة**، ولكل منهما طريقة حسم، وللصفين الأول والثاني تقدير كيفي.","درجة السلوك 80 للسلوك الإيجابي يستحقها الطالب تلقائياً وتُحسم عند المخالفة، و 20 للسلوك المتميز تُكتسب بممارسات كالتسامح والأمانة والانتماء الوطني؛ و**درجات الحسم** تتبع درجة المشكلة، ومعها فرص تعويض لا تعفي من الإجراءات.","**التدرج**: يُطبَّق الإجراء التالي عند تكرار المشكلة نفسها، وإذا ارتكب الطالب أكثر من مشكلة في وقت واحد تُتخذ إجراءات المشكلة الأعلى درجة.","المواظبة من الثالث الابتدائي: تُحسم درجة عن كل يوم غياب بدون عذر، وتجاوز الغياب بدون عذر 10% يحرم من الانتقال؛ والعذر يُقدَّم خلال **ثلاثة أيام عمل**، ويُشعَر ولي الأمر بالغياب في اليوم نفسه.","في الصف: تغيب طالب يوماً بلا عذر مقبول، فيُحسم من مواظبته درجة واحدة لا خمس، ولا يُحرم من الاختبار مباشرة؛ والموجه الطلابي لا يرصد هذه الدرجات ولا يحسمها، بل يدرس حالة متكرر الغياب."],"map":{"type":"steps","head":true,"title":["Behavior problem degrees (1447)","درجات مشكلات السلوك وما يُحسم لكل درجة"],"groups":[{"n":"الأولى","d":"ar.l02.grades","tag":"حسم 1"},{"n":"الثانية","d":"ar.l02.grades","tag":"حسم 2"},{"n":"الثالثة","d":"ar.l02.grades","tag":"حسم 3"},{"n":"الرابعة","d":"ar.l02.grades","tag":"حسم 10","hl":true},{"n":"الخامسة","d":"ar.l02.grades","tag":"حسم 15","hl":true,"trap":"التعويض بالسلوك المتميز لا يعفي من الإجراءات"}]}},{"pts":["مواقف الأنظمة في الاختبار تسأل عن الخطوة الصحيحة، وقاعدتها: الإجراء المعتمد في القواعد قبل الاجتهاد، والإدارة أولاً في كل ما يخص معلومات الطالب أو خروجه، والجدول يبين ما تغيّر في قواعد 1447.","اعتداء طالب على زميله بالضرب: الإجراءات المعتمدة **إشعار ولي الأمر** وتعهد خطي، ثم النقل إلى فصل آخر بقرار لجنة التوجيه الطلابي إذا تكررت المشكلة؛ أما عقابه أمام زملائه فليس منها.","طالب يدخن خارج السور: [[**إبلاغ المرشد الطلابي ومدير المدرسة**|ar.l02.committee]] (اسمه الرسمي اليوم: الموجه الطلابي)، لا التجاهل لأنه خارج المدرسة ولا التوبيخ العلني، فالقواعد تشمل الشوارع المحاذية إذا رصدها منسوبو المدرسة.","في الصف: اتصل أخصائي نفسي من عيادة خارجية يطلب معلومات عن طالب؛ الخطوة الأولى [[**التحدث مع إدارة المدرسة واتباع تعليماتها**|ar.l01.privacy]]، لا إرسال السجلات ولا إعداد سجل غير رسمي، وإذن الطالب وحده لا يكفي.","ولي أمر يريد أخذ ابنه أثناء الحصة يُحال إلى **إدارة المدرسة** لأن الاستئذان إجراء إداري؛ ودليل [[القواعد|ar.l02.behavior]] يُسلَّم لولي الأمر ويوقّع بالعلم، وعند المخالفة يوقّع على العقد السلوكي أو التعهد.","قواعد ضبط الصف التي يتفق عليها المعلم مع طلابه، كرفع اليد قبل السؤال، تكون **متسقة مع قواعد الانضباط التي أقرتها الوزارة**، لا مع معلمي المدرسة الآخرين ولا مع توقعات أولياء الأمور."],"cmp":{"title":"ما تغيّر في قواعد السلوك والمواظبة 1447 (الإصدار الخامس)","cols":["الإصدارات السابقة","قواعد 1447"],"rows":[{"k":"اسم اللجنة","a":"لجنة التوجيه والإرشاد","b":"لجنة التوجيه الطلابي","tag":"تغيّر"},{"k":"المختص بدراسة الحالة","a":"المرشد الطلابي","b":"الموجه الطلابي، ولا يشارك في رصد الدرجات ولا تنفيذ الإجراءات","tag":"تغيّر"},{"k":"النطاق خارج السور","a":"الطرقات المحيطة لطلاب المتوسطة والثانوية","b":"حدود المدرسة (الشوارع المحاذية) لجميع الطلاب إذا رصدها منسوبو المدرسة أو كاميراتها، والتعليم الإلكتروني والحافلات والأنشطة","tag":"تغيّر"},{"k":"درجة السلوك","a":"—","b":"100: إيجابي 80 تُحسم منه، ومتميز 20 تُكتسب، مع فرص تعويض","tag":"أُضيف"}]}}],"L04":[{"pts":["[[**مجتمع التعلم المهني**|ar.l04.plc]] مهنيون في المدرسة يعملون بشكل مخطط ومستمر، وهدفه **تفعيل تعاون المعلمين لتحسين تعلم الطلاب**، ومبادئه أربعة: تشارك الرؤية والقيم والأهداف، وثقافة التعاون، والتركيز على تعلم الطلاب، والتركيز على النتائج.","هو عملي لا نظري، فالمفهوم الخاطئ عنه أنه **يُعنى بالجوانب النظرية**؛ و[[أوعيته|ar.l04.plcforms]] منها البحوث الإجرائية والتوأمة المهنية والتدريب بالأقران والشبكات المهنية.","يُشكَّل حسب **الصفوف التي يدرسونها** لا حسب الأعمار أو سنوات الخبرة، ويحلل النتائج بأسئلة عن الأسئلة والفصول (أين أخطأ الطلاب؟ لماذا اختلفت الفصول؟) لا عمّن حصل على أعلى الدرجات.","في الصف: يلتقي معلمو الصف الخامس بانتظام لمناقشة استراتيجيات تساعد من يجد صعوبة في الرياضيات؛ الفائدة في مفتاح الهيئة **تقديم تعليم مناسب لجميع أنواع ومستويات الطلاب**، لا مكافأة المعلمين ولا المقارنة بينهم.","مع الزملاء: الخلاف أو الغيرة من زميل متميز يُعالج بـ**اقتراح مبادرات جماعية للعمل كفريق**، والنقد يُقابَل بالصبر؛ وللمعلمين المستجدين يوفر مجتمع التعلم البيئة الداعمة والإسناد."]},{"pts":["التواصل مع ولي الأمر شراكة في مصلحة الطالب، فالأصل أن يستقبله المعلم ويهتم بلقائه؛ والقاعدة في مواقفه: اسمع أولاً، واختر وسيلة ثنائية الاتجاه للنقاش، وأحِل إلى المختص أو الإدارة ما ليس من صلاحيتك.","ولي الأمر الغاضب: [[**الإنصات أولاً**|ar.l04.angry]] ثم العرض، فشرح وجهة نظرك ومراجعة اللوائح خطوات لاحقة؛ والغاضب من مستوى ابنه يُواجَه بهدوء ومنطق وحياد وبأدلة من أعماله، لا برفع الدرجات.","في الصف: اتصل والد منزعج يرى أن ابنه عوقب ظلماً، فطلب المعلم مقابلته؛ يبدأ المقابلة بإتاحة الفرصة للأب ليعبّر عن رأيه ومشاعره وفهمه لما حصل، لأن البدائل الأخرى خطوات صحيحة في توقيت خاطئ.","لمناقشة التقدم وتبادل الآراء: [[**عقد اجتماع لمناقشة الأهداف المشتركة**|ar.l04.parentcomm]]، لأن الملاحظات المكتوبة ودفتر المتابعة تواصل في اتجاه واحد؛ والتقارير هدفها **توضيح مستوى الطالب وتقدمه** بلغة بسيطة وموجزة، والسؤال الحاكم: ماذا أريد من ولي الأمر أن يعرف؟","سؤال عن صعوبات التعلم: **طلب موعد اجتماع مع مختص صعوبات التعلم**، فالتشخيص ليس من صلاحية المعلم؛ وشكوى التنمر: [[استماع ثم متابعة مع الموجه الطلابي|ar.l02.rifq]] (المرشد سابقاً)؛ وطلب أخذ الابن أثناء الحصة: إدارة المدرسة لأنه إجراء إداري.","نتائج صف كامل متدنية تُبحث في [[مجالس أولياء الأمور|ar.l04.family]]، ووالد الطالب المخالف يُعان بـ**تزويده بلائحة القواعد السلوكية لتدريب ابنه في المنزل**؛ ومزايا الاجتماعات لا تشمل **إشراك أولياء الأمور في تقويم المعلمين**، ومخاطبة المدير بـ[[خطاب إداري|ar.l04.parenttools]] رسمي."]},{"pts":["مؤشر الممارس 3.2: **يستخلص أبرز معوقات التواصل مع أولياء الأمور** ويشارك في اللقاءات التي تستهدف التغلب عليها؛ والمعوقات من جهتين: الأسرة كالوقت واللغة والتجربة السابقة، والمدرسة كالاستدعاء عند المشكلات فقط.","الخريطة تقابل كل معوّق بحله: مرونة المواعيد، ورسائل إيجابية دورية، ولغة بسيطة، والإنصات قبل العرض، وتنويع القنوات، وإشراك الأسرة في الأنشطة؛ والسؤال يطلب الحل عادة لا اسم المعوّق.","ولي أمر لا يستجيب: **يُحلَّل السبب أولاً** (وقت؟ لغة؟ تجربة سابقة؟) ثم يُختار الحل المناسب له، لا تكرار الاستدعاء بالطريقة نفسها.","قواعد 1447 تجعل من **دور الأسرة** حضور الاجتماعات ومجالس أولياء الأمور والتواصل الفوري مع المدرسة عند غياب الابن، ولجنة التوجيه الطلابي هي التي تعقد مجلس أولياء الأمور.","في الصف: أغلب أولياء أمور فصل لا يحضرون اللقاءات المسائية لأن كثيراً منهم يعملون مساءً؛ الأنسب تنويع قنوات التواصل ومواعيده كاللقاءات الافتراضية والرسائل الدورية، لا الاكتفاء بإرسال الدرجات النهائية آخر الفصل."],"map":{"type":"grid","mlist":true,"rh":true,"title":["Barriers to parent communication & their fixes","كل حل يعالج معوّقاً: من جهة الأسرة أو المدرسة"],"colsTitle":["المعوّق"],"rowsTitle":["الحل"],"cols":[{"n":"من جهة الأسرة","c":"#4A5953"},{"n":"من جهة المدرسة","c":"#4A5953"}],"rows":[{"n":"مرونة المواعيد","cells":[{"n":"","ar":"انشغال وضيق وقت","c":"#4A5953"},{"n":"","ar":"مواعيد غير مناسبة","c":"#4A5953"}]},{"n":"رسائل إيجابية دورية","cells":[{"n":"","ar":"تجربة سلبية سابقة","c":"#4A5953"},{"n":"","ar":"استدعاء عند المشكلات فقط","c":"#4A5953"}]},{"n":"لغة بسيطة","cells":[{"n":"","ar":"ضعف القراءة أو اختلاف اللغة","c":"#4A5953"},{"n":"","ar":"تقارير مليئة بالمصطلحات","c":"#4A5953"}]},{"n":"الإنصات قبل العرض","cells":[{"n":"","ar":"حرج من مستوى الابن","c":"#4A5953"},{"n":"","ar":"أسلوب لوم أو استعلاء","c":"#4A5953"}]},{"n":"تنويع القنوات","cells":[null,{"n":"","ar":"قناة واحدة","c":"#4A5953"}]},{"n":"إشراك الأسرة في الأنشطة","cells":[{"n":"","ar":"«التعليم مسؤولية المدرسة وحدها»","c":"#4A5953"},null]}]}},{"pts":["[[**الشراكة المجتمعية**|ar.l04.partnership]] إسهام الأسر والمؤسسات بالفكر والمشورة والموارد في تطوير التعليم، في علاقة **تبادلية** تأخذ فيها المدرسة من مجتمعها وتعطيه، وتنميتها هدف في رؤية 2030.","**مقومات الشراكة**: احترام متبادل، وتقدير جهود المعلمين، ومسؤولية مشتركة بين المدرسة والأسرة والقطاعين العام والخاص والجامعات؛ ومن نتائجها اتجاهات أفضل نحو المدرسة وتسرب أقل ومعنويات أعلى للمعلمين.","الأنشطة غير الصفية **اختيارية** تناسب ميول الطلاب، ولا تُقصر على داخل المدرسة، وأعمال الطلاب المعروضة من عملهم هم؛ فجعلها إلزامية أو موحدة للجميع يناقض فلسفتها.","في الصف: كلّف معلم طلابه بتنظيف الحديقة والمسجد المجاورين للمدرسة؛ الأنسب **تكليف الطلاب بتقرير عما عملوه وتقييمهم**، لا مكافأتهم بالانصراف المبكر لأنه تعزيز في غير محله.","مشاركة المعلم في فعاليات الحي **تكسبه خبرات تدعم تعلم طلابه وتفاعلهم مع المجتمع** ولا تخرج عن الإطار المهني، وهو في الميثاق عضو مؤثر في مجتمعه."]},{"pts":["مؤشر 3.3: [[**يتقصى القضايا المحلية ويوظفها في التدريس بصورة تعزز وظيفة المعرفة**|ar.l04.local]]، أي أن يستعمل الطالب ما تعلمه ليفهم مشكلة في بيئته ويقترح لها حلاً، والعمل فيه خطوتان: تقصٍّ ثم توظيف.","**التقصي** من الأخبار المحلية والإحصاءات الرسمية والأسر والمؤسسات القريبة، و**التوظيف** يربط القضية بهدف الدرس: بيانات حقيقية في الرياضيات، أو تجربة في العلوم، أو نص في اللغة.","الضوابط: أن تناسب القضية عمر الطلاب، وتخلو من التشهير بأشخاص أو جهات، ولا تتحول الحصة إلى موعظة؛ والأثر تعلم ذو معنى ومسؤولية مجتمعية.","في الصف: معلم رياضيات يدرّس النسبة المئوية لاحظ في نشرة محلية ارتفاع استهلاك المياه في الحي؛ التوظيف الأنسب أن يحسب الطلاب نسب الهدر من بيانات أسرهم ويقترحوا طرقاً للترشيد، لا موعظة عن الإسراف بدل الدرس."]}]};
window.__dataDone&&window.__dataDone("lesson");